window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s29-20","number":20,"surah":29,"verses":[17],"verseLabel":"العنكبوت: 17","question":"ما سرّ ترتيب ﴿فَابْتَغُوا عِنْدَ اللَّهِ الرِّزْقَ وَاعْبُدُوهُ وَاشْكُرُوا لَهُ﴾؟","answer":"نقل طلب الرزق إلى مالكه، ثم رتب العبادة والشكر على الاعتراف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص150–170.","url":""}]},{"id":"s29-21","number":21,"surah":29,"verses":[17],"verseLabel":"العنكبوت: 17","question":"ما سرّ التعبير في قول إبراهيم ﴿وَاشْكُرُوا لَهُ﴾ بدل «واشكروه»؟","answer":"ذكر المبحث أن الفعل إذا قصد به إسداء الشكر إلى المنعم عُدي باللام، بخلاف شكر النعمة نفسها؛ فاللام توجه الشكر خالصًا لله صاحب الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص150–170.","url":""}]},{"id":"s29-22","number":22,"surah":29,"verses":[18],"verseLabel":"العنكبوت: 18","question":"ما سرّ التعبير بـ﴿وَإِلَيْهِ تُرْجَعُونَ﴾ في الآية 17، وبـ﴿وَإِلَيْهِ تُقْلَبُونَ﴾ في الآية 18؟","answer":"جاء ﴿ترجعون﴾ في ختام دعوة إبراهيم إلى طلب الرزق من الله وعبادته، تقريرًا للمرجع؛ وجاء ﴿تقلبون﴾ بعدها لإبراز التحول والانصراف القهري إلى المصير الآخر. وقد فُتح مبحثا الآيتين 17 و18.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص150–185.","url":""}]},{"id":"s29-23","number":23,"surah":29,"verses":[19],"verseLabel":"العنكبوت: 19","question":"ما سرّ التعبير بـ﴿أَوَلَمْ يَرَوْا كَيْفَ يُبْدِئُ اللَّهُ الْخَلْقَ ثُمَّ يُعِيدُهُ﴾؟","answer":"جعل الخلق المشاهد دليلًا على الإعادة؛ من بدأ بلا مثال لا تعجزه الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص186–199.","url":""}]},{"id":"s29-24","number":24,"surah":29,"verses":[20],"verseLabel":"العنكبوت: 20","question":"ما سرّ الجمع بين السير والنظر في ﴿سِيرُوا فِي الْأَرْضِ فَانْظُرُوا كَيْفَ بَدَأَ الْخَلْقَ﴾؟","answer":"جمع حركة الجسد ونظر العقل؛ آثار الحياة والأمم توسع الدليل خارج الأفق القريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص200–217.","url":""}]},{"id":"s29-25","number":25,"surah":29,"verses":[20],"verseLabel":"العنكبوت: 20","question":"ما سرّ إظهار اسم الله في ﴿ثُمَّ اللَّهُ يُنْشِئُ النَّشْأَةَ الْآخِرَةَ﴾؟","answer":"جدّد إسناد الخلق إليه عند الانتقال من المشاهدة إلى البعث الذي أنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص200–217.","url":""}]},{"id":"s29-26","number":26,"surah":29,"verses":[22],"verseLabel":"العنكبوت: 22","question":"ما سرّ زيادة ﴿وَلَا فِي السَّمَاءِ﴾ في نفي الإعجاز؟","answer":"استوعب النفي الأرض والسماء لإزالة كل توهم بالفرار من قدرة الله، حتى لو قدر لهم الالتحاق بالسماء؛ فليس لهم مهرب في أي جهة. صيغ السؤال على الآية نفسها من غير إحالة مقارنة مجهولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص229–242.","url":""}]},{"id":"s29-27","number":27,"surah":29,"verses":[23],"verseLabel":"العنكبوت: 23","question":"ما سرّ التعبير بالماضي في ﴿أُولَئِكَ يَئِسُوا مِنْ رَحْمَتِي﴾؟","answer":"صور اليأس يوم القيامة كأنه تحقق وثبت بسبب كفرهم السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص243–258.","url":""}]},{"id":"s29-28","number":28,"surah":29,"verses":[24],"verseLabel":"العنكبوت: 24","question":"ما دلالة جواب قوم إبراهيم ﴿اقْتُلُوهُ أَوْ حَرِّقُوهُ﴾؟","answer":"حين عجزوا عن البرهان لم يبق إلا إسكات صاحبه بالقوة، وتدرجوا إلى أشدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص259–287.","url":""}]},{"id":"s29-29","number":29,"surah":29,"verses":[25],"verseLabel":"العنكبوت: 25","question":"ما سرّ التعبير في قول إبراهيم ﴿إِنَّمَا اتَّخَذْتُمْ مِنْ دُونِ اللَّهِ أَوْثَانًا مَوَدَّةَ بَيْنِكُمْ﴾؟","answer":"كشف التعبير أن رابطة المودة الاجتماعية في الحياة الدنيا هي التي أمسكت جماعتهم على عبادة الأوثان، ثم تنقلب هذه المودة يوم القيامة إلى تبرؤ ولعن.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص259–287.","url":""}]},{"id":"s29-30","number":30,"surah":29,"verses":[26],"verseLabel":"العنكبوت: 26","question":"ما سرّ التعبير في قول إبراهيم ﴿إِنِّي مُهَاجِرٌ إِلَى رَبِّي﴾؟","answer":"جعل الهجرة انتقالًا إلى رعاية الله وطاعته، لا مجرد خروج من مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص288–306.","url":""}]},{"id":"s29-31","number":31,"surah":29,"verses":[27],"verseLabel":"العنكبوت: 27","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا فِي ذُرِّيَّتِهِ النُّبُوَّةَ وَالْكِتَابَ﴾؟","answer":"بعد ترك إبراهيم قومه عوضه الله امتداد الهداية في ذريته، لا مكسبًا وقتيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص288–306.","url":""}]},{"id":"s29-32","number":32,"surah":29,"verses":[29],"verseLabel":"العنكبوت: 29","question":"ما سرّ الجمع في خطاب لوط بين إتيان الرجال وقطع السبيل وإتيان المنكر في النادي؟","answer":"جمع فساد الشهوة وأمن الطريق والمجال العام؛ لم تبق الجريمة شأنًا فرديًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص307–333.","url":""}]},{"id":"s29-33","number":33,"surah":29,"verses":[31],"verseLabel":"العنكبوت: 31","question":"ما دلالة قول إبراهيم عن لوط عند خبر إهلاك القرية؟","answer":"لما أخبرت الملائكة بإهلاك أهل القرية راجع إبراهيم في شأن لوط، فطمأنوه بأن الله أعلم بمن فيها وأنه سينجي لوطًا وأهله إلا امرأته؛ فالسياق عناية بالمؤمن لا اعتراض على الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص334–343.","url":""}]},{"id":"s29-34","number":34,"surah":29,"verses":[33],"verseLabel":"العنكبوت: 33","question":"ما سرّ الجمع بين ﴿سِيءَ بِهِمْ﴾ و﴿ضَاقَ بِهِمْ ذَرْعًا﴾ في وصف لوط؟","answer":"جمع الألم النفسي والعجز عن حماية الضيوف؛ والذراع صورة للطاقة التي ضاقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص355–366.","url":""}]},{"id":"s29-35","number":35,"surah":29,"verses":[35],"verseLabel":"العنكبوت: 35","question":"ما سرّ التعبير بـ﴿وَلَقَدْ تَرَكْنَا مِنْهَا آيَةً بَيِّنَةً﴾؟","answer":"أبقى من القرية أثرًا يرى، فتحولت القصة إلى شاهد مكاني للعقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص374–377.","url":""}]},{"id":"s29-36","number":36,"surah":29,"verses":[38],"verseLabel":"العنكبوت: 38","question":"ما سرّ التعبير عن عاد وثمود بـ﴿وَقَدْ تَبَيَّنَ لَكُمْ مِنْ مَسَاكِنِهِمْ﴾؟","answer":"آثارهم في طرق العرب حجة مشاهدة؛ الزينة الشيطانية حالت دون قراءة الأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص389–401.","url":""}]},{"id":"s29-37","number":37,"surah":29,"verses":[38],"verseLabel":"العنكبوت: 38","question":"ما سرّ تقديم عاد على ثمود في ﴿وَعَادًا وَثَمُودَ﴾؟","answer":"جاء ترتيب عاد ثم ثمود على سبق الوجود التاريخي؛ فعاد أقدم، ثم جاءت ثمود بعدها، فوافق ترتيب الذكر ترتيب الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص389–401.","url":""}]},{"id":"s29-38","number":38,"surah":29,"verses":[40],"verseLabel":"العنكبوت: 40","question":"ما سرّ جمع مصارع الأمم في ﴿فَكُلًّا أَخَذْنَا بِذَنْبِهِ﴾؟","answer":"اختلاف العقوبات ووحدة السبب يثبتان عدل السنة الإلهية وتنوع القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص412–421.","url":""}]},{"id":"s29-39","number":39,"surah":29,"verses":[41],"verseLabel":"العنكبوت: 41","question":"ما سرّ تشبيه اتخاذ الأولياء ببيت العنكبوت؟","answer":"شبه حال من يتخذ من دون الله أولياء بحال العنكبوت التي تتخذ بيتًا تطلب به الحماية، مع أنه أوهن البيوت؛ فالمثل لفساد الاعتماد وعجز المتخذ، لا لمجرد رقة خيوط البيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص422–434.","url":""}]},{"id":"s29-40","number":40,"surah":29,"verses":[41],"verseLabel":"العنكبوت: 41","question":"ما سرّ التعبير بـ﴿وَإِنَّ أَوْهَنَ الْبُيُوتِ لَبَيْتُ الْعَنْكَبُوتِ لَوْ كَانُوا يَعْلَمُونَ﴾؟","answer":"ليس وجه المثل خفاء ضعف الخيط، بل ضعف البيت من جهة الاعتماد والحماية؛ فقوله ﴿لو كانوا يعلمون﴾ ينفي عن المشركين العلم النافع بحقيقة ما اتخذوه من أولياء، لا مجرد المعرفة الحسية ببيت العنكبوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص422–434.","url":""}]},{"id":"s29-41","number":41,"surah":29,"verses":[43],"verseLabel":"العنكبوت: 43","question":"ما سرّ التعبير بـ﴿وَمَا يَعْقِلُهَا إِلَّا الْعَالِمُونَ﴾؟","answer":"العقل هنا إدراك وجه المثل والعبور من صورته إلى حجته؛ ولذلك خُص به العالمون الذين يتدبرون مواقع الأمثال، لا من يحفظ ألفاظها فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص443–448.","url":""}]},{"id":"s29-42","number":42,"surah":29,"verses":[45],"verseLabel":"العنكبوت: 45","question":"ما دلالة قوله تعالى ﴿إِنَّ الصَّلَاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ﴾؟","answer":"عرض المبحث أن الصلاة المقامة بحقها تزجر صاحبها وتذكره بالله، وأن أثر النهي يتأكد بحسب حضور القلب والمحافظة عليها؛ فالآية تقرر خاصيتها التربوية ولا تجعل كل صورة صلاة مانعًا آليًا من المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص454–466.","url":""}]},{"id":"s29-43","number":43,"surah":29,"verses":[45],"verseLabel":"العنكبوت: 45","question":"ما أوجه معنى ﴿وَلَذِكْرُ اللَّهِ أَكْبَرُ﴾ بعد بيان أثر الصلاة؟","answer":"ذكر المبحث أوجهًا، منها أن ذكر الله في الصلاة أكبر مقاصدها، وأن ذكر الله لعبده وثناءه عليه أكبر من ذكر العبد؛ لذلك لا يحصر اللفظ في تفسير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص454–466.","url":""}]},{"id":"s29-44","number":44,"surah":29,"verses":[46],"verseLabel":"العنكبوت: 46","question":"ما سرّ التعبير بـ﴿وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ﴾؟","answer":"لأن المقصود كشف الحق لا هزيمة الخصم، واستثنى الظالم الذي يفسد طريق الحوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص468–485.","url":""}]},{"id":"s29-45","number":45,"surah":29,"verses":[46],"verseLabel":"العنكبوت: 46","question":"ما سرّ التعبير بـ﴿وَإِلَهُنَا وَإِلَهُكُمْ وَاحِدٌ﴾؟","answer":"بدأ من أصل مشترك يبطل توهم صراع الآلهة ويفتح باب تصحيح ما اختلفوا فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص468–485.","url":""}]},{"id":"s29-46","number":46,"surah":29,"verses":[48],"verseLabel":"العنكبوت: 48","question":"ما سرّ التعبير بـ﴿وَمَا كُنْتَ تَتْلُو مِنْ قَبْلِهِ مِنْ كِتَابٍ وَلَا تَخُطُّهُ بِيَمِينِكَ﴾؟","answer":"نفى القراءة والكتابة قبل الوحي ليقطع دعوى نقله من الكتب، وخص اليمين لأنها أداة الخط المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص502–517.","url":""}]},{"id":"s29-47","number":47,"surah":29,"verses":[49],"verseLabel":"العنكبوت: 49","question":"ما سرّ التعبير بـ﴿بَلْ هُوَ آيَاتٌ بَيِّنَاتٌ فِي صُدُورِ الَّذِينَ أُوتُوا الْعِلْمَ﴾؟","answer":"نقل موضع حفظه من الصحف إلى الصدور الحية، فكان إعجازه محفوظًا في جماعة العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص518–528.","url":""}]},{"id":"s29-48","number":48,"surah":29,"verses":[50],"verseLabel":"العنكبوت: 50","question":"ما دلالة طلبهم آيات أخرى مع قيام حجة القرآن؟","answer":"قصروا الآية على الخارق الحسي، فردهم إلى سلطان الله وإلى كفاية الكتاب المتلو المستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص529–539.","url":""}]},{"id":"s29-49","number":49,"surah":29,"verses":[51],"verseLabel":"العنكبوت: 51","question":"ما سرّ الاستفهام في ﴿أَوَلَمْ يَكْفِهِمْ أَنَّا أَنْزَلْنَا عَلَيْكَ الْكِتَابَ يُتْلَى عَلَيْهِمْ﴾؟","answer":"ميزة القرآن أن آيته باقية تتجدد تلاوتها، بخلاف خوارق تنقضي مشاهدتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص540–553.","url":""}]},{"id":"s29-50","number":50,"surah":29,"verses":[52],"verseLabel":"العنكبوت: 52","question":"ما سرّ التعبير بـ﴿كَفَى بِاللَّهِ بَيْنِي وَبَيْنَكُمْ شَهِيدًا﴾؟","answer":"حين ردوا الآية جعل علم الله بالوحي والتكذيب شهادة تكفي عن شروطهم المتعنتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص554–567.","url":""}]},{"id":"s29-51","number":51,"surah":29,"verses":[54],"verseLabel":"العنكبوت: 54","question":"ما سرّ التعبير بـ﴿وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكَافِرِينَ﴾ قبل وقوع العذاب؟","answer":"أسبابها وحكمها قد أحاطا بهم، فلا يخرجهم تأخر ظهورها من سلطانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص568–588.","url":""}]},{"id":"s29-52","number":52,"surah":29,"verses":[56],"verseLabel":"العنكبوت: 56","question":"ما سرّ التعبير بـ﴿يَا عِبَادِيَ الَّذِينَ آمَنُوا إِنَّ أَرْضِي وَاسِعَةٌ فَإِيَّايَ فَاعْبُدُونِ﴾؟","answer":"إذا ضاق موضع العبادة فملك الله أوسع؛ وتقديم ﴿إياي﴾ يحصر العبودية ولو كلفت الهجرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص589–600.","url":""}]},{"id":"s29-53","number":53,"surah":29,"verses":[57],"verseLabel":"العنكبوت: 57","question":"ما سرّ تعقيب الأمر بالهجرة بقوله ﴿كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ﴾؟","answer":"أزال خوف الموت الذي يمنع الخروج: الموت واقع في الوطن والهجرة، ثم المرجع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص589–600.","url":""}]},{"id":"s29-54","number":54,"surah":29,"verses":[58],"verseLabel":"العنكبوت: 58","question":"ما سرّ التعبير بـ﴿لَنُبَوِّئَنَّهُمْ مِنَ الْجَنَّةِ غُرَفًا تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ﴾؟","answer":"قابل ترك الوطن بمسكن رفيع دائم، وتحتَه أسباب النعيم الجارية.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص601–612.","url":""}]},{"id":"s29-55","number":55,"surah":29,"verses":[60],"verseLabel":"العنكبوت: 60","question":"ما سرّ التعبير بـ﴿وَكَأَيِّنْ مِنْ دَابَّةٍ لَا تَحْمِلُ رِزْقَهَا اللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ﴾؟","answer":"احتج على خوف رزق الهجرة بمخلوقات لا تدخر قوتها، ومع ذلك يصلها رزقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص613–621.","url":""}]},{"id":"s29-56","number":56,"surah":29,"verses":[61],"verseLabel":"العنكبوت: 61","question":"ما دلالة إقرارهم بأن الله خلق السماوات وسخر الشمس ثم انصرافهم عن التوحيد؟","answer":"أظهر التناقض بين إقرار الخلق وصرف العبادة؛ النتيجة لا تتبع مقدمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص622–631.","url":""}]},{"id":"s29-57","number":57,"surah":29,"verses":[62],"verseLabel":"العنكبوت: 62","question":"ما دلالة قوله تعالى ﴿يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ لَهُ﴾؟","answer":"إضافة ﴿مِنْ عِبَادِهِ﴾ تذكّر بأن جميع الخلق عباده، مؤمنهم وكافرهم، وأن بسط الرزق وتقديره جارٍ عليهم بعلمه؛ فلا يصح قصرها على تطمين المهاجرين وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص632–640.","url":""}]},{"id":"s29-58","number":58,"surah":29,"verses":[63],"verseLabel":"العنكبوت: 63","question":"ما دلالة إقرارهم بـ﴿الْحَمْدُ لِلَّهِ﴾ بعد نزول المطر ثم وصف أكثرهم بأنهم لا يعقلون؟","answer":"لسانهم يقر بالمنعم في موضع، لكن عقلهم لا يعبر من النعمة إلى توحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص641–652.","url":""}]},{"id":"s29-59","number":59,"surah":29,"verses":[64],"verseLabel":"العنكبوت: 64","question":"ما سرّ وصف الدنيا بـ﴿لَهْوٌ وَلَعِبٌ﴾ والآخرة بـ﴿لَهِيَ الْحَيَوَانُ﴾؟","answer":"الدنيا تشغل بما يزول، أما «الحيوان» فالحياة الكاملة الدائمة التي لا موت فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص653–670.","url":""}]},{"id":"s29-60","number":60,"surah":29,"verses":[65],"verseLabel":"العنكبوت: 65","question":"ما دلالة إخلاصهم الدعاء في الفلك ثم إشراكهم بعد النجاة؟","answer":"الخطر يسقط أوهام الوسائط، لكن الألفة تعيدها بعد الأمن؛ فالمشهد يكشف علم الفطرة وخيانة السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص671–686.","url":""}]},{"id":"s29-61","number":61,"surah":29,"verses":[67],"verseLabel":"العنكبوت: 67","question":"ما سرّ التذكير بالحرم الآمن والناس يتخطفون من حولهم؟","answer":"أمنهم الاستثنائي نعمة مشاهدة من الله، فكيف يقابلونه بالإيمان بالباطل والكفر بها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص696–714.","url":""}]},{"id":"s29-62","number":62,"surah":29,"verses":[69],"verseLabel":"العنكبوت: 69","question":"ما سرّ ختم السورة بـ﴿وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا﴾؟","answer":"عادت إلى فتنة المطلع: الهداية الأعمق ثمرة مجاهدة صادقة، و«سبلنا» تعدد طرق الخير مع وحدة الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص730–740.","url":""}]},{"id":"s30-1","number":1,"surah":30,"verses":[1],"verseLabel":"الروم: 1","question":"ما وجه افتتاح سورة الروم بـ﴿الم﴾ قبل خبر غلبة الروم؟","answer":"افتتحت السورة بالحروف المقطعة التي نبهت إلى شأن القرآن وتحديه، ثم جاء خبر الروم بالغيب القريب؛ فاجتمع في المطلع التنبيه إلى الوحي ووعد سيقع في زمن معلوم، من غير حصر معنى الحروف في تفسير جازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص741–763.","url":""}]},{"id":"s30-2","number":2,"surah":30,"verses":[2],"verseLabel":"الروم: 2","question":"ما سرّ إسناد ﴿غُلِبَتِ﴾ إلى ﴿الرُّومُ﴾ بالتأنيث؟","answer":"رُوعي في اسم الروم معنى الأمة أو الجماعة، فجاز تأنيث الفعل المسند إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص753–763.","url":""}]},{"id":"s30-3","number":3,"surah":30,"verses":[2],"verseLabel":"الروم: 2","question":"ما سرّ تعريف ﴿الرُّومُ﴾؟","answer":"للعهد؛ الأمة المعروفة للدولة الرومية التي تابع العرب خبر حربها.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص753–763.","url":""}]},{"id":"s30-4","number":4,"surah":30,"verses":[3],"verseLabel":"الروم: 3","question":"ما أوجه معنى ﴿فِي أَدْنَى الْأَرْضِ﴾؟","answer":"عرض المبحث أن الأدنى يحتمل الأقرب، أي أقرب أرض الروم إلى العرب، وذُكر فيه أيضًا معنى الانخفاض؛ فلا يحصر اللفظ في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص753–763.","url":""}]},{"id":"s30-5","number":5,"surah":30,"verses":[3,4],"verseLabel":"الروم: 3-4","question":"ما سرّ الجمع بين الإخبار بانقلاب الغلبة وتحديده بـ﴿فِي بِضْعِ سِنِينَ﴾؟","answer":"حدد انقلابًا مخالفًا للظاهر وزمنًا محدودًا، فصار وقوعه شاهدًا على صدق الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص753–763.","url":""}]},{"id":"s30-6","number":6,"surah":30,"verses":[4],"verseLabel":"الروم: 4","question":"ما سرّ التعبير بـ﴿لِلَّهِ الْأَمْرُ مِنْ قَبْلُ وَمِنْ بَعْدُ﴾؟","answer":"نزع النصر من استقلال القوى؛ تدبير الله قائم قبل الهزيمة وبعد الانتصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص764–776.","url":""}]},{"id":"s30-7","number":7,"surah":30,"verses":[4,5],"verseLabel":"الروم: 4-5","question":"ما وجه فرح المؤمنين بنصر الروم؟","answer":"لأن الروم أهل كتاب أقرب إلى المؤمنين من فارس الوثنية، ولتحقق وعد الله أمام شماتة المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص764–776.","url":""}]},{"id":"s30-8","number":8,"surah":30,"verses":[6],"verseLabel":"الروم: 6","question":"ما سرّ توكيد الوعد في ﴿وَعْدَ اللَّهِ لَا يُخْلِفُ اللَّهُ وَعْدَهُ﴾؟","answer":"أظهر الاسم بدل الضمير وكرر الوعد لتثبيت النبوءة حين بدت بعيدة في ميزان السياسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص777–783.","url":""}]},{"id":"s30-9","number":9,"surah":30,"verses":[7],"verseLabel":"الروم: 7","question":"ما سرّ التعبير بـ﴿يَعْلَمُونَ ظَاهِرًا مِنَ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"لم ينف العلم كله؛ أثبت لهم قشرة من تدبير الدنيا، ونفى ما وراءها من الغاية والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص784–795.","url":""}]},{"id":"s30-10","number":10,"surah":30,"verses":[7],"verseLabel":"الروم: 7","question":"ما سرّ تكرار الضمير في ﴿وَهُمْ عَنِ الْآخِرَةِ هُمْ غَافِلُونَ﴾؟","answer":"قوّى حصر الغفلة فيهم وعجب من اجتماع الدقة الدنيوية والعمى عن المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص784–795.","url":""}]},{"id":"s30-11","number":11,"surah":30,"verses":[8],"verseLabel":"الروم: 8","question":"لماذا دعاهم إلى التفكر ﴿فِي أَنْفُسِهِمْ﴾؟","answer":"الإنسان أقرب دليل إليه؛ وجوده وفناؤه يكشفان أن الخلق بالحق وإلى أجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص10–21.","url":""}]},{"id":"s30-12","number":12,"surah":30,"verses":[9],"verseLabel":"الروم: 9","question":"لماذا سأل ﴿أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنْظُرُوا﴾؟","answer":"انتقل من النفس إلى التاريخ المشاهد؛ قوة الأمم لم تمنع عاقبة التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص22–38.","url":""}]},{"id":"s30-13","number":13,"surah":30,"verses":[10],"verseLabel":"الروم: 10","question":"لماذا كانت عاقبة المسيئين ﴿السُّوأَى﴾؟","answer":"جاءت صيغة المؤنث من الأسوأ بمعنى العاقبة الأشد سوءًا، لأنها ثمرة التكذيب والاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص39–49.","url":""}]},{"id":"s30-14","number":14,"surah":30,"verses":[11],"verseLabel":"الروم: 11","question":"ما سرّ تكرار ﴿اللَّهُ يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ﴾؟","answer":"جعل البداية التي لا ينكرونها جسرًا عقليًا إلى الإعادة، ثم إلى الرجوع للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص50–55.","url":""}]},{"id":"s30-15","number":15,"surah":30,"verses":[12],"verseLabel":"الروم: 12","question":"ما سرّ التعبير بـ﴿يُبْلِسُ الْمُجْرِمُونَ﴾؟","answer":"الإبلاس سكوت اليائس المنقطع الحجة؛ تفاجئهم الساعة بما لا جواب له.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص56–59.","url":""}]},{"id":"s30-16","number":16,"surah":30,"verses":[14],"verseLabel":"الروم: 14","question":"ما سرّ التعبير بـ﴿يَوْمَئِذٍ يَصَّدَّعُونَ﴾؟","answer":"يتفرقون فرقًا لا تلتئم: أهل الجنة وأهل السعير، بعد اجتماعهم في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص66–69.","url":""}]},{"id":"s30-17","number":17,"surah":30,"verses":[15],"verseLabel":"الروم: 15","question":"ما سرّ التعبير عن المؤمنين بـ﴿فَهُمْ فِي رَوْضَةٍ يُحْبَرُونَ﴾؟","answer":"الروضة تجمع حسن المنظر، و«يحبرون» سرور يظهر أثره عليهم ويتجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص70–75.","url":""}]},{"id":"s30-18","number":18,"surah":30,"verses":[17,18],"verseLabel":"الروم: 17-18","question":"ما سرّ توزيع أوقات التسبيح والحمد في الآيتين 17–18؟","answer":"أحاط تحولات اليوم بالذكر، حتى لا يمر زمن الانتقال بلا تنزيه وحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص89–105.","url":""}]},{"id":"s30-19","number":19,"surah":30,"verses":[17],"verseLabel":"الروم: 17","question":"ما سرّ تقديم المساء على الصباح في ﴿حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ﴾؟","answer":"ذكر المبحث أن المساء متقدم على الصباح في الاعتبار الشرعي واللغوي لابتداء اليوم من الليل، فجاء ترتيب الذكر موافقًا لذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص89–105.","url":""}]},{"id":"s30-20","number":20,"surah":30,"verses":[19],"verseLabel":"الروم: 19","question":"ما سرّ الجمع بين ﴿يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ﴾؟","answer":"عرض اتجاهي القدرة المتقابلين ليقرب إخراج الناس من الأرض بعد موتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص106–117.","url":""}]},{"id":"s30-21","number":21,"surah":30,"verses":[20],"verseLabel":"الروم: 20","question":"ما سرّ التعبير بـ﴿خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ إِذَا أَنْتُمْ بَشَرٌ تَنْتَشِرُونَ﴾؟","answer":"«إذا» تفاجئ بالقفزة من أصل ساكن إلى بشر يعمرون الأرض ويتكاثرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص118–128.","url":""}]},{"id":"s30-22","number":22,"surah":30,"verses":[21],"verseLabel":"الروم: 21","question":"ما سرّ التعبير بـ﴿مِنْ أَنْفُسِكُمْ أَزْوَاجًا﴾؟","answer":"من الجنس نفسه لتتحقق الألفة والفهم والسكون، لا مجرد بقاء النوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص129–147.","url":""}]},{"id":"s30-23","number":23,"surah":30,"verses":[21],"verseLabel":"الروم: 21","question":"ما سرّ الجمع بين السكن والمودة والرحمة في آية الأزواج؟","answer":"السكن حاجة النفس، والمودة رابطة الاختيار، والرحمة تحفظ العلاقة عند ضعف الدوافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص129–147.","url":""}]},{"id":"s30-24","number":24,"surah":30,"verses":[22],"verseLabel":"الروم: 22","question":"لماذا جعل اختلاف الألسنة والألوان آية؟","answer":"من أصل إنساني واحد تتولد لغات وهيئات لا تحصى بلا اختلاط يزيل التميز.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص148–161.","url":""}]},{"id":"s30-25","number":25,"surah":30,"verses":[22],"verseLabel":"الروم: 22","question":"من المراد بـ﴿الْعَالِمِينَ﴾ في قوله ﴿إِنَّ فِي ذَلِكَ لَآيَاتٍ لِلْعَالِمِينَ﴾؟","answer":"فسر المبحث ﴿لِلْعَالِمِينَ﴾ بجمع عالم، أي أهل العلم والنظر؛ لأن العالم أقرب إلى الاعتبار من الجاهل. لذلك حُذف من جواب البنك التفريق غير المنضبط بينها وبين «العلماء».","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص148–161.","url":""}]},{"id":"s30-26","number":26,"surah":30,"verses":[23],"verseLabel":"الروم: 23","question":"لماذا جعل النوم بالليل والنهار آية؟","answer":"لم يقيده بزمن واحد لأن حاجة الأبدان وأعمال الناس تتنوع، وكل نوم وانبعاث شاهد تدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص162–177.","url":""}]},{"id":"s30-27","number":27,"surah":30,"verses":[24],"verseLabel":"الروم: 24","question":"ما سرّ الجمع بين البرق خوفًا وطمعًا؟","answer":"المشهد الواحد يخيف من الصاعقة ويطمع في المطر، فجمع أثرين متضادين بقدرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص178–194.","url":""}]},{"id":"s30-28","number":28,"surah":30,"verses":[25],"verseLabel":"الروم: 25","question":"ما سرّ التعبير بـ﴿وَمِنْ آيَاتِهِ أَنْ تَقُومَ السَّمَاءُ وَالْأَرْضُ بِأَمْرِهِ﴾؟","answer":"الثبات الذي يبدو طبيعيًا قيام مستمر بأمره، ثم الدعوة الواحدة تخرج الناس من الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص195–211.","url":""}]},{"id":"s30-29","number":29,"surah":30,"verses":[26],"verseLabel":"الروم: 26","question":"ما سرّ ختم ﴿كُلٌّ لَهُ قَانِتُونَ﴾؟","answer":"كل الموجودات خاضعة لنظامه، فشذوذ الإنسان بالشرك لا يغير حقيقة ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص212–236.","url":""}]},{"id":"s30-30","number":30,"surah":30,"verses":[27],"verseLabel":"الروم: 27","question":"ما أوجه معنى ﴿وَهُوَ أَهْوَنُ عَلَيْهِ﴾ مع استواء الأشياء في قدرة الله؟","answer":"عرض المبحث أوجهًا: أن معنى ﴿أهون﴾ هين، أو أن الضمير يعود إلى المخلوق فتكون الإعادة أهون عليه، أو أن الخطاب جرى على قياس البشر في أن الإعادة أيسر من الابتداء؛ ولا يدل شيء من ذلك على تفاوت قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص212–236.","url":""}]},{"id":"s30-31","number":31,"surah":30,"verses":[28],"verseLabel":"الروم: 28","question":"لماذا ضرب لهم مثلًا من أنفسهم في شركائهم من المماليك؟","answer":"احتج بما لا يقبلونه لأنفسهم: لا يسوون خدمهم بأنفسهم، فكيف يجعلون خلقه شركاء له؟","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص237–260.","url":""}]},{"id":"s30-32","number":32,"surah":30,"verses":[30],"verseLabel":"الروم: 30","question":"ما سرّ التعبير بـ﴿فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا﴾؟","answer":"إقامة الوجه توجه كامل ثابت، و«حنيفًا» ميل عن الشرك إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص278–299.","url":""}]},{"id":"s30-33","number":33,"surah":30,"verses":[30],"verseLabel":"الروم: 30","question":"ما سرّ تسمية الدين ﴿فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا﴾؟","answer":"أصل التوحيد موافق للاستعداد الذي خلق في الإنسان، والانحراف طارئ عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص278–299.","url":""}]},{"id":"s30-34","number":34,"surah":30,"verses":[31,32],"verseLabel":"الروم: 31-32","question":"لماذا نهى عن الذين فرقوا دينهم وكانوا شيعًا؟","answer":"التوحيد يجمع الوجهة، أما اتباع الهوى فيجزئ الحق أحزابًا يفرح كل منها بما لديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص300–325.","url":""}]},{"id":"s30-35","number":35,"surah":30,"verses":[33],"verseLabel":"الروم: 33","question":"لماذا إذا مس الناس ضر دعوا ربهم منيبين ثم يشرك فريق؟","answer":"الشدة تكشف علم الفطرة، والرخاء يكشف سلطان العادة والمصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص326–344.","url":""}]},{"id":"s30-36","number":36,"surah":30,"verses":[36],"verseLabel":"الروم: 36","question":"ما دلالة فرحهم بالرحمة وقنوطهم عند إصابتهم بسيئة بما قدمت أيديهم؟","answer":"وصف تقلبهم مع الظاهر العاجل؛ لا يقرؤون النعمة شكرًا ولا المصيبة مراجعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص352–373.","url":""}]},{"id":"s30-37","number":37,"surah":30,"verses":[37],"verseLabel":"الروم: 37","question":"لماذا جعل بسط الرزق وقدره آية؟","answer":"تقلب الرزق رغم تشابه السعي يوقظ إلى تدبير فوق الأسباب، ويختبر الشكر والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص352–373.","url":""}]},{"id":"s30-38","number":38,"surah":30,"verses":[38],"verseLabel":"الروم: 38","question":"ما سرّ التعبير بـ﴿فَآتِ ذَا الْقُرْبَى حَقَّهُ﴾ بعد الحديث عن الرزق؟","answer":"من علم أن البسط من الله أدى حق المال، ولم يتوهم أنه ملك ذاتي بلا واجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص374–383.","url":""}]},{"id":"s30-39","number":39,"surah":30,"verses":[39],"verseLabel":"الروم: 39","question":"ما سرّ التعبير بـ﴿وَمَا آتَيْتُمْ مِنْ رِبًا لِيَرْبُوَ فِي أَمْوَالِ النَّاسِ فَلَا يَرْبُو عِنْدَ اللَّهِ﴾؟","answer":"فرّق بين زيادة الرقم وزيادة القيمة عند الله؛ ما طلب به عوض الناس لا يزكو.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص384–393.","url":""}]},{"id":"s30-40","number":40,"surah":30,"verses":[39],"verseLabel":"الروم: 39","question":"ما سرّ المقابلة بين الربا والزكاة في الآية؟","answer":"الربا يبدو ناميًا وهو ممحوق البركة، والزكاة تبدو نقصًا ويضاعف الله أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص384–393.","url":""}]},{"id":"s30-41","number":41,"surah":30,"verses":[40],"verseLabel":"الروم: 40","question":"لماذا رتب ﴿خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ﴾؟","answer":"اختصر دورة الوجود التي لا يشارك فيها معبود، ثم سألهم مواجهة هذا العجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص394–402.","url":""}]},{"id":"s30-42","number":42,"surah":30,"verses":[41],"verseLabel":"الروم: 41","question":"ما سرّ التعبير بـ﴿ظَهَرَ الْفَسَادُ فِي الْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتْ أَيْدِي النَّاسِ﴾؟","answer":"عمم مجال الأثر، ونسبه إلى كسبهم ليصلحوا السبب بدل الاكتفاء بالشكوى من النتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص403–411.","url":""}]},{"id":"s30-43","number":43,"surah":30,"verses":[41],"verseLabel":"الروم: 41","question":"ما سرّ التعبير بـ﴿لِيُذِيقَهُمْ بَعْضَ الَّذِي عَمِلُوا﴾؟","answer":"العقوبة الدنيوية عينة لا استيفاء، غايتها أن يرجعوا قبل الجزاء الأكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص403–411.","url":""}]},{"id":"s30-44","number":44,"surah":30,"verses":[42],"verseLabel":"الروم: 42","question":"ما سرّ إعادة الأمر بالسير بعد ذكر الفساد؟","answer":"ليقرؤوا التاريخ بوصفه نتيجة للشرك، لا حوادث منفصلة عن الأخلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص412–419.","url":""}]},{"id":"s30-45","number":45,"surah":30,"verses":[43],"verseLabel":"الروم: 43","question":"ما سرّ التعبير بـ﴿فَأَقِمْ وَجْهَكَ لِلدِّينِ الْقَيِّمِ مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ﴾؟","answer":"ثبات الوجه اليوم هو النجاة قبل يوم ينقسم فيه الناس ولا يمكن تدارك الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص420–429.","url":""}]},{"id":"s30-46","number":46,"surah":30,"verses":[44],"verseLabel":"الروم: 44","question":"ما سرّ التعبير بـ﴿مَنْ كَفَرَ فَعَلَيْهِ كُفْرُهُ وَمَنْ عَمِلَ صَالِحًا فَلِأَنْفُسِهِمْ يَمْهَدُونَ﴾؟","answer":"قابل حمل التبعة بتهيئة الفراش؛ الصالح يبني راحته المقبلة بعمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص430–438.","url":""}]},{"id":"s30-47","number":47,"surah":30,"verses":[46],"verseLabel":"الروم: 46","question":"ما سرّ وصف الرياح بأنها ﴿مُبَشِّرَاتٍ﴾؟","answer":"علاماتها تسبق المطر والرحمة، فكأنها تحمل البشرى قبل وصول العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص447–460.","url":""}]},{"id":"s30-48","number":48,"surah":30,"verses":[47],"verseLabel":"الروم: 47","question":"ما سرّ التعبير بـ﴿وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ﴾؟","answer":"تفضل الله فجعل نصرهم وعدًا ثابتًا، بعد ذكر سنته في الانتقام من المجرمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص461–471.","url":""}]},{"id":"s30-49","number":49,"surah":30,"verses":[48],"verseLabel":"الروم: 48","question":"ما سرّ وصف مراحل السحاب: يثيره ثم يبسطه ثم يجعله كسفًا؟","answer":"نقل العين عبر التكوين المتدرج حتى خروج الودق، فيرى السامع التدبير لا المطر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص472–495.","url":""}]},{"id":"s30-50","number":50,"surah":30,"verses":[49],"verseLabel":"الروم: 49","question":"ما سرّ تكرار ﴿مِنْ قَبْلُ﴾ في وصف إبلاسهم قبل نزول المطر؟","answer":"تعلقت ﴿مِنْ قَبْلِ أَنْ يُنَزَّلَ عَلَيْهِمْ﴾ بإنزال المطر، ثم جاءت ﴿مِنْ قَبْلِهِ لَمُبْلِسِينَ﴾ لتوكيد رسوخ إبلاسهم قبل الإنزال؛ فالثانية توكيد للحالة مع اختلاف المتعلَّق في التركيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص472–495.","url":""}]},{"id":"s30-51","number":51,"surah":30,"verses":[50],"verseLabel":"الروم: 50","question":"ما سرّ التعبير بـ﴿فَانْظُرْ إِلَى آثَارِ رَحْمَتِ اللَّهِ﴾ لا «إلى المطر»؟","answer":"نقل النظر من الوسيلة إلى نتائج الرحمة في الأرض والحياة، ثم إلى الإحياء الأكبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص472–495.","url":""}]},{"id":"s30-52","number":52,"surah":30,"verses":[52,53],"verseLabel":"الروم: 52-53","question":"ما سرّ تشبيه الكفار بالموتى والصم والعمي؟","answer":"المشكلة ليست فقد الحواس، بل تعطل الاستجابة حتى صار إسماع الحجة كإسماع من لا يرجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص509–530.","url":""}]},{"id":"s30-53","number":53,"surah":30,"verses":[54],"verseLabel":"الروم: 54","question":"ما سرّ تكرار ﴿ضَعْفٍ﴾ ثلاث مرات وجعل بينهما قوة؟","answer":"جعل الضعف إطار البداية والنهاية، والقوة مرحلة عابرة موهوبة لا مبرر للغرور بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص531–544.","url":""}]},{"id":"s30-54","number":54,"surah":30,"verses":[55],"verseLabel":"الروم: 55","question":"ما دلالة قسم المجرمين عند قيام الساعة أنهم لم يلبثوا غير ساعة؟","answer":"عند قيام الساعة يقسم المجرمون أنهم ما لبثوا غير ساعة؛ فهول الموقف يقصر في تصورهم مدة اللبث، ويكشف استمرار انقلاب تقديرهم عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص545–558.","url":""}]},{"id":"s30-55","number":55,"surah":30,"verses":[56],"verseLabel":"الروم: 56","question":"لماذا صحح أهل العلم والإيمان مدة اللبث؟","answer":"العلم بالوحي أبقاهم على ميزان الحقيقة حين أربك البعث المنكرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص559–574.","url":""}]},{"id":"s30-56","number":56,"surah":30,"verses":[58],"verseLabel":"الروم: 58","question":"ما سرّ التعبير بـ﴿وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِنْ كُلِّ مَثَلٍ﴾؟","answer":"استوعب طرائق البيان، حتى صار ردهم للآيات عنادًا لا نقص توضيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص575–593.","url":""}]},{"id":"s30-57","number":57,"surah":30,"verses":[60],"verseLabel":"الروم: 60","question":"ما سرّ ختم السورة بـ﴿فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَا يَسْتَخِفَّنَّكَ الَّذِينَ لَا يُوقِنُونَ﴾؟","answer":"عادت إلى وعد المطلع: تحقق نصر الروم نموذج، فلا يحملنّك اضطراب غير الموقنين على الخفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص594–604.","url":""}]},{"id":"s31-1","number":1,"surah":31,"verses":[1],"verseLabel":"لقمان: 1","question":"ما وجه افتتاح سورة لقمان بـ﴿الم﴾؟","answer":"افتتحت بالحروف المقطعة تنبيهًا إلى شأن القرآن المؤلف من الحروف المعهودة، مع بقاء تعيين مرادها مما لا يجزم فيه بوجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص605–642.","url":""}]},{"id":"s31-2","number":2,"surah":31,"verses":[2],"verseLabel":"لقمان: 2","question":"ما سرّ وصف آيات الكتاب بـ﴿الْحَكِيمِ﴾؟","answer":"الحكيم يحتمل معنى المحكم الذي لا خلل فيه، وذا الحكمة لاشتماله على الحكم والمواعظ؛ فوصف الكتاب يقرر إحكامه وما ينطق به من حكمة، من غير تعليق الجواب على مقارنة لم تفتح أطرافها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص616–642.","url":""}]},{"id":"s31-3","number":3,"surah":31,"verses":[3],"verseLabel":"لقمان: 3","question":"ما سرّ الجمع بين ﴿هُدًى وَرَحْمَةً﴾ وتخصيصهما بالمحسنين؟","answer":"الهداية تدل الطريق، والرحمة ثمرة سلوكه، وخص المحسنين لأنهم المنتفعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص616–642.","url":""}]},{"id":"s31-4","number":4,"surah":31,"verses":[4],"verseLabel":"لقمان: 4","question":"ما سرّ تكرار الضمير في ﴿وَهُمْ بِالْآخِرَةِ هُمْ يُوقِنُونَ﴾؟","answer":"ثبت اختصاصهم باليقين الكامل في مقابل من يشتري لهو الحديث.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص616–642.","url":""}]},{"id":"s31-5","number":5,"surah":31,"verses":[6],"verseLabel":"لقمان: 6","question":"ما سرّ التعبير بـ﴿يَشْتَرِي لَهْوَ الْحَدِيثِ﴾؟","answer":"صور بذل المال أو الاختيار في كلام يصرف عن الحق كصفقة خاسرة مقصودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص643–669.","url":""}]},{"id":"s31-6","number":6,"surah":31,"verses":[7],"verseLabel":"لقمان: 7","question":"ما سرّ التدرج في ﴿وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا﴾؟","answer":"درج من الإعراض المتكبر إلى محو السماع ثم ثقل الأذن؛ تصوير لتصاعد الانغلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص643–669.","url":""}]},{"id":"s31-7","number":7,"surah":31,"verses":[10],"verseLabel":"لقمان: 10","question":"ما أوجه معنى ﴿بِغَيْرِ عَمَدٍ تَرَوْنَهَا﴾؟","answer":"يحتمل التركيب نفي العمد أصلًا، ويحتمل وجود عمد لا ترونها على اختلاف التفسير؛ والعبرة بثبات السماوات وقيامها بقدرة الله، فلا يحصر الجواب في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص683–705.","url":""}]},{"id":"s31-8","number":8,"surah":31,"verses":[10],"verseLabel":"لقمان: 10","question":"ما سرّ تخصيص السماوات بوصف ﴿بِغَيْرِ عَمَدٍ تَرَوْنَهَا﴾ في هذا السياق؟","answer":"تعلّق الوصف بالسماوات لأنها مرفوعة يشاهد علوها، فكان نفي العمد المرئية فيها موضع الدلالة؛ أما الأرض فهي قرار المخاطبين. صيغ السؤال على الآية نفسها دون تعليل مقارن خارجي.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص683–705.","url":""}]},{"id":"s31-9","number":9,"surah":31,"verses":[11],"verseLabel":"لقمان: 11","question":"ما سرّ التعبير بـ﴿هَذَا خَلْقُ اللَّهِ فَأَرُونِي مَاذَا خَلَقَ الَّذِينَ مِنْ دُونِهِ﴾؟","answer":"نقلهم من دعوى الشريك إلى اختبار الإنجاز: أين أثر خلقه أمام الكون المشهود؟","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص683–705.","url":""}]},{"id":"s31-10","number":10,"surah":31,"verses":[12],"verseLabel":"لقمان: 12","question":"ما سرّ البدء بالشكر في قوله ﴿أَنِ اشْكُرْ لِلَّهِ﴾؟","answer":"الشكر رؤية المنعم واستعمال النعمة في مراده، وهو أصل الحكمة العملية كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص706–718.","url":""}]},{"id":"s31-11","number":11,"surah":31,"verses":[12],"verseLabel":"لقمان: 12","question":"ما سرّ التعبير بـ﴿وَمَنْ يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ﴾؟","answer":"نفع الشكر عائد إلى صاحبه حفظًا وزيادة، والله غني عن العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص706–718.","url":""}]},{"id":"s31-12","number":12,"surah":31,"verses":[13],"verseLabel":"لقمان: 13","question":"ما سرّ افتتاح وصية لقمان بنداء ﴿يَا بُنَيَّ﴾؟","answer":"التصغير للتحبيب والشفقة، فيدخل أعظم تحذير من باب القرب لا القسوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص719–728.","url":""}]},{"id":"s31-13","number":13,"surah":31,"verses":[13],"verseLabel":"لقمان: 13","question":"ما سرّ التعبير بـ﴿إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ﴾؟","answer":"لأنه يضع العبادة في غير موضعها ويسوي المخلوق بالخالق، فأعظم به قلبًا للحقائق.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص719–728.","url":""}]},{"id":"s31-14","number":14,"surah":31,"verses":[14],"verseLabel":"لقمان: 14","question":"ما سرّ تخصيص الأم بقوله ﴿وَهْنًا عَلَى وَهْنٍ﴾ بعد الوصية بالوالدين؟","answer":"لأن حملها وولادتها ورضاعها آلام متراكبة قد لا يراها الولد كما يرى كسب الأب.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص729–755.","url":""}]},{"id":"s31-15","number":15,"surah":31,"verses":[15],"verseLabel":"لقمان: 15","question":"ما سرّ الجمع بين ﴿فَلَا تُطِعْهُمَا﴾ و﴿وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا﴾؟","answer":"فصل بين الطاعة العقدية الممنوعة والصحبة الإنسانية الواجبة؛ الخلاف لا يلغي البر.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص729–755.","url":""}]},{"id":"s31-16","number":16,"surah":31,"verses":[16],"verseLabel":"لقمان: 16","question":"ما سرّ التمثيل بحبة خردل في صخرة أو في السماوات أو الأرض؟","answer":"جمع نهاية الصغر وشدة الخفاء وبعد المكان؛ لا يضيع العمل في أي حاجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص756–766.","url":""}]},{"id":"s31-17","number":17,"surah":31,"verses":[16],"verseLabel":"لقمان: 16","question":"ما سرّ ختم الآية بـ﴿إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ﴾؟","answer":"اللطيف يصل علمه وتدبيره إلى الدقائق، والخبير يعلم باطنها وحقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص756–766.","url":""}]},{"id":"s31-18","number":18,"surah":31,"verses":[17],"verseLabel":"لقمان: 17","question":"ما سرّ الجمع بين إقامة الصلاة والأمر بالمعروف والنهي عن المنكر والصبر؟","answer":"الصلاة تصلح النفس، والدعوة تصلح الغير، والصبر يحفظ الطريق من تبعات الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص767–775.","url":""}]},{"id":"s31-19","number":19,"surah":31,"verses":[18],"verseLabel":"لقمان: 18","question":"ما سرّ التعبير بـ﴿وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ﴾؟","answer":"استعار داء يصيب عنق البعير لمن يلوي وجهه كبرًا عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص776–784.","url":""}]},{"id":"s31-20","number":20,"surah":31,"verses":[18],"verseLabel":"لقمان: 18","question":"ما سرّ التعبير بـ﴿وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا﴾؟","answer":"نُهي عن مشية البطر والخيلاء، وذكر الأرض يستحضر أن الماشي عليها عبد محدود لا يملك أن يتجاوز قدره؛ فالتعبير يذم المرح المتكبر لا مطلق الفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص776–784.","url":""}]},{"id":"s31-21","number":21,"surah":31,"verses":[19],"verseLabel":"لقمان: 19","question":"ما سرّ الجمع بين ﴿وَاقْصِدْ فِي مَشْيِكَ﴾ و﴿وَاغْضُضْ مِنْ صَوْتِكَ﴾؟","answer":"سوّى السمت الظاهر والصوت على ميزان الاعتدال؛ لا خيلاء ولا صخب.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص785–791.","url":""}]},{"id":"s31-22","number":22,"surah":31,"verses":[19],"verseLabel":"لقمان: 19","question":"ما سرّ تشبيه أنكر الأصوات بصوت الحمير؟","answer":"شبّه الصوت المرتفع المنكر بنهيق الحمير تنفيرًا من صورته وقبح وقعه؛ فالمذموم رفع الصوت على وجه النكارة بلا حاجة، لا مجرد قوة الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص785–791.","url":""}]},{"id":"s31-23","number":23,"surah":31,"verses":[20],"verseLabel":"لقمان: 20","question":"ما سرّ التعبير بـ﴿وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظَاهِرَةً وَبَاطِنَةً﴾؟","answer":"الإسباغ إتمام النعمة وإحاطتها، وتقسيمها إلى ظاهرة وباطنة يستوعب ما يدركه الإنسان وما يخفى عليه؛ وقد عرض المبحث أيضًا قراءتي الإفراد والجمع في ﴿نعمه﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص792–815.","url":""}]},{"id":"s31-24","number":24,"surah":31,"verses":[20],"verseLabel":"لقمان: 20","question":"ما دلالة نفي العلم والهدى والكتاب المنير عن جدالهم في الله؟","answer":"نُفيت عنه أصول الاحتجاج: علم محقق، وهدى يرشد إلى الحق، وكتاب منير يحتج به؛ فبقي جدالًا مجردًا من مستند.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص792–815.","url":""}]},{"id":"s31-25","number":25,"surah":31,"verses":[21],"verseLabel":"لقمان: 21","question":"ما دلالة جوابهم ﴿بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا﴾؟","answer":"هربوا من الدليل إلى الميراث الاجتماعي، فسألهم النص: ولو كان الشيطان يقودهم؟","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص10–23.","url":""}]},{"id":"s31-26","number":26,"surah":31,"verses":[22],"verseLabel":"لقمان: 22","question":"ما سرّ التعبير بـ﴿فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى﴾؟","answer":"شبه التوحيد بعروة شديدة يمسكها المستسلم لله فلا يسقط عند الفتن.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص24–34.","url":""}]},{"id":"s31-27","number":27,"surah":31,"verses":[27],"verseLabel":"لقمان: 27","question":"ما سرّ التمثيل بأشجار الأرض أقلامًا والبحر مدادًا لعدم نفاد كلمات الله؟","answer":"جمع موارد كتابة متخيلة بلا حد ليقرب عدم تناهي علم الله وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص65–73.","url":""}]},{"id":"s31-28","number":28,"surah":31,"verses":[27],"verseLabel":"لقمان: 27","question":"ما سرّ التعبير بالعدد ﴿سَبْعَةُ أَبْحُرٍ﴾؟","answer":"صرح المبحث بأن السبعة مستعملة كناية عن الكثرة، فلا يتوقف المعنى على حصر البحار في سبعة؛ والغرض تصوير أن الإمداد مهما كثر لا يستوعب كلمات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص65–73.","url":""}]},{"id":"s31-29","number":29,"surah":31,"verses":[28],"verseLabel":"لقمان: 28","question":"ما سرّ التعبير بـ﴿مَا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَاحِدَةٍ﴾؟","answer":"الكثرة لا تثقل القدرة؛ إيجاد الجميع وإعادتهم كإيجاد فرد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص74–80.","url":""}]},{"id":"s31-30","number":30,"surah":31,"verses":[29],"verseLabel":"لقمان: 29","question":"ما سرّ التعبير بالإيلاج في ﴿يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ﴾؟","answer":"الإيلاج إدخال تدريجي؛ يصور زيادة أحدهما في الآخر بلا فجأة ولا اضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص81–93.","url":""}]},{"id":"s31-31","number":31,"surah":31,"verses":[30],"verseLabel":"لقمان: 30","question":"ما سرّ التعبير بـ﴿ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ﴾؟","answer":"كل دلائل الخلق السابقة ترجع إلى أصل واحد: ثبوت ألوهيته وبطلان ما يدعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص94–104.","url":""}]},{"id":"s31-32","number":32,"surah":31,"verses":[31],"verseLabel":"لقمان: 31","question":"ما سرّ تشبيه الموج بـ﴿الظُّلَلِ﴾؟","answer":"الموج العالي يظل من تحته كالسحاب أو الجبال، فيغمر الإنسان بالخوف من فوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص105–130.","url":""}]},{"id":"s31-33","number":33,"surah":31,"verses":[32],"verseLabel":"لقمان: 32","question":"ما سرّ الجمع بين وصفي ﴿خَتَّارٍ كَفُورٍ﴾؟","answer":"الختار شديد الغدر؛ جمع نقض عهد الضر وجحود نعمة النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص105–130.","url":""}]},{"id":"s31-34","number":34,"surah":31,"verses":[33],"verseLabel":"لقمان: 33","question":"ما سرّ المغايرة بين ﴿وَالِدٌ عَنْ وَلَدِهِ﴾ و﴿مَوْلُودٌ هُوَ جَازٍ عَنْ وَالِدِهِ﴾؟","answer":"استعمل ﴿مولود﴾ لاستحضار رابطة الولادة الوثيقة، وأكد جانب نفي جزاء الولد عن والده بالضمير ﴿هو﴾ واسم الفاعل؛ فانتفى النفع من الجانبين في أشد علاقات القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص131–146.","url":""}]},{"id":"s31-35","number":35,"surah":31,"verses":[33],"verseLabel":"لقمان: 33","question":"ما سرّ الجمع بين ﴿فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا﴾ و﴿وَلَا يَغُرَّنَّكُمْ بِاللَّهِ الْغَرُورُ﴾؟","answer":"حذر من فتنة الشيء نفسه ومن المزيّن الذي يستعمل سعة رحمة الله ذريعة للمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص131–146.","url":""}]},{"id":"s31-36","number":36,"surah":31,"verses":[34],"verseLabel":"لقمان: 34","question":"ما سرّ ختم السورة بمفاتح الغيب المذكورة في الآية 34؟","answer":"جاء الختام بعد الأمر بتقوى يوم القيامة ليقرر اختصاص الله بعلم الغيوب: وقت الساعة والغيث وما في الأرحام وما تكسب النفس وأرض موتها؛ فختم بقصور علم البشر وإحاطة علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص147–164.","url":""}]},{"id":"s32-1","number":1,"surah":32,"verses":[1],"verseLabel":"السجدة: 1","question":"ما وجه افتتاح سورة السجدة بـ﴿الم﴾؟","answer":"افتتحت بالحروف المقطعة تنبيهًا إلى شأن القرآن وتحديه، ثم أعقبها تقرير تنزيل الكتاب من رب العالمين؛ ولا يجزم في تعيين معنى الحروف بوجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص165–186.","url":""}]},{"id":"s32-2","number":2,"surah":32,"verses":[2],"verseLabel":"السجدة: 2","question":"ما سرّ التعبير بـ﴿تَنْزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِنْ رَبِّ الْعَالَمِينَ﴾؟","answer":"بدأ بالمصدر ليجعل التنزيل نفسه القضية، ثم نفى الريب وحدد المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص176–186.","url":""}]},{"id":"s32-3","number":3,"surah":32,"verses":[3],"verseLabel":"السجدة: 3","question":"ما سرّ الانتقال من حكاية قولهم ﴿افْتَرَاهُ﴾ إلى تقرير ﴿بَلْ هُوَ الْحَقُّ مِنْ رَبِّكَ﴾؟","answer":"لم يكتف بنفي التهمة، بل أثبت نقيضها ومصدر الحق وغايته في الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص187–201.","url":""}]},{"id":"s32-4","number":4,"surah":32,"verses":[4],"verseLabel":"السجدة: 4","question":"ما سرّ ذكر الاستواء على العرش بعد خلق السماوات والأرض؟","answer":"انتقل من إيجاد الملك إلى كمال تدبيره وسلطانه، على الوجه اللائق بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص202–217.","url":""}]},{"id":"s32-5","number":5,"surah":32,"verses":[5],"verseLabel":"السجدة: 5","question":"ما أوجه دلالة عروج الأمر في يوم مقداره ألف سنة؟","answer":"عرض المبحث عروج تدبير الأمر من السماء إلى الأرض ثم رجوعه، وبيّن اختلاف مقدار اليوم باختلاف المقام والمقياس؛ فالمقصود إحاطة التدبير وبعد مقاييسه عن حساب البشر، لا تحديد سرعة حسية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص218–233.","url":""}]},{"id":"s32-6","number":6,"surah":32,"verses":[6],"verseLabel":"السجدة: 6","question":"ما سرّ الجمع بين ﴿عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْعَزِيزُ الرَّحِيمُ﴾؟","answer":"العلم يحيط، والعزة تنفذ الحكم، والرحمة تجعل التدبير إحسانًا لا قهرًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص234–259.","url":""}]},{"id":"s32-7","number":7,"surah":32,"verses":[7],"verseLabel":"السجدة: 7","question":"ما سرّ التعبير بـ﴿الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ﴾؟","answer":"لكل مخلوق إتقان يناسب غايته، وإن لم يدرك الإنسان وجه الحسن في كل صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص234–259.","url":""}]},{"id":"s32-8","number":8,"surah":32,"verses":[7,8,9],"verseLabel":"السجدة: 7-9","question":"ما سرّ الانتقال من الطين إلى النطفة ثم التسوية والنفخ؟","answer":"اختصر أصل النوع ومراحل الفرد ليظهر تدرج القدرة من المادة إلى الإنسان السميع البصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص234–259.","url":""}]},{"id":"s32-9","number":9,"surah":32,"verses":[9],"verseLabel":"السجدة: 9","question":"ما سرّ الجمع بين السمع والأبصار والأفئدة ثم تعقيبه بـ﴿قَلِيلًا مَا تَشْكُرُونَ﴾؟","answer":"هذه أدوات تلقي الدليل وفهمه، فقلة الشكر هي تعطيل وظيفتها لا مجرد قلة القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص234–259.","url":""}]},{"id":"s32-10","number":10,"surah":32,"verses":[10],"verseLabel":"السجدة: 10","question":"ما سرّ التعبير في قولهم ﴿أَئِذَا ضَلَلْنَا فِي الْأَرْضِ﴾؟","answer":"الضلال في الأرض تصوير لاختلاط أجزاء الأجساد بترابها وذهاب تمييزها في ظنهم؛ فجاء قولهم إنكارًا للبعث ناشئًا من قياس قدرة الخالق على قدرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص260–269.","url":""}]},{"id":"s32-11","number":11,"surah":32,"verses":[11],"verseLabel":"السجدة: 11","question":"ما سرّ التعبير بـ﴿يَتَوَفَّاكُمْ مَلَكُ الْمَوْتِ الَّذِي وُكِّلَ بِكُمْ﴾؟","answer":"التوفي استيفاء النفس، و«وكل بكم» ينفي الفوضى؛ لكل أجل تنفيذ مأمور.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص270–278.","url":""}]},{"id":"s32-12","number":12,"surah":32,"verses":[12],"verseLabel":"السجدة: 12","question":"ما سرّ تصوير المجرمين ﴿نَاكِسُوا رُءُوسِهِمْ عِنْدَ رَبِّهِمْ﴾؟","answer":"من رفع رأسه عن السجود في الدنيا خفضه الخزي عند انكشاف البصر والسمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص279–297.","url":""}]},{"id":"s32-13","number":13,"surah":32,"verses":[12],"verseLabel":"السجدة: 12","question":"ما سرّ تقديم الإبصار على السمع في قولهم ﴿رَبَّنَا أَبْصَرْنَا وَسَمِعْنَا﴾؟","answer":"قُدّم الإبصار لأن مقام القيامة مقام مشاهدة لما كانوا يسمعون خبره وينكرونه؛ فصار المرئي يومئذ أسبق في اعترافهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص279–297.","url":""}]},{"id":"s32-14","number":14,"surah":32,"verses":[13],"verseLabel":"السجدة: 13","question":"ما دلالة قوله تعالى ﴿وَلَوْ شِئْنَا لَآتَيْنَا كُلَّ نَفْسٍ هُدَاهَا﴾؟","answer":"الهداية القهرية ممكنة، لكن الابتلاء اقتضى الاختيار وقيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص298–309.","url":""}]},{"id":"s32-15","number":15,"surah":32,"verses":[14],"verseLabel":"السجدة: 14","question":"ما سرّ المقابلة بين ﴿نَسِيتُمْ لِقَاءَ يَوْمِكُمْ هَذَا﴾ و﴿إِنَّا نَسِينَاكُمْ﴾؟","answer":"نسيانهم إهمال متعمد للقاء، ومقابلته تركهم في العذاب لا غياب العلم عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص310–321.","url":""}]},{"id":"s32-16","number":16,"surah":32,"verses":[15],"verseLabel":"السجدة: 15","question":"ما سرّ تصوير استجابتهم للآيات بقوله ﴿خَرُّوا سُجَّدًا﴾؟","answer":"جاء السجود استجابة فورية تهوي فيها الأجساد حين ترتفع الحقيقة في القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص322–333.","url":""}]},{"id":"s32-17","number":17,"surah":32,"verses":[16],"verseLabel":"السجدة: 16","question":"ما سرّ التعبير بـ﴿تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ﴾؟","answer":"صور الجنب يبتعد بنفسه عن موضع الراحة؛ رغبة العبادة أقوى من جذب الفراش.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص334–343.","url":""}]},{"id":"s32-18","number":18,"surah":32,"verses":[16],"verseLabel":"السجدة: 16","question":"ما سرّ الجمع بين الخوف والطمع في دعائهم؟","answer":"جمع جناحي العبادة؛ فلا أمن يغري ولا يأس يقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص334–343.","url":""}]},{"id":"s32-19","number":19,"surah":32,"verses":[17],"verseLabel":"السجدة: 17","question":"ما سرّ التعبير بـ﴿فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ﴾؟","answer":"نُكرت ﴿نفس﴾ و﴿قرة أعين﴾ وعبّر بالإخفاء لتعميم الجهل بمقدار الثواب وتعظيمه؛ فهو جزاء لا تحيط به نفس قبل ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص344–350.","url":""}]},{"id":"s32-20","number":20,"surah":32,"verses":[18],"verseLabel":"السجدة: 18","question":"ما سرّ الاستفهام في ﴿أَفَمَنْ كَانَ مُؤْمِنًا كَمَنْ كَانَ فَاسِقًا﴾؟","answer":"استفهام يرفض التسوية قبل تفصيل المصيرين؛ اختلاف الطريق يستلزم اختلاف النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص351–356.","url":""}]},{"id":"s32-21","number":21,"surah":32,"verses":[20],"verseLabel":"السجدة: 20","question":"ما دلالة تكرر إرادة أهل النار الخروج وإعادتهم فيها؟","answer":"كرر الإرادة والإعادة لتصوير تجدد الأمل الكاذب والرد القاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص366–376.","url":""}]},{"id":"s32-22","number":22,"surah":32,"verses":[20],"verseLabel":"السجدة: 20","question":"ما سرّ تذكير الموصول في ﴿عَذَابَ النَّارِ الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ﴾؟","answer":"الموصول المذكر ﴿الذي﴾ عائد إلى ﴿عذاب﴾ لا إلى ﴿النار﴾؛ فجرى التذكير ومثله الضمير في ﴿به﴾ على مرجع العذاب. صيغ السؤال على تركيب السجدة نفسه دون إبقاء مقارنة غير مفتوحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص366–376.","url":""}]},{"id":"s32-23","number":23,"surah":32,"verses":[21],"verseLabel":"السجدة: 21","question":"ما سرّ التعبير بـ﴿الْعَذَابِ الْأَدْنَى﴾ و﴿الْعَذَابِ الْأَكْبَرِ﴾؟","answer":"عذاب الدنيا أقرب وأقل، وغايته التنبيه والرجوع قبل عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص377–384.","url":""}]},{"id":"s32-24","number":24,"surah":32,"verses":[22],"verseLabel":"السجدة: 22","question":"ما دلالة ترتيب التذكير بآيات الله ثم الإعراض عنها؟","answer":"الجريمة ليست جهلًا أوليًا، بل إدارة الظهر بعد حضور التذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص385–395.","url":""}]},{"id":"s32-25","number":25,"surah":32,"verses":[23],"verseLabel":"السجدة: 23","question":"ما أوجه عود الضمير في ﴿فَلَا تَكُنْ فِي مِرْيَةٍ مِنْ لِقَائِهِ﴾؟","answer":"ذكر المبحث وجوهًا لعود الضمير: إلى موسى في لقاء النبي به، ومنه ما حمل على ليلة الإسراء أو لقاء الآخرة، وقيل إلى الكتاب أي لقاء موسى التوراة؛ فلا يحصر اللفظ في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص396–404.","url":""}]},{"id":"s32-26","number":26,"surah":32,"verses":[24],"verseLabel":"السجدة: 24","question":"ما سرّ الجمع بين الصبر واليقين في جعل الأئمة الهادين؟","answer":"الصبر يحمل أعباء الطريق، واليقين يمنع التردد؛ بهما تستحق قيادة الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص405–413.","url":""}]},{"id":"s32-27","number":27,"surah":32,"verses":[26],"verseLabel":"السجدة: 26","question":"ما سرّ التعبير بـ﴿أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا﴾؟","answer":"جعل التاريخ نفسه هاديًا لمن يمشي في مساكن الهالكين ويسمع دلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص420–428.","url":""}]},{"id":"s32-28","number":28,"surah":32,"verses":[27],"verseLabel":"السجدة: 27","question":"ما سرّ تصوير إحياء الأرض الجرز بسوق الماء إليها؟","answer":"«الجرز» اليابسة التي أكل نباتها؛ إحياؤها بالماء نموذج مرئي للبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص429–439.","url":""}]},{"id":"s32-29","number":29,"surah":32,"verses":[28],"verseLabel":"السجدة: 28","question":"ما أوجه معنى ﴿الْفَتْحُ﴾ في سؤالهم ﴿مَتَى هَذَا الْفَتْحُ﴾؟","answer":"ذكر المبحث في الفتح وجوهًا، منها نصر المؤمنين والفصل بينهم وبين الكافرين، ومنها يوم القيامة أو العذاب؛ لذلك لا يعتمد حصره في معنى واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص440–452.","url":""}]},{"id":"s32-30","number":30,"surah":32,"verses":[29],"verseLabel":"السجدة: 29","question":"ما دلالة عدم نفع الإيمان يوم الفتح؟","answer":"إذا جاء الفتح الفاصل وانكشف ما كانوا يكذبون به لم يعد الإيمان المتأخر نافعًا، ولا يمهلون للرجوع؛ ويتنوع تعيين الفتح بحسب الوجوه المذكورة في المبحث.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص440–452.","url":""}]},{"id":"s32-31","number":31,"surah":32,"verses":[30],"verseLabel":"السجدة: 30","question":"ما سرّ ختم السورة بـ﴿فَأَعْرِضْ عَنْهُمْ وَانْتَظِرْ إِنَّهُمْ مُنْتَظِرُونَ﴾؟","answer":"قابل انتظار المؤمن لوعد الله بانتظارهم سقوطه؛ وسيكشف الواقع أي الانتظارين صدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص440–452.","url":""}]},{"id":"s33-1","number":1,"surah":33,"verses":[1],"verseLabel":"الأحزاب: 1","question":"ما سرّ افتتاح السورة بخطاب النبي ﷺ: ﴿يَا أَيُّهَا النَّبِيُّ اتَّقِ اللَّهَ﴾؟","answer":"افتتح الخطاب بوصف النبوة تشريفًا وتنبيهًا إلى أن الأمر متعلق بمقام الرسالة، والأمر بالتقوى تثبيت على دوامها وكمالها، لا نسبة تقصير إلى النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص453–488.","url":""}]},{"id":"s33-2","number":2,"surah":33,"verses":[1],"verseLabel":"الأحزاب: 1","question":"ما سرّ الجمع بين النهي عن طاعة الكافرين والمنافقين؟","answer":"لأن الخطر يأتي من عدو معلن وآخر متستر، ولكل منهما ضغطه في قضايا السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص464–488.","url":""}]},{"id":"s33-3","number":3,"surah":33,"verses":[2],"verseLabel":"الأحزاب: 2","question":"ما سرّ تعقيب النهي بقوله ﴿وَاتَّبِعْ مَا يُوحَى إِلَيْكَ مِنْ رَبِّكَ﴾؟","answer":"لم يترك فراغًا بعد رفض ضغطهم؛ البديل المحدد هو الوحي من الرب المربي.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص464–488.","url":""}]},{"id":"s33-4","number":4,"surah":33,"verses":[3],"verseLabel":"الأحزاب: 3","question":"ما سرّ التعبير بـ﴿وَكَفَى بِاللَّهِ وَكِيلًا﴾؟","answer":"من فوّض أمره لله استغنى عن تنازلات طلب الحماية من الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص464–488.","url":""}]},{"id":"s33-5","number":5,"surah":33,"verses":[4],"verseLabel":"الأحزاب: 4","question":"ما سرّ التعبير بـ﴿مَا جَعَلَ اللَّهُ لِرَجُلٍ مِنْ قَلْبَيْنِ فِي جَوْفِهِ﴾؟","answer":"مهّد بنفي اجتماع الأصلين المتناقضين لنقض أقوال تجعل الزوجة أمًا والدعي ابنًا بمجرد اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص489–511.","url":""}]},{"id":"s33-6","number":6,"surah":33,"verses":[4],"verseLabel":"الأحزاب: 4","question":"ما سرّ زيادة ﴿فِي جَوْفِهِ﴾ مع أن القلب لا يكون إلا فيه؟","answer":"زادت ﴿في جوفه﴾ تصويرًا للمحال وتوكيدًا له في موضعه المحسوس؛ ومُهّد بهذا المثل لنقض دعاوى الظهار والتبني التي لا تقلب الحقائق بالألفاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص489–511.","url":""}]},{"id":"s33-7","number":7,"surah":33,"verses":[4],"verseLabel":"الأحزاب: 4","question":"ما سرّ التعبير بـ﴿وَمَا جَعَلَ أَدْعِيَاءَكُمْ أَبْنَاءَكُمْ﴾؟","answer":"فرق بين عاطفة الرعاية وحقيقة النسب؛ القول لا يغير الخلقة والحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص489–511.","url":""}]},{"id":"s33-8","number":8,"surah":33,"verses":[5],"verseLabel":"الأحزاب: 5","question":"ما سرّ التعبير بـ﴿ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ﴾؟","answer":"رد الاسم إلى الحقيقة والعدل في الأنساب، مع إبقاء الأخوة والموالاة لمن جهل أبوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص512–529.","url":""}]},{"id":"s33-9","number":9,"surah":33,"verses":[5],"verseLabel":"الأحزاب: 5","question":"ما سرّ المقابلة بين الخطأ وتعمد القلوب في الآية 5؟","answer":"فصل سبق اللسان عن قصد القلب، فالحكم الأخلاقي يتبع التعمد بعد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص512–529.","url":""}]},{"id":"s33-10","number":10,"surah":33,"verses":[6],"verseLabel":"الأحزاب: 6","question":"ما سرّ التعبير بـ﴿النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ﴾؟","answer":"طاعته وهديه أصدق نفعًا لهم من رغبات قد تهلكهم؛ فهو أولى في أمر الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص530–548.","url":""}]},{"id":"s33-11","number":11,"surah":33,"verses":[6],"verseLabel":"الأحزاب: 6","question":"ما سرّ وصف أزواج النبي ﷺ بأنهن ﴿أُمَّهَاتُهُمْ﴾؟","answer":"الأمومة هنا في حرمة النكاح بعد النبي ﷺ ووجوب التعظيم، لا في جميع أحكام النسب والخلوة والميراث؛ لذلك قُيد الجواب بما يثبته السياق والبحث.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص530–548.","url":""}]},{"id":"s33-12","number":12,"surah":33,"verses":[7],"verseLabel":"الأحزاب: 7","question":"ما سرّ تخصيص نوح وإبراهيم وموسى وعيسى بعد ذكر النبيين؟","answer":"عطف أولي العزم تشريفًا وإبرازًا للميثاق العظيم الذي يجمع رسالاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص549–566.","url":""}]},{"id":"s33-13","number":13,"surah":33,"verses":[9],"verseLabel":"الأحزاب: 9","question":"ما سرّ المقابلة بين الجنود المرئية والريح والجنود التي لم يروها؟","answer":"قوبل حشد الأحزاب المشاهد بريح وجنود لم يرها المؤمنون؛ فظهر أن رد العدوان كان بتدبير الله وأسباب لم تكن في حساب القوة الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص567–583.","url":""}]},{"id":"s33-14","number":14,"surah":33,"verses":[10],"verseLabel":"الأحزاب: 10","question":"ما سرّ تصوير الخوف بـ﴿زَاغَتِ الْأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ﴾؟","answer":"رسم الذعر في العين والنفس؛ كأن القلب يصعد من شدة الخوف حتى الحلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص584–599.","url":""}]},{"id":"s33-15","number":15,"surah":33,"verses":[10],"verseLabel":"الأحزاب: 10","question":"ما سرّ جمع ﴿الظُّنُونَا﴾ في قوله ﴿وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا﴾؟","answer":"جمع الظنون لتعدد ما اضطرب في النفوس زمن الشدة واختلاف أحوال المؤمنين والمنافقين، مع ما في صيغة الجمع من تهويل تلك الخواطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص584–599.","url":""}]},{"id":"s33-16","number":16,"surah":33,"verses":[11],"verseLabel":"الأحزاب: 11","question":"ما سرّ التعبير بـ﴿هُنَالِكَ ابْتُلِيَ الْمُؤْمِنُونَ وَزُلْزِلُوا زِلْزَالًا شَدِيدًا﴾؟","answer":"أشار إلى لحظة الخطر البعيدة في الهول، وشبه اضطراب النفوس بزلزال الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص584–599.","url":""}]},{"id":"s33-17","number":17,"surah":33,"verses":[12],"verseLabel":"الأحزاب: 12","question":"ما دلالة قول المنافقين ﴿مَا وَعَدَنَا اللَّهُ وَرَسُولُهُ إِلَّا غُرُورًا﴾؟","answer":"حوّلوا الوعد الذي يثبّت المؤمن إلى تهمة حين خالف الواقع العاجل توقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص600–608.","url":""}]},{"id":"s33-18","number":18,"surah":33,"verses":[13],"verseLabel":"الأحزاب: 13","question":"ما دلالة ندائهم ﴿يَا أَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَارْجِعُوا﴾؟","answer":"استعملوا اسم يثرب ونداء أهلها ليثيروا رابطة المكان ويدعوهم إلى الرجوع عن موضع القتال؛ فكان النداء أداة تثبيط وفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص609–622.","url":""}]},{"id":"s33-19","number":19,"surah":33,"verses":[13],"verseLabel":"الأحزاب: 13","question":"ما سرّ كشف عذرهم بقوله ﴿وَمَا هِيَ بِعَوْرَةٍ إِنْ يُرِيدُونَ إِلَّا فِرَارًا﴾؟","answer":"أسقط العذر الخارجي وكشف الإرادة الداخلية؛ البيت ستار للهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص609–622.","url":""}]},{"id":"s33-20","number":20,"surah":33,"verses":[15],"verseLabel":"الأحزاب: 15","question":"ما سرّ تذكيرهم بعهدهم السابق ألا يولوا الأدبار؟","answer":"ليحول الفرار من ضعف لحظي إلى نقض مسؤول لعهد سيسألون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص635–640.","url":""}]},{"id":"s33-21","number":21,"surah":33,"verses":[16],"verseLabel":"الأحزاب: 16","question":"ما سرّ الجمع بين الموت والقتل في ﴿لَنْ يَنْفَعَكُمُ الْفِرَارُ﴾؟","answer":"فرّق الموت الطبيعي والقتل ثم جمعهما في أجل لا يطيله الفرار إلا متاعًا قليلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص641–652.","url":""}]},{"id":"s33-22","number":22,"surah":33,"verses":[18],"verseLabel":"الأحزاب: 18","question":"ما سرّ دخول ﴿قَدْ﴾ على قوله ﴿يَعْلَمُ اللَّهُ الْمُعَوِّقِينَ مِنْكُمْ﴾؟","answer":"«قد» للتحقيق، واستحضر فعلهم المستمر في تثبيط غيرهم لا جبنهم الشخصي فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص669–681.","url":""}]},{"id":"s33-23","number":23,"surah":33,"verses":[19],"verseLabel":"الأحزاب: 19","question":"ما سرّ الجمع بين ﴿أَشِحَّةً عَلَيْكُمْ﴾ وتصوير أعينهم تدور عند الخوف؟","answer":"جمع بخلهم بالنصرة وشدة هلعهم؛ يأخذون من الجماعة ولا يعطونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص682–711.","url":""}]},{"id":"s33-24","number":24,"surah":33,"verses":[20],"verseLabel":"الأحزاب: 20","question":"ما دلالة حسبانهم أن الأحزاب لم يذهبوا بعد انصرافهم؟","answer":"بقي الخوف في قلوبهم بعد زوال الجيش، حتى صار الوهم أقوى من المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص712–727.","url":""}]},{"id":"s33-25","number":25,"surah":33,"verses":[21],"verseLabel":"الأحزاب: 21","question":"ما سرّ ورود ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ﴾ في سياق الخوف؟","answer":"جعل ثباته العملي جوابًا حيًا على أعذار المتخلفين، لا موعظة نظرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص728–740.","url":""}]},{"id":"s33-26","number":26,"surah":33,"verses":[22],"verseLabel":"الأحزاب: 22","question":"ما دلالة قول المؤمنين عند رؤية الأحزاب ﴿هَذَا مَا وَعَدَنَا اللَّهُ وَرَسُولُهُ﴾؟","answer":"المشهد نفسه كذب به المنافقون وزاد المؤمنين إيمانًا؛ الموقف يكشف نوع القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص741–752.","url":""}]},{"id":"s33-27","number":27,"surah":33,"verses":[23],"verseLabel":"الأحزاب: 23","question":"ما سرّ التعبير بـ﴿مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ﴾؟","answer":"لم يكتف بصدق القول؛ جعل الصدق وفاءً عمليًا بالعهد حتى الموت أو الانتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص753–768.","url":""}]},{"id":"s33-28","number":28,"surah":33,"verses":[25],"verseLabel":"الأحزاب: 25","question":"ما سرّ التعبير بـ﴿وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْرًا﴾؟","answer":"عادوا يحملون غيظهم نفسه بلا غنيمة ولا نصر؛ فجمع الخيبة الداخلية والخارجية.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص786–798.","url":""}]},{"id":"s33-29","number":29,"surah":33,"verses":[25],"verseLabel":"الأحزاب: 25","question":"ما سرّ التعبير بـ﴿وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ﴾؟","answer":"لم ينسب النصر لقوتهم؛ الريح والتدبير صرفا المعركة قبل التحامها العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج44، ص786–798.","url":""}]},{"id":"s33-30","number":30,"surah":33,"verses":[26],"verseLabel":"الأحزاب: 26","question":"ما سرّ تصوير الرعب في قوله ﴿وَقَذَفَ فِي قُلُوبِهِمُ الرُّعْبَ﴾؟","answer":"صور الرعب شيئًا ألقي فجأة في الداخل، فسقط الحصن قبل سقوط الجدار.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص10–21.","url":""}]},{"id":"s33-31","number":31,"surah":33,"verses":[28],"verseLabel":"الأحزاب: 28","question":"ما سرّ تخيير النبي ﷺ أزواجه بين الدنيا وبين الله ورسوله والدار الآخرة؟","answer":"ليكون بيته موافقًا لطبيعة الرسالة وزهدها اختيارًا واعيًا لا إلزامًا خفيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص31–42.","url":""}]},{"id":"s33-32","number":32,"surah":33,"verses":[30,31],"verseLabel":"الأحزاب: 30-31","question":"ما سرّ مضاعفة العذاب لأزواج النبي ﷺ ومضاعفة أجر المحسنة منهن؟","answer":"زيادة القرب والقدوة تضاعف المسؤولية كما تضاعف فضل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص53–65.","url":""}]},{"id":"s33-33","number":33,"surah":33,"verses":[31],"verseLabel":"الأحزاب: 31","question":"ما سرّ التعبير بـ﴿وَمَنْ يَقْنُتْ مِنْكُنَّ﴾ بصيغة التذكير؟","answer":"﴿من﴾ اسم شرط عام يراعى لفظه المفرد المذكر في ﴿يقنت﴾، ثم يراعى معنى النساء في ﴿منكن﴾ وما بعده؛ فجمع النظم بين اللفظ والمعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص66–84.","url":""}]},{"id":"s33-34","number":34,"surah":33,"verses":[32],"verseLabel":"الأحزاب: 32","question":"ما سرّ التعبير بـ﴿لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ﴾؟","answer":"الخصوصية معلقة بالتقوى وبمقامهن من بيت النبوة، وما يترتب عليه من زيادة القدوة والمسؤولية؛ وليست تفضيلًا ذاتيًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص85–104.","url":""}]},{"id":"s33-35","number":35,"surah":33,"verses":[32],"verseLabel":"الأحزاب: 32","question":"ما سرّ النهي عن الخضوع بالقول دون النهي عن أصل الكلام؟","answer":"ضبط هيئة الخطاب المثيرة للطمع، وأبقى القول المعروف الذي تدعو إليه الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص85–104.","url":""}]},{"id":"s33-36","number":36,"surah":33,"verses":[32],"verseLabel":"الأحزاب: 32","question":"ما سرّ استعمال ﴿أَحَدٍ﴾ في ﴿لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ﴾؟","answer":"﴿أحد﴾ في سياق النفي يعم الواحد من العقلاء مذكرًا أو مؤنثًا، ولذلك صح مع خطاب النساء وكان أبلغ في نفي المماثلة العامة من لفظ يختص بالمؤنث.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص85–104.","url":""}]},{"id":"s33-37","number":37,"surah":33,"verses":[33],"verseLabel":"الأحزاب: 33","question":"ما سرّ التعبير بـ﴿وَقَرْنَ فِي بُيُوتِكُنَّ﴾؟","answer":"جعل البيت موضع السكينة والأصل، لا سجنًا يمنع الخروج المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص105–135.","url":""}]},{"id":"s33-38","number":38,"surah":33,"verses":[33],"verseLabel":"الأحزاب: 33","question":"ما سرّ الانتقال من ضمائر خطاب النساء إلى ضمير الجمع المذكر في آية التطهير؟","answer":"انتقل الضمير إلى صيغة الجمع المذكر لأن لفظ ﴿أهل البيت﴾ يتناول الرجال والنساء بالتغليب، مع بقاء زوجات النبي داخلات في سياق الخطاب؛ فلا يُخرجهن التحول الضميري منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص105–135.","url":""}]},{"id":"s33-39","number":39,"surah":33,"verses":[35],"verseLabel":"الأحزاب: 35","question":"ما سرّ تكرار صفات الرجال والنساء في الآية 35؟","answer":"ساوى في طريق التكليف والثواب مع التصريح بكل جنس، فلا يذوب ذكر النساء في التغليب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص153–174.","url":""}]},{"id":"s33-40","number":40,"surah":33,"verses":[36],"verseLabel":"الأحزاب: 36","question":"ما سرّ التصريح بالمؤمن والمؤمنة في قوله ﴿وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ﴾؟","answer":"الإيمان يقتضي سقوط الاختيار المعارض بعد ثبوت حكم الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص175–190.","url":""}]},{"id":"s33-41","number":41,"surah":33,"verses":[37],"verseLabel":"الأحزاب: 37","question":"ما دلالة قوله للنبي ﷺ ﴿وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ﴾؟","answer":"الذي أخفاه النبي ﷺ ما علمه من أن زينب ستصير زوجًا له بعد زيد، وكان يخشى مقالة الناس في زواج مطلقة من كان يدعى ابنًا له؛ فالعتاب متعلق بخشية الناس في إظهار الحكم، لا بمحبة محرمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص191–215.","url":""}]},{"id":"s33-42","number":42,"surah":33,"verses":[37],"verseLabel":"الأحزاب: 37","question":"ما سرّ تزويج النبي ﷺ زينب بعد أن قضى زيد منها وطرًا؟","answer":"لإبطال تحريم زوجة المتبنى بالفعل النبوي، لا بالقول وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص191–215.","url":""}]},{"id":"s33-43","number":43,"surah":33,"verses":[40],"verseLabel":"الأحزاب: 40","question":"ما سرّ التعبير بـ﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ﴾؟","answer":"نفى الأبوة التي تترتب عليها أحكام التبني، ثم أثبت مقام الرسالة وختم النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص235–246.","url":""}]},{"id":"s33-44","number":44,"surah":33,"verses":[40],"verseLabel":"الأحزاب: 40","question":"ما سرّ التعبير بـ﴿وَخَاتَمَ النَّبِيِّينَ﴾؟","answer":"لأن رسالته أكملت بناء النبوات وختمته، فلا نبي بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص235–246.","url":""}]},{"id":"s33-45","number":45,"surah":33,"verses":[41,42],"verseLabel":"الأحزاب: 41-42","question":"ما سرّ الجمع بين الذكر الكثير والتسبيح بكرة وأصيلًا؟","answer":"كثرة الذكر تحمي القلب وسط ضغط المجتمع، وتحيط اليوم بطرفيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص247–254.","url":""}]},{"id":"s33-46","number":46,"surah":33,"verses":[43],"verseLabel":"الأحزاب: 43","question":"ما سرّ الجمع بين صلاة الله وصلاة ملائكته على المؤمنين؟","answer":"صلاة الله رحمة وثناء، وصلاة الملائكة دعاء؛ كلها تخرج المؤمن من ظلمات الفتن إلى النور.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص255–263.","url":""}]},{"id":"s33-47","number":47,"surah":33,"verses":[45,46],"verseLabel":"الأحزاب: 45-46","question":"ما سرّ الجمع للنبي ﷺ بين صفات الشاهد والمبشر والنذير والداعي والسراج؟","answer":"استوعبت علاقته بالحق والناس والطريق: يشهد ويعد ويحذر ويدعو ويضيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص277–294.","url":""}]},{"id":"s33-48","number":48,"surah":33,"verses":[46],"verseLabel":"الأحزاب: 46","question":"ما سرّ وصف النبي ﷺ بـ﴿سِرَاجًا مُنِيرًا﴾؟","answer":"السراج يجمع أصل الإضاءة وإيصال النور إلى غيره، و﴿منيرًا﴾ تؤكد قوة الإضاءة والهداية؛ فالصورة لبيان أثر الرسالة في كشف الطريق، دون حاجة إلى مقابلة افتراضية مع الشمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص277–294.","url":""}]},{"id":"s33-49","number":49,"surah":33,"verses":[49],"verseLabel":"الأحزاب: 49","question":"ما وجه سقوط العدة عن المطلقة قبل المساس؟","answer":"لأن العدة تتحقق بها براءة الرحم، فإذا لم يقع دخول انتفت علتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص313–328.","url":""}]},{"id":"s33-50","number":50,"surah":33,"verses":[49],"verseLabel":"الأحزاب: 49","question":"ما سرّ الجمع بين ﴿فَمَتِّعُوهُنَّ﴾ و﴿سَرِّحُوهُنَّ سَرَاحًا جَمِيلًا﴾؟","answer":"جبر خاطر المطلقة بعطاء، ثم جعل الفراق نفسه معروفًا بلا أذى أو تشهير.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص313–328.","url":""}]},{"id":"s33-51","number":51,"surah":33,"verses":[53],"verseLabel":"الأحزاب: 53","question":"ما سرّ تفصيل أدب الدخول والطعام والحجاب في بيت النبي ﷺ؟","answer":"لأن الألفة لا تسقط الخصوصية، وبيت النبوة موضع قدوة ووحي لا مجلسًا مباحًا بلا حد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص388–421.","url":""}]},{"id":"s33-52","number":52,"surah":33,"verses":[53],"verseLabel":"الأحزاب: 53","question":"ما سرّ المقابلة بين حياء النبي ﷺ وقوله ﴿وَاللَّهُ لَا يَسْتَحْيِي مِنَ الْحَقِّ﴾؟","answer":"كان طول مكث الضيوف يؤذي النبي ﷺ، وكان يمنعه حياؤه وكرمه من التصريح؛ فبيّن الله الحق الذي يجب إظهاره. والمنفي عن الله حياءٌ يفضي إلى ترك بيان الحق، لا صفة الحياء على الوجه اللائق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص388–421.","url":""}]},{"id":"s33-53","number":53,"surah":33,"verses":[56],"verseLabel":"الأحزاب: 56","question":"ما سرّ الجمع بين صلاة الله وملائكته على النبي ﷺ ثم أمر المؤمنين بالصلاة والسلام عليه؟","answer":"قُدِّم الخبر بصلاة الله وملائكته تشريفًا للنبي ﷺ، ثم أُمر المؤمنون أن يشاركوا في هذا الثناء بالدعاء له والتسليم والانقياد؛ فاجتمع بيان منزلته وحقه على أمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص445–454.","url":""}]},{"id":"s33-54","number":54,"surah":33,"verses":[57],"verseLabel":"الأحزاب: 57","question":"ما سرّ الجمع بين إيذاء الله وإيذاء رسوله ﷺ؟","answer":"إيذاء الله هو فعل ما يكرهه ويسخطه، وإيذاء الرسول ﷺ اعتداء على مقام الرسالة؛ فالجمع يبين أن أذى الرسول متصل بحرمة مرسله وعقوبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص455–471.","url":""}]},{"id":"s33-55","number":55,"surah":33,"verses":[58],"verseLabel":"الأحزاب: 58","question":"ما سرّ تسمية أذى المؤمنين والمؤمنات بغير ما اكتسبوا ﴿بُهْتَانًا وَإِثْمًا مُبِينًا﴾؟","answer":"هو بهتان لأنه اتهام يبهت المظلوم ولا أصل له، وإثم مبين لأنه عدوان ظاهر وقع من غير جناية مكتسبة؛ فجمع الوصفان كذب القول وجرم الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص455–471.","url":""}]},{"id":"s33-56","number":56,"surah":33,"verses":[59],"verseLabel":"الأحزاب: 59","question":"ما سرّ التعليل في قوله ﴿ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلَا يُؤْذَيْنَ﴾؟","answer":"جعل إدناء الجلابيب علامة ظاهرة على العفة والاحتشام، فيكون أقرب إلى معرفتهن بذلك وأبعد عن تعرض أهل السفه لهن؛ والآية تقرر الوقاية ولا تحمل المعتدى عليها إثم العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص472–483.","url":""}]},{"id":"s33-57","number":57,"surah":33,"verses":[60],"verseLabel":"الأحزاب: 60","question":"ما سرّ الجمع بين المنافقين والذين في قلوبهم مرض والمرجفين في المدينة؟","answer":"فصّل أصناف الفساد بحسب منابعه: نفاق يضمر العداوة، ومرض قلب يبعث على الفجور، وإرجاف ينشر الخوف؛ ثم جمعها لاشتراكها في تهديد أمن المدينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص484–503.","url":""}]},{"id":"s33-58","number":58,"surah":33,"verses":[63],"verseLabel":"الأحزاب: 63","question":"ما سرّ تذكير ﴿قَرِيبًا﴾ في قوله ﴿لَعَلَّ السَّاعَةَ تَكُونُ قَرِيبًا﴾؟","answer":"راعى النظم معنى الزمن المحذوف، أي: لعل زمان الساعة قريب، وقيل: التقدير شيئًا قريبًا؛ فجيء بالمذكر لأن السؤال عن وقتها لا لمجرد مراعاة لفظ ﴿الساعة﴾ المؤنث.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص504–513.","url":""}]},{"id":"s33-59","number":59,"surah":33,"verses":[66],"verseLabel":"الأحزاب: 66","question":"ما سرّ تصوير أهل النار بقوله ﴿تُقَلَّبُ وُجُوهُهُمْ فِي النَّارِ﴾؟","answer":"التقليب يصور اضطراب وجوههم في جهات النار وشدة إحاطتها بهم، ويجسد الحسرة التي يصحبها قولهم: يا ليتنا أطعنا الله والرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص514–537.","url":""}]},{"id":"s33-60","number":60,"surah":33,"verses":[67],"verseLabel":"الأحزاب: 67","question":"ما دلالة اعترافهم ﴿إِنَّا أَطَعْنَا سَادَتَنَا وَكُبَرَاءَنَا﴾؟","answer":"كشف الاعتراف أن التقليد وتعظيم الرؤساء حلّا محل الدليل، لكنه لا يرفع مسؤوليتهم؛ فقد اختاروا الطاعة التي أضلتهم ثم طلبوا مضاعفة العذاب لمتبوعيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص514–537.","url":""}]},{"id":"s33-61","number":61,"surah":33,"verses":[69],"verseLabel":"الأحزاب: 69","question":"ما سرّ النهي عن التشبه بالذين آذوا موسى عليه السلام؟","answer":"النهي يحمي مقام النبوة من الشائعات والأذى، ويستحضر أن الله برّأ موسى مما نسبوه إليه وكان وجيهًا عنده؛ فالعبرة ألا يعاد مسلك الأمم في إيذاء رسلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص538–547.","url":""}]},{"id":"s33-62","number":62,"surah":33,"verses":[70,71],"verseLabel":"الأحزاب: 70-71","question":"ما سرّ الجمع بين تقوى الله والقول السديد؟","answer":"التقوى تضبط القصد والباطن، والقول السديد يصيب الحق في الظاهر؛ ومن اجتماعهما ينشأ إصلاح العمل ومغفرة الذنب كما رتبته الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص548–561.","url":""}]},{"id":"s33-63","number":63,"surah":33,"verses":[72],"verseLabel":"الأحزاب: 72","question":"ما سرّ تمثيل ضخامة الأمانة بعرضها على السماوات والأرض والجبال ثم حمل الإنسان لها؟","answer":"التصوير يهوّل شأن التكليف والقيام بحق الاختيار حتى أشفقت منه الأجرام العظام، ثم يبرز ثقل ما حمله الإنسان وما يعرض له من ظلم وجهل إذا ضيعه؛ وليس المقصود حصر حقيقة الأمانة في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص562–592.","url":""}]},{"id":"s33-64","number":64,"surah":33,"verses":[73],"verseLabel":"الأحزاب: 73","question":"ما سرّ ختم السورة بذكر عذاب المنافقين والمشركين وتوبة الله على المؤمنين؟","answer":"ربط الختام مآلات الناس بموقفهم من الأمانة: نفاق وشرك يوجبان العذاب، وإيمان يفتح باب التوبة؛ ثم ختم بالمغفرة والرحمة الملائمتين لقبول الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص562–592.","url":""}]},{"id":"s34-1","number":1,"surah":34,"verses":[1],"verseLabel":"سبأ: 1","question":"ما وجه افتتاح سبأ بـ﴿الْحَمْدُ لِلَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾؟","answer":"أسس الحمد على الملك الشامل، ليبطل من البداية ملك الشركاء واستقلال الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص593–612.","url":""}]},{"id":"s34-2","number":2,"surah":34,"verses":[1],"verseLabel":"سبأ: 1","question":"ما سرّ التعبير بـ﴿وَلَهُ الْحَمْدُ فِي الْآخِرَةِ﴾ مع أن الحمد له في الدارين؟","answer":"خص الآخرة لأن حمده يظهر يومئذ بلا منازع ولا غفلة بعد انكشاف الحكمة والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص593–612.","url":""}]},{"id":"s34-3","number":3,"surah":34,"verses":[2],"verseLabel":"سبأ: 2","question":"ما سرّ الجمع بين ما يلج في الأرض وما يخرج منها وما ينزل من السماء وما يعرج فيها؟","answer":"أحاط حركات الكون في اتجاهاتها الأربعة، فلا تغيب ذرة عن علمه وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص613–630.","url":""}]},{"id":"s34-4","number":4,"surah":34,"verses":[2],"verseLabel":"سبأ: 2","question":"ما سرّ تقديم ﴿الرَّحِيمُ﴾ على ﴿الْغَفُورُ﴾ في ختام الآية 2؟","answer":"تقدم في السياق عموم ملك الله وعلمه بحركات الموجودات، فناسب تقديم الرحمة العامة، ثم جاءت المغفرة لما يتعلق بذنوب المكلفين؛ ولذلك خالف الترتيب الأشهر الذي يتقدم فيه ذكر الذنب والمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص613–630.","url":""}]},{"id":"s34-5","number":5,"surah":34,"verses":[3],"verseLabel":"سبأ: 3","question":"ما سرّ التعبير في قول الكافرين ﴿لَا تَأْتِينَا السَّاعَةُ﴾، ثم الرد عليهم بقوله ﴿بَلَى وَرَبِّي لَتَأْتِيَنَّكُمْ﴾؟","answer":"قابل نفيهم المجرد بقسم وتوكيد مباشر، ثم وصف علمًا لا تغيب عنه ذرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص631–658.","url":""}]},{"id":"s34-6","number":6,"surah":34,"verses":[3],"verseLabel":"سبأ: 3","question":"ما سرّ التعبير بـ﴿لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ﴾؟","answer":"العزوب غياب وبعد؛ نفاه حتى عن أصغر وزن لتثبت دقة الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص631–658.","url":""}]},{"id":"s34-7","number":7,"surah":34,"verses":[5],"verseLabel":"سبأ: 5","question":"ما سرّ التعبير عن المعاجزين بقوله ﴿لَهُمْ عَذَابٌ مِنْ رِجْزٍ أَلِيمٌ﴾؟","answer":"سعيهم لإفشال الآيات يقابله عذاب مضطرب موجع، ولا يحققون السبق الذي توهموه.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص667–680.","url":""}]},{"id":"s34-8","number":8,"surah":34,"verses":[6],"verseLabel":"سبأ: 6","question":"لماذا يعلم أهل العلم أن المنزل هو الحق ويهدي إلى صراط العزيز الحميد؟","answer":"العلم الصحيح يعبر من إحكام الوحي إلى صدق مصدره، ويجمع هيبة العزيز واستحقاق الحميد.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص681–694.","url":""}]},{"id":"s34-9","number":9,"surah":34,"verses":[7],"verseLabel":"سبأ: 7","question":"ما سرّ التعبير في قولهم ﴿هَلْ نَدُلُّكُمْ عَلَى رَجُلٍ يُنَبِّئُكُمْ﴾؟","answer":"تكلموا عن الرسول كغريب لا يعرف، واستخدموا «ينبئكم» للتهكم بخبر البعث العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص695–710.","url":""}]},{"id":"s34-10","number":10,"surah":34,"verses":[8],"verseLabel":"سبأ: 8","question":"ما سرّ وصفهم خبر البعث بأنه ﴿الضَّلَالِ الْبَعِيدِ﴾؟","answer":"جعل الضلال مكانًا بعد صاحبه عن الحق، فلا يرى طريق الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص711–730.","url":""}]},{"id":"s34-11","number":11,"surah":34,"verses":[9],"verseLabel":"سبأ: 9","question":"لماذا هددوا بكسف من السماء أو خسف من الأرض؟","answer":"من أحاطت به قدرة الله فوقه وتحته لا يعجزه فراره من البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص731–754.","url":""}]},{"id":"s34-12","number":12,"surah":34,"verses":[10],"verseLabel":"سبأ: 10","question":"ما سرّ الأمر للجبال بقوله ﴿أَوِّبِي مَعَهُ﴾؟","answer":"التأويب ترجيع التسبيح؛ صارت الجبال والطير جوقة تستجيب لصوت داود.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص755–780.","url":""}]},{"id":"s34-13","number":13,"surah":34,"verses":[10],"verseLabel":"سبأ: 10","question":"لماذا ألان الله لداود الحديد؟","answer":"جمع له قوة الروح بالتسبيح وقوة الصناعة، ليحول المعدن الصلب إلى حماية للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص755–780.","url":""}]},{"id":"s34-14","number":14,"surah":34,"verses":[11],"verseLabel":"سبأ: 11","question":"ما سرّ التعبير بـ﴿وَقَدِّرْ فِي السَّرْدِ﴾؟","answer":"أمر بتناسب حلق الدرع؛ لا تضيق فتضعف الحركة ولا تتسع فتترك منفذًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص755–780.","url":""}]},{"id":"s34-15","number":15,"surah":34,"verses":[12],"verseLabel":"سبأ: 12","question":"ما سرّ التعبير عن الريح المسخّرة لسليمان بقوله ﴿غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ﴾؟","answer":"قاس السرعة بمسافة مألوفة: تقطع في طرفي النهار ما تقطعه القوافل في شهرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص781–800.","url":""}]},{"id":"s34-16","number":16,"surah":34,"verses":[12],"verseLabel":"سبأ: 12","question":"لماذا أجرى له ﴿عَيْنَ الْقِطْرِ﴾؟","answer":"صور النحاس المذاب عينًا جارية تحت سلطانه، فاجتمعت له سرعة النقل وقوة الصناعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج45، ص781–800.","url":""}]},{"id":"s34-17","number":17,"surah":34,"verses":[13],"verseLabel":"سبأ: 13","question":"ما سرّ التعبير بـ﴿اعْمَلُوا آلَ دَاوُودَ شُكْرًا﴾ فجعل الشكر عملًا؟","answer":"قال «اعملوا» لا «اشكروا» ليجعل الشكر عملًا لا لسانًا فقط، وليحتمل «شكرًا» معاني المفعول به ولأجله والحال؛ فاتسعت الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص10–24.","url":""}]},{"id":"s34-18","number":18,"surah":34,"verses":[13],"verseLabel":"سبأ: 13","question":"ما سرّ التعبير بـ﴿وَقَلِيلٌ مِنْ عِبَادِيَ الشَّكُورُ﴾؟","answer":"صيغة «شكور» تدل على رسوخ الشكر وتكرره، وهي مرتبة لا يبلغها كثيرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص10–24.","url":""}]},{"id":"s34-19","number":19,"surah":34,"verses":[14],"verseLabel":"سبأ: 14","question":"لماذا لم يدل الجن على موت سليمان إلا دابة الأرض؟","answer":"أسقط دعوى علمهم الغيب بأضعف مخلوق يأكل منسأته حتى انكشف موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص25–38.","url":""}]},{"id":"s34-20","number":20,"surah":34,"verses":[14],"verseLabel":"سبأ: 14","question":"ما سرّ التعبير عن العصا بـ﴿مِنْسَأَتَهُ﴾؟","answer":"المنسأة هي العصا التي يُنسأ بها، أي يؤخر ويزجر؛ واختيار اسمها يستحضر وظيفة العصا في السوق والاتكاء، وهي التي أكلتها دابة الأرض فانكشف موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص25–38.","url":""}]},{"id":"s34-21","number":21,"surah":34,"verses":[15],"verseLabel":"سبأ: 15","question":"ما سرّ التعبير بـ﴿لَقَدْ كَانَ لِسَبَإٍ فِي مَسْكَنِهِمْ آيَةٌ جَنَّتَانِ عَنْ يَمِينٍ وَشِمَالٍ﴾؟","answer":"أحاط الخصب بمساكنهم من الجانبين، فكانوا داخل آية رزق وأمن لا يمرون بها فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص39–61.","url":""}]},{"id":"s34-22","number":22,"surah":34,"verses":[15],"verseLabel":"سبأ: 15","question":"ما سرّ الجمع بين ﴿بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ﴾؟","answer":"جمع نعمة المكان وستر تقصير الإنسان؛ رخاء الأرض ورحمة الرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص39–61.","url":""}]},{"id":"s34-23","number":23,"surah":34,"verses":[16],"verseLabel":"سبأ: 16","question":"ما سرّ المقابلة في قوله ﴿وَبَدَّلْنَاهُمْ بِجَنَّتَيْهِمْ جَنَّتَيْنِ﴾؟","answer":"كرر لفظ الجنتين للمقابلة بين الأصل والبدل: جنتان مثمرتان تحولتا إلى جنتين لا تحملان إلا الثمر المر والأثل وشيئًا من السدر؛ فبقي الاسم وانقلبت الحقيقة تهويلًا للخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص62–78.","url":""}]},{"id":"s34-24","number":24,"surah":34,"verses":[16],"verseLabel":"سبأ: 16","question":"لماذا كان العقاب بسيل العرم؟","answer":"جاء الهلاك من منظومة الماء التي صنعت رخاءهم؛ النعمة حين كُفرت انقلبت أداة زوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص62–78.","url":""}]},{"id":"s34-25","number":25,"surah":34,"verses":[17],"verseLabel":"سبأ: 17","question":"ما سرّ القصر في قوله ﴿وَهَلْ نُجَازِي إِلَّا الْكَفُورَ﴾؟","answer":"الاستفهام الإنكاري يفيد أن هذا الجزاء الاستئصالي لا يقع إلا على من بلغ الغاية في كفر النعمة؛ فلا يجعل كل تقصير في منزلة الكفر المستحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص79–89.","url":""}]},{"id":"s34-26","number":26,"surah":34,"verses":[18],"verseLabel":"سبأ: 18","question":"لماذا جعل بين سبأ والقرى المباركة قرى ظاهرة وقدر فيها السير؟","answer":"جمع قرب المنازل وأمن المراحل، حتى صار السفر ميسورًا ليلًا ونهارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص90–106.","url":""}]},{"id":"s34-27","number":27,"surah":34,"verses":[19],"verseLabel":"سبأ: 19","question":"لماذا دعوا ﴿رَبَّنَا بَاعِدْ بَيْنَ أَسْفَارِنَا﴾؟","answer":"بطروا سهولة النعمة وطلبوا ما يصنع التفاوت والمغامرة، فانقلب طلبهم شتاتًا حقيقيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص107–128.","url":""}]},{"id":"s34-28","number":28,"surah":34,"verses":[20],"verseLabel":"سبأ: 20","question":"ما سرّ التعبير بـ﴿وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ﴾؟","answer":"لم يملك علمًا ولا سلطانًا؛ ظن قابلية إغوائهم فاختاروا تصديقه باتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص129–139.","url":""}]},{"id":"s34-29","number":29,"surah":34,"verses":[21],"verseLabel":"سبأ: 21","question":"لماذا أعطي إبليس سلطان الاختبار؟","answer":"ليتميز من يؤمن بالآخرة ممن هو منها في شك، لا لأنه يجبر أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص140–156.","url":""}]},{"id":"s34-30","number":30,"surah":34,"verses":[22],"verseLabel":"سبأ: 22","question":"ما سرّ التعبير بـ﴿لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ﴾؟","answer":"بدأ بأصغر ملك، ثم نفى الشركة والظهير والشفاعة؛ فهدم كل صورة للاستقلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص157–176.","url":""}]},{"id":"s34-31","number":31,"surah":34,"verses":[23],"verseLabel":"سبأ: 23","question":"لماذا لا تنفع الشفاعة إلا لمن أذن له؟","answer":"حتى الوساطة التي تعلقوا بها داخلة تحت سلطان الله وليست حقًا يفرض عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص177–193.","url":""}]},{"id":"s34-32","number":32,"surah":34,"verses":[24],"verseLabel":"سبأ: 24","question":"ما سرّ الاستفهام في ﴿مَنْ يَرْزُقُكُمْ مِنَ السَّمَاوَاتِ وَالْأَرْضِ﴾ ثم أجاب ﴿قُلِ اللَّهُ﴾؟","answer":"سبق إلى الجواب الذي لا يستطيعون إنكاره، ثم أنصف المحاجة ظاهريًا: أحد الفريقين على هدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص194–208.","url":""}]},{"id":"s34-33","number":33,"surah":34,"verses":[25],"verseLabel":"سبأ: 25","question":"ما سرّ التعبير بـ﴿لَا تُسْأَلُونَ عَمَّا أَجْرَمْنَا وَلَا نُسْأَلُ عَمَّا تَعْمَلُونَ﴾؟","answer":"نسب الإجرام إلى نفسه جدلًا وأتى بعملهم محايدًا غاية الإنصاف في الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص209–220.","url":""}]},{"id":"s34-34","number":34,"surah":34,"verses":[28],"verseLabel":"سبأ: 28","question":"ما سرّ التعبير بـ﴿وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ﴾؟","answer":"قصر رسالته على العموم، فليس نذير قبيلة ولا زمن محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص231–241.","url":""}]},{"id":"s34-35","number":35,"surah":34,"verses":[31],"verseLabel":"سبأ: 31","question":"ما سرّ التعبير في قول المستضعفون للمستكبرين ﴿لَوْلَا أَنْتُمْ لَكُنَّا مُؤْمِنِينَ﴾؟","answer":"حاولوا نقل مسؤولية الاختيار إلى القادة، فتكشف الآيات جدال التابع والمتبوع بلا نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص254–269.","url":""}]},{"id":"s34-36","number":36,"surah":34,"verses":[34],"verseLabel":"سبأ: 34","question":"لماذا كان مترفو كل قرية أسرع إلى تكذيب النذير؟","answer":"الترف يربط صاحبه بالنظام القائم، فيرى الرسالة تهديدًا للمكانة لا دعوة للحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص305–321.","url":""}]},{"id":"s34-37","number":37,"surah":34,"verses":[35],"verseLabel":"سبأ: 35","question":"لماذا احتجوا بكثرة الأموال والأولاد على نجاتهم؟","answer":"قاسوا الكرامة الأخروية بالعطاء الدنيوي، مع أنه ابتلاء لا شهادة رضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص305–321.","url":""}]},{"id":"s34-38","number":38,"surah":34,"verses":[37],"verseLabel":"سبأ: 37","question":"ما سرّ التعبير بـ﴿وَمَا أَمْوَالُكُمْ وَلَا أَوْلَادُكُمْ بِالَّتِي تُقَرِّبُكُمْ عِنْدَنَا زُلْفَى﴾؟","answer":"نفى التقريب عن الأدوات بذاتها، واستثنى الإيمان والعمل الذي يحسن استعمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص333–351.","url":""}]},{"id":"s34-39","number":39,"surah":34,"verses":[39],"verseLabel":"سبأ: 39","question":"ما سرّ التعبير بـ﴿وَمَا أَنْفَقْتُمْ مِنْ شَيْءٍ فَهُوَ يُخْلِفُهُ﴾؟","answer":"عمم كل نفقة مشروعة، ووعد بخلف قد يكون مالًا أو بركة أو ثوابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص360–374.","url":""}]},{"id":"s34-40","number":40,"surah":34,"verses":[40],"verseLabel":"سبأ: 40","question":"ما دلالة سؤال الملائكة ﴿أَهَؤُلَاءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ﴾؟","answer":"لاستصدار براءتهم أمام العابدين، فتنهار دعوى الوساطة من أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص375–394.","url":""}]},{"id":"s34-41","number":41,"surah":34,"verses":[46],"verseLabel":"سبأ: 46","question":"لماذا وعظهم بواحدة: أن يقوموا لله مثنى وفرادى ثم يتفكروا؟","answer":"أزال ضغط الجماعة؛ التفكير الصادق منفردًا أو مع صاحب يكشف براءة الرسول من الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص452–468.","url":""}]},{"id":"s34-42","number":42,"surah":34,"verses":[48],"verseLabel":"سبأ: 48","question":"ما سرّ تصوير إظهار الحق بقوله ﴿إِنَّ رَبِّي يَقْذِفُ بِالْحَقِّ﴾؟","answer":"استعير القذف لإلقاء الحق بقوة وإصابته موضع الباطل، وجاء وصف الله بعلام الغيوب ليقرر أن ما يقذفه حق مصيب لا يخفى عليه محله.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص469–484.","url":""}]},{"id":"s34-43","number":43,"surah":34,"verses":[49],"verseLabel":"سبأ: 49","question":"ما سرّ التعبير بـ﴿جَاءَ الْحَقُّ وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ﴾؟","answer":"عند حضور الحق عُطل الباطل عن أول فعل وآخره؛ لا ينشئ حجة ولا يسترجع سلطانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص485–498.","url":""}]},{"id":"s34-44","number":44,"surah":34,"verses":[51],"verseLabel":"سبأ: 51","question":"ما سرّ التعبير بـ﴿فَلَا فَوْتَ وَأُخِذُوا مِنْ مَكَانٍ قَرِيبٍ﴾؟","answer":"لا مهرب حين تكون القدرة أقرب إليهم من طريق فرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص499–512.","url":""}]},{"id":"s34-45","number":45,"surah":34,"verses":[52],"verseLabel":"سبأ: 52","question":"ما سرّ التعبير في قولهم ﴿آمَنَّا بِهِ﴾ ثم قوله ﴿وَأَنَّى لَهُمُ التَّنَاوُشُ مِنْ مَكَانٍ بَعِيدٍ﴾؟","answer":"شبه تحصيل الإيمان بعد انتهاء الاختبار بتناول شيء بعيد لا تصل إليه اليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص499–512.","url":""}]},{"id":"s34-46","number":46,"surah":34,"verses":[54],"verseLabel":"سبأ: 54","question":"ما سرّ ختم السورة بأنهم حيل بينهم وبين ما يشتهون؟","answer":"جمع كل خسارتهم في حاجز نهائي بين الرغبة والقدرة، كما وقع لأشباههم من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص513–540.","url":""}]},{"id":"s35-1","number":1,"surah":35,"verses":[1],"verseLabel":"فاطر: 1","question":"ما وجه افتتاح فاطر بـ﴿الْحَمْدُ لِلَّهِ فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"بنى الحمد على الابتداء الخالق من غير مثال؛ وهو أصل دلائل السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص541–550.","url":""}]},{"id":"s35-2","number":2,"surah":35,"verses":[1],"verseLabel":"فاطر: 1","question":"ما سرّ التعبير عن الملائكة بقوله ﴿أُولِي أَجْنِحَةٍ مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾؟","answer":"بيّن تفاوت هيئاتهم وقدراتهم على تنفيذ الرسالة، ثم عمم الزيادة في الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص541–550.","url":""}]},{"id":"s35-3","number":3,"surah":35,"verses":[2],"verseLabel":"فاطر: 2","question":"ما سرّ تصوير الرحمة بالفتح في قوله ﴿مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِنْ رَحْمَةٍ﴾؟","answer":"شُبهت الرحمة بخزائن أو أبواب يفتحها مالكها للناس؛ فإذا فتح الله منها شيئًا لم تستطع قوة أن تحبسه، وفي التنكير والعموم شمول لأنواع الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص551–562.","url":""}]},{"id":"s35-4","number":4,"surah":35,"verses":[2],"verseLabel":"فاطر: 2","question":"ما سرّ المقابلة بين فتح الرحمة وإمساكها في الآية 2؟","answer":"قابل الفتح بالإمساك لإحاطة الحكم بحالتي العطاء والمنع، ثم نفى ممسكًا لما فتح ومرسلًا لما أمسك؛ فاستقل سلطان الله من الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص551–562.","url":""}]},{"id":"s35-5","number":5,"surah":35,"verses":[3],"verseLabel":"فاطر: 3","question":"ما سرّ الاستفهام في قوله ﴿هَلْ مِنْ خَالِقٍ غَيْرُ اللَّهِ يَرْزُقُكُمْ﴾؟","answer":"الاستفهام إنكاري يتحدى أن يوجد خالق غير الله يتولى الرزق من السماء والأرض؛ فإذا بطل الشريك في الخلق والرزق لزم إفراد الله بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص563–575.","url":""}]},{"id":"s35-6","number":6,"surah":35,"verses":[5],"verseLabel":"فاطر: 5","question":"لماذا نهى عن أن تغر الحياة الدنيا وأن يغر بالله الغرور؟","answer":"حذر من بريق المتاع ومن الشيطان الذي يحول حلم الله إلى أمان كاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص587–601.","url":""}]},{"id":"s35-7","number":7,"surah":35,"verses":[6],"verseLabel":"فاطر: 6","question":"ما سرّ التعبير بـ﴿إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا﴾؟","answer":"المعلومة لا تكفي؛ المطلوب تحويلها إلى موقف ومخالفة عملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص602–619.","url":""}]},{"id":"s35-8","number":8,"surah":35,"verses":[8],"verseLabel":"فاطر: 8","question":"ما سرّ التعبير بـ﴿أَفَمَنْ زُيِّنَ لَهُ سُوءُ عَمَلِهِ فَرَآهُ حَسَنًا﴾؟","answer":"المصيبة ليست فعل السوء فقط، بل انقلاب الميزان الذي يمنع التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص634–659.","url":""}]},{"id":"s35-9","number":9,"surah":35,"verses":[8],"verseLabel":"فاطر: 8","question":"ما سرّ جمع ﴿حَسَرَاتٍ﴾ في قوله ﴿فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَاتٍ﴾؟","answer":"الجمع يصور تعدد موجبات الأسف وتجددها بتجدد إعراضهم، فنُهي النبي ﷺ أن تستنفد نفسه حسرات متراكبة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص634–659.","url":""}]},{"id":"s35-10","number":10,"surah":35,"verses":[9],"verseLabel":"فاطر: 9","question":"ما سرّ التعبير بـ﴿كَذَلِكَ النُّشُورُ﴾ بعد إحياء الأرض؟","answer":"جعل إحياء الأرض الميتة بالماء مثالًا محسوسًا لنشر الأجساد بعد الموت؛ فاسم الإشارة يرد الغائب المختلف فيه إلى مشهد يرونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص660–680.","url":""}]},{"id":"s35-11","number":11,"surah":35,"verses":[10],"verseLabel":"فاطر: 10","question":"ما سرّ التعبير بـ﴿فَلِلَّهِ الْعِزَّةُ جَمِيعًا﴾؟","answer":"اللام تفيد الاختصاص، و﴿جميعًا﴾ تستغرق جنس العزة؛ فمن أرادها حقًا فليطلبها بطاعة مالكها لا بالتعلق بمن لا يملك منها شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص681–706.","url":""}]},{"id":"s35-12","number":12,"surah":35,"verses":[10],"verseLabel":"فاطر: 10","question":"لماذا يصعد الكلم الطيب ويرفعه العمل الصالح؟","answer":"القول المقبول يتجه إلى الله، والعمل يصدقه ويعليه؛ فلا يغني كلام بلا أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص681–706.","url":""}]},{"id":"s35-13","number":13,"surah":35,"verses":[11],"verseLabel":"فاطر: 11","question":"ما سرّ ذكر الخلق من تراب ثم نطفة ثم الأزواج؟","answer":"وصل أصل الإنسان الفردي بامتداد النوع، وكل مرحلة تحت علمه وتقديره.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص707–729.","url":""}]},{"id":"s35-14","number":14,"surah":35,"verses":[12],"verseLabel":"فاطر: 12","question":"ما سرّ التعبير عن البحرين بقوله ﴿وَمَا يَسْتَوِي الْبَحْرَانِ﴾ ثم ذكر منافع مشتركة؟","answer":"اختلاف العذب والملح لا يمنع أن يسخر الله كليهما للطعام والحلية والسفن.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص730–758.","url":""}]},{"id":"s35-15","number":15,"surah":35,"verses":[12],"verseLabel":"فاطر: 12","question":"ما سرّ اتصال ﴿لِتَبْتَغُوا مِنْ فَضْلِهِ﴾ بمشهد الفلك المواخر؟","answer":"جاء الابتغاء من فضل الله غايةً من تسخير البحر وشق السفن له؛ فمشهد الفلك المواخر يصل حركة السفن بالسعي في الرزق والتجارة، ثم يعقبه رجاء الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص730–758.","url":""}]},{"id":"s35-16","number":16,"surah":35,"verses":[13],"verseLabel":"فاطر: 13","question":"ما سرّ التعبير عن المعبودات بقوله ﴿مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ﴾؟","answer":"القطمير قشرة دقيقة على النواة؛ نفي ملكها يبالغ في إسقاط أدنى سلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص759–783.","url":""}]},{"id":"s35-17","number":17,"surah":35,"verses":[14],"verseLabel":"فاطر: 14","question":"لماذا يكفر الشركاء بعبادتهم يوم القيامة؟","answer":"لأن نسبتهم إلى الألوهية كذب عليهم، فيتبرؤون حين ينكشف الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج46، ص784–797.","url":""}]},{"id":"s35-18","number":18,"surah":35,"verses":[15],"verseLabel":"فاطر: 15","question":"ما سرّ التعبير بـ﴿أَنْتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ﴾؟","answer":"عرّف الطرفين وحصر الوصف: الفقر حقيقتهم الدائمة، وغناه محمود لا يمنع الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص10–18.","url":""}]},{"id":"s35-19","number":19,"surah":35,"verses":[18],"verseLabel":"فاطر: 18","question":"لماذا لا تزر وازرة وزر أخرى، ولو كانت ذات قربى؟","answer":"المسؤولية فردية، وأقوى رابطة بشرية لا تنقل حمل الذنب يوم الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص31–57.","url":""}]},{"id":"s35-20","number":20,"surah":35,"verses":[19,20,21,22],"verseLabel":"فاطر: 19-22","question":"لماذا قابل الأعمى والبصير والظلمات والنور والظل والحرور والأحياء والأموات؟","answer":"راكم مقابلات حسية حتى يتضح البعد بين الإيمان والكفر واستحالـة تسويتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص58–83.","url":""}]},{"id":"s35-21","number":21,"surah":35,"verses":[19,20,21,22],"verseLabel":"فاطر: 19-22","question":"ما سرّ تكرار ﴿مَا﴾ النافية في مقابلات ﴿وَمَا يَسْتَوِي﴾؟","answer":"كرر النفي مع كل مقابلة ليفصل صور التباين ويثبت استحالة التسوية: بين الأعمى والبصير، والظلمات والنور، والظل والحرور؛ ثم انتقل إلى نفي استواء الأحياء والأموات.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص58–83.","url":""}]},{"id":"s35-22","number":22,"surah":35,"verses":[24],"verseLabel":"فاطر: 24","question":"ما سرّ التعبير بـ﴿وَإِنْ مِنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ﴾؟","answer":"عمم سنة البيان؛ لا يعاقب الله أمة بلا وصول أصل الإنذار إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص84–94.","url":""}]},{"id":"s35-23","number":23,"surah":35,"verses":[27],"verseLabel":"فاطر: 27","question":"لماذا انتقل من ألوان الثمرات إلى جدد الجبال ثم الناس والدواب؟","answer":"وحد ظاهرة التنوع اللوني في النبات والجماد والحيوان لتشهد بوحدة المبدع.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص111–125.","url":""}]},{"id":"s35-24","number":24,"surah":35,"verses":[28],"verseLabel":"فاطر: 28","question":"ما سرّ التعبير بـ﴿إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ﴾؟","answer":"العلم الحقيقي بآيات الخلق وأسماء الله يثمر خشية، وإلا بقي معلومات بلا أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص126–138.","url":""}]},{"id":"s35-25","number":25,"surah":35,"verses":[29],"verseLabel":"فاطر: 29","question":"ما سرّ التعبير عن أهل القرآن بقوله ﴿يَرْجُونَ تِجَارَةً لَنْ تَبُورَ﴾؟","answer":"شبه التلاوة والصلاة والإنفاق برأس مال مضمون عند الله لا يصيبه كساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص139–155.","url":""}]},{"id":"s35-26","number":26,"surah":35,"verses":[30],"verseLabel":"فاطر: 30","question":"ما سرّ ختم جزاءهم بـ﴿إِنَّهُ غَفُورٌ شَكُورٌ﴾؟","answer":"يغفر النقص ويشكر القليل بالمضاعفة؛ فاجتمع ستر التقصير وزيادة الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص139–155.","url":""}]},{"id":"s35-27","number":27,"surah":35,"verses":[32],"verseLabel":"فاطر: 32","question":"لماذا قسم ورثة الكتاب إلى ظالم ومقتصد وسابق ثم قال ﴿ذَلِكَ هُوَ الْفَضْلُ الْكَبِيرُ﴾؟","answer":"مجرد الاصطفاء وحمل الكتاب فضل، وأعلاه السبق بالخيرات بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص166–183.","url":""}]},{"id":"s35-28","number":28,"surah":35,"verses":[33],"verseLabel":"فاطر: 33","question":"لماذا يحلون في الجنة أساور من ذهب ولؤلؤًا ولباسهم حرير؟","answer":"أظهر النعيم زينة ولباسًا بعد أعمال كانت في الدنيا غالبًا خفية شاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص184–195.","url":""}]},{"id":"s35-29","number":29,"surah":35,"verses":[33],"verseLabel":"فاطر: 33","question":"ما سرّ الجمع بين الذهب واللؤلؤ والحرير في وصف نعيمهم؟","answer":"جمع زينة البدن من الذهب واللؤلؤ مع نعومة اللباس من الحرير لاستكمال صورة التكريم والنعيم ظاهرًا وباطنًا؛ وفي تنكير الحرير تفخيم لجنسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص184–195.","url":""}]},{"id":"s35-30","number":30,"surah":35,"verses":[34],"verseLabel":"فاطر: 34","question":"ما سرّ التعبير في قول أهل الجنة ﴿الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ﴾ معرفًا؟","answer":"استغرق جنس الحزن أو الحزن العظيم المعروف من خوف المصير؛ لم يبق له أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص196–213.","url":""}]},{"id":"s35-31","number":31,"surah":35,"verses":[35],"verseLabel":"فاطر: 35","question":"ما سرّ التعبير في قولهم ﴿لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ﴾؟","answer":"نفوا تعب العمل ثم إعياء ما بعده، فنعيمهم بلا كلفة ولا فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص196–213.","url":""}]},{"id":"s35-32","number":32,"surah":35,"verses":[36],"verseLabel":"فاطر: 36","question":"لماذا لا يقضى على أهل النار فيموتوا ولا يخفف عنهم؟","answer":"قطع طريقي الراحة: انتهاء الإحساس بالموت أو نقص العذاب بالبقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص214–238.","url":""}]},{"id":"s35-33","number":33,"surah":35,"verses":[37],"verseLabel":"فاطر: 37","question":"لماذا يطلبون الخروج ليعملوا صالحًا غير الذي كانوا يعملون؟","answer":"اعترفوا أن المشكلة نوع العمل لا نقص الوقت، فردهم إلى عمر كاف وإنذار حاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص214–238.","url":""}]},{"id":"s35-34","number":34,"surah":35,"verses":[39],"verseLabel":"فاطر: 39","question":"ما سرّ التعبير بـ﴿هُوَ الَّذِي جَعَلَكُمْ خَلَائِفَ فِي الْأَرْضِ﴾؟","answer":"كل جيل يخلف غيره في مهلة محدودة؛ الاستخلاف أمانة لا ملك دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص247–262.","url":""}]},{"id":"s35-35","number":35,"surah":35,"verses":[40],"verseLabel":"فاطر: 40","question":"لماذا تحداهم أن يروا ماذا خلق شركاؤهم من الأرض أو شركهم في السماوات؟","answer":"قسم دعوى الألوهية إلى خلق وشركة ووحي، ثم أثبت فراغها من الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص263–288.","url":""}]},{"id":"s35-36","number":36,"surah":35,"verses":[41],"verseLabel":"فاطر: 41","question":"ما سرّ التعبير بـ﴿إِنَّ اللَّهَ يُمْسِكُ السَّمَاوَاتِ وَالْأَرْضَ أَنْ تَزُولَا﴾؟","answer":"ما يبدو ثباتًا ذاتيًا هو حفظ متجدد، ولو زال النظام لم يمسكه أحد بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص289–305.","url":""}]},{"id":"s35-37","number":37,"surah":35,"verses":[43],"verseLabel":"فاطر: 43","question":"ما سرّ التعبير بـ﴿وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِ﴾؟","answer":"صُوِّر المكر السيئ كشيء يحيط بصاحبه من كل جانب؛ والقصر يقرر رجوع وباله على أهله وإن بدا أول أمره واقعًا بغيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص306–339.","url":""}]},{"id":"s35-38","number":38,"surah":35,"verses":[43],"verseLabel":"فاطر: 43","question":"لماذا لا يجدون لسنة الله تبديلًا ولا تحويلًا؟","answer":"لا تتغير حقيقتها ولا تُصرف عن مستحقها بالمحاباة؛ التاريخ قانون أخلاقي ثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص306–339.","url":""}]},{"id":"s35-39","number":39,"surah":35,"verses":[44],"verseLabel":"فاطر: 44","question":"لماذا لم تعجز الله قوة الأمم السابقة؟","answer":"من خلق السماوات والأرض لا يحده ما جمع البشر من بطش وعمران.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص340–357.","url":""}]},{"id":"s35-40","number":40,"surah":35,"verses":[45],"verseLabel":"فاطر: 45","question":"ما دلالة قوله ﴿وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِمَا كَسَبُوا مَا تَرَكَ عَلَى ظَهْرِهَا مِنْ دَابَّةٍ﴾؟","answer":"تشابك فساد الإنسان والحياة يقتضي هلاكًا واسعًا، لكن الحلم يؤخرهم إلى أجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص358–385.","url":""}]},{"id":"s35-41","number":41,"surah":35,"verses":[45],"verseLabel":"فاطر: 45","question":"ما سرّ ختم السورة بـ﴿فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا﴾؟","answer":"التأخير ليس غفلة؛ يرى أعمال العباد ويضع الجزاء في وقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص358–385.","url":""}]},{"id":"s35-42","number":42,"surah":35,"verses":[45],"verseLabel":"فاطر: 45","question":"ما سرّ التعبير في فاطر بـ﴿عَلَى ظَهْرِهَا مِنْ دَابَّةٍ﴾، وفي النحل بـ﴿عَلَيْهَا مِنْ دَابَّةٍ﴾؟","answer":"خصت فاطر الظهر لتصوير ظاهر الأرض الذي تدب عليه المخلوقات، وفي تقديم القيد تهويل لتمام القدرة على إخلائه؛ أما آية النحل فجاءت في سياق ظلم المشركين الأشد وعممت عدم الترك بـ﴿عليها﴾ من غير تقييد بالظهر. وقد فتح مبحث فاطر المقارنة صراحة، وقوبل نص النحل في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص358–385، وج26، ص669–681.","url":""}]},{"id":"s36-1","number":1,"surah":36,"verses":[1],"verseLabel":"يس: 1","question":"ما أوجه دلالة افتتاح السورة بـ﴿يس﴾؟","answer":"هي من الحروف المقطعة على القول الأشهر، وفيها تنبيه إلى شأن القرآن وتحديه؛ وذُكرت أقوال أخرى، منها أنها نداء، فلا يحصر معناها في وجه واحد بغير دليل قاطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص386–400.","url":""}]},{"id":"s36-2","number":2,"surah":36,"verses":[2],"verseLabel":"يس: 2","question":"لماذا أقسم بـ﴿الْقُرْآنِ الْحَكِيمِ﴾؟","answer":"أقسم بالوحي المحكم ذي الحكمة على صدق الرسول الذي يحمله؛ فالدليل والقسم شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص386–400.","url":""}]},{"id":"s36-3","number":3,"surah":36,"verses":[3,4],"verseLabel":"يس: 3-4","question":"ما سرّ التعبير بـ﴿إِنَّكَ لَمِنَ الْمُرْسَلِينَ * عَلَى صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"أكدت الجملة الرسالة بـ﴿إن﴾ واللام و﴿من﴾، ثم صورت المنهج الذي جاء به الرسول طريقًا مستقيمًا؛ فاجتمع إثبات حامل الوحي واستقامة ما يحمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص386–400.","url":""}]},{"id":"s36-4","number":4,"surah":36,"verses":[5],"verseLabel":"يس: 5","question":"ما سرّ الجمع بين وصفي ﴿الْعَزِيزِ الرَّحِيمِ﴾ في إنزال القرآن؟","answer":"العزة تثبت سلطان منزل القرآن وغلبته، والرحمة تبين أن التنزيل والإنذار من آثار رحمته بالخلق؛ فاجتمع في الوحي نفاذ السلطان وقصد الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص401–404.","url":""}]},{"id":"s36-5","number":5,"surah":36,"verses":[6],"verseLabel":"يس: 6","question":"ما سرّ التعبير بـ﴿لِتُنْذِرَ قَوْمًا مَا أُنْذِرَ آبَاؤُهُمْ﴾؟","answer":"طال عليهم عهد الرسالة المباشرة فصارت الغفلة وصفًا غالبًا يحتاج إيقاظًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص405–415.","url":""}]},{"id":"s36-6","number":6,"surah":36,"verses":[8],"verseLabel":"يس: 8","question":"لماذا شبههم بمن في أعناقهم أغلال إلى الأذقان؟","answer":"صور الكبر الذي يرفع الرأس ويمنع الالتفات إلى الدليل؛ القيد نتيجة اختيارهم المعاند.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص422–434.","url":""}]},{"id":"s36-7","number":7,"surah":36,"verses":[9],"verseLabel":"يس: 9","question":"لماذا جعل من بين أيديهم سدًا ومن خلفهم سدًا؟","answer":"أحاط طريق النظر في العاقبة والماضي، ثم غشى الأبصار فبلغ الانغلاق غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص435–448.","url":""}]},{"id":"s36-8","number":8,"surah":36,"verses":[11],"verseLabel":"يس: 11","question":"ما سرّ تخصيص الإنذار بمن اتبع الذكر وخشي الرحمن بالغيب؟","answer":"الإنذار العام لا ينتفع به إلا قلب يستجيب للوحي ويراقب الرحيم وهو لا يراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص462–475.","url":""}]},{"id":"s36-9","number":9,"surah":36,"verses":[12],"verseLabel":"يس: 12","question":"ما سرّ التعبير بـ﴿وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ﴾؟","answer":"لا يحصى الفعل وحده، بل ما يظل بعده من سنة حسنة أو سيئة وخطوات إلى الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص476–493.","url":""}]},{"id":"s36-10","number":10,"surah":36,"verses":[12],"verseLabel":"يس: 12","question":"ما سرّ التعبير بـ﴿وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ فِي إِمَامٍ مُبِينٍ﴾؟","answer":"الإمام سجل جامع يرجع إليه، و«مبين» ينفي ضياع التفاصيل أو التباسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص476–493.","url":""}]},{"id":"s36-11","number":11,"surah":36,"verses":[13],"verseLabel":"يس: 13","question":"ما سرّ عدم تسمية القرية في قوله ﴿أَصْحَابَ الْقَرْيَةِ﴾؟","answer":"أُبهم اسم القرية لأن المقصود تمثيل حال أهلها في التكذيب ومجادلة الرسل، لا تعيين موضعها؛ وقد اختلف في اسمها فلا يبنى البيان على تعيين غير مقطوع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص494–502.","url":""}]},{"id":"s36-12","number":12,"surah":36,"verses":[14],"verseLabel":"يس: 14","question":"لماذا عزز الله الرسولين بثالث؟","answer":"زيادة الحجة والقوة عند استمرار التكذيب، لا حاجة الوحي إلى كثرة ليصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص503–513.","url":""}]},{"id":"s36-13","number":13,"surah":36,"verses":[15],"verseLabel":"يس: 15","question":"ما دلالة احتجاجهم بقولهم ﴿مَا أَنْتُمْ إِلَّا بَشَرٌ مِثْلُنَا﴾؟","answer":"قصروا الرسل على البشرية وجعلوا مماثلتهم لهم مانعًا من الرسالة، ثم نفوا تنزيل الرحمن؛ فالحجة تكشف قياسًا فاسدًا لا برهانًا على تكذيب الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص514–521.","url":""}]},{"id":"s36-14","number":14,"surah":36,"verses":[18],"verseLabel":"يس: 18","question":"ما سرّ التعبير في قولهم للرسل ﴿إِنَّا تَطَيَّرْنَا بِكُمْ﴾؟","answer":"التطير نسبة الشؤم إلى مجيء الرسل، وهو قلب للسبب؛ إذ جعلوا دعوة الإصلاح مصدر ما يكرهون بدل أن يراجعوا إسرافهم وأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص533–546.","url":""}]},{"id":"s36-15","number":15,"surah":36,"verses":[19],"verseLabel":"يس: 19","question":"ما سرّ التعبير في جواب الرسل ﴿طَائِرُكُمْ مَعَكُمْ﴾؟","answer":"ردوا الشؤم إلى ما يلازم القوم من كفر وإسراف، لا إلى الرسل؛ فاستعير الطائر للنصيب والعاقبة التي صنعوها بأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص547–555.","url":""}]},{"id":"s36-16","number":16,"surah":36,"verses":[20],"verseLabel":"يس: 20","question":"لماذا جاء الرجل ﴿مِنْ أَقْصَى الْمَدِينَةِ يَسْعَى﴾؟","answer":"المؤمن البعيد سبق أهل المركز إلى النصرة، والسعي يصور خوفه على قومه لا على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص556–572.","url":""}]},{"id":"s36-17","number":17,"surah":36,"verses":[21],"verseLabel":"يس: 21","question":"ما سرّ التعبير بـ﴿اتَّبِعُوا مَنْ لَا يَسْأَلُكُمْ أَجْرًا وَهُمْ مُهْتَدُونَ﴾؟","answer":"جمع نزاهة الداعي وصحة الطريق؛ فلا مصلحة تفسر دعوتهم ولا ضلال في مقصدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص556–572.","url":""}]},{"id":"s36-18","number":18,"surah":36,"verses":[22],"verseLabel":"يس: 22","question":"ما سرّ عدول الرجل المؤمن من خطاب قومه إلى قوله ﴿وَمَا لِيَ لَا أَعْبُدُ الَّذِي فَطَرَنِي﴾؟","answer":"عرض الحجة على نفسه تلطفًا في النصح، ثم عاد إلى خطابهم في ﴿وَإِلَيْهِ تُرْجَعُونَ﴾؛ فجمع رفق العرض وعموم المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص573–578.","url":""}]},{"id":"s36-19","number":19,"surah":36,"verses":[22],"verseLabel":"يس: 22","question":"لماذا انتقل من ﴿فَطَرَنِي﴾ إلى ﴿وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"بدأ بنعمته الشخصية ثم واجههم بالمصير المشترك الذي لا يختص به.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص573–578.","url":""}]},{"id":"s36-20","number":20,"surah":36,"verses":[26],"verseLabel":"يس: 26","question":"ما سرّ الانتقال إلى قوله ﴿قِيلَ ادْخُلِ الْجَنَّةَ﴾ بعد موقف الرجل المؤمن؟","answer":"حذف ما بين موقفه ودخول الجنة من أحداث، فطُوي ذكر قتله وانتقل النظم سريعًا إلى كرامته؛ وفي الإيجاز تعظيم لفوز المؤمن وتصغير لما ناله في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص599–611.","url":""}]},{"id":"s36-21","number":21,"surah":36,"verses":[26,27],"verseLabel":"يس: 26-27","question":"لماذا تمنى أن يعلم قومه بمغفرة ربه له؟","answer":"بقي ناصحًا بعد أذاهم؛ أراد أن يصير مصيره نفسه حجة تنقذهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص599–611.","url":""}]},{"id":"s36-22","number":22,"surah":36,"verses":[29],"verseLabel":"يس: 29","question":"ما سرّ التعبير عن هلاكهم بقوله ﴿إِلَّا صَيْحَةً وَاحِدَةً فَإِذَا هُمْ خَامِدُونَ﴾؟","answer":"قابل ضجيج تهديدهم بصوت واحد يطفئ حركتهم كما تخمد النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص612–625.","url":""}]},{"id":"s36-23","number":23,"surah":36,"verses":[30],"verseLabel":"يس: 30","question":"ما سرّ التعبير بـ﴿يَا حَسْرَةً عَلَى الْعِبَادِ﴾؟","answer":"نداء تهويل لحال يكرر فيها البشر الاستهزاء بكل رسول حتى يستحقوا الحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص626–634.","url":""}]},{"id":"s36-24","number":24,"surah":36,"verses":[33],"verseLabel":"يس: 33","question":"ما سرّ الجمع بين إحياء الأرض وإخراج الحب منها ثم قوله ﴿فَمِنْهُ يَأْكُلُونَ﴾؟","answer":"انتقل من المعجزة الكونية إلى اللقمة اليومية ليجعل دليل البعث في يد كل إنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص647–656.","url":""}]},{"id":"s36-25","number":25,"surah":36,"verses":[35],"verseLabel":"يس: 35","question":"ما أوجه دلالة ﴿وَمَا عَمِلَتْهُ أَيْدِيهِمْ﴾ في الآية 35؟","answer":"تحتمل ﴿ما﴾ النفي، أي الثمر ليس من صنع أيديهم، وتحتمل الموصولية، أي ومن الذي عملته أيديهم من معالجة وغرس؛ وفي القراءتين رد النعمة إلى الله مع إثبات مباشرة البشر لأسبابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص657–670.","url":""}]},{"id":"s36-26","number":26,"surah":36,"verses":[36],"verseLabel":"يس: 36","question":"ما سرّ التعبير بـ﴿سُبْحَانَ الَّذِي خَلَقَ الْأَزْوَاجَ كُلَّهَا﴾؟","answer":"نزه الخالق الذي أودع التقابل والتكامل في النبات والإنسان وما لا يعلمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص671–679.","url":""}]},{"id":"s36-27","number":27,"surah":36,"verses":[37],"verseLabel":"يس: 37","question":"ما سرّ التعبير بـ﴿وَآيَةٌ لَهُمُ اللَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ﴾؟","answer":"شبه إزالة الضوء بسلخ جلد يغطي ما تحته، فإذا نزع ظهر الظلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص680–690.","url":""}]},{"id":"s36-28","number":28,"surah":36,"verses":[38],"verseLabel":"يس: 38","question":"ما سرّ التعبير عن الشمس بقوله ﴿تَجْرِي لِمُسْتَقَرٍّ لَهَا﴾؟","answer":"حركتها منضبطة إلى حد مكاني أو زمني قدره العزيز العليم، لا سيرًا عشوائيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص691–698.","url":""}]},{"id":"s36-29","number":29,"surah":36,"verses":[39],"verseLabel":"يس: 39","question":"ما سرّ تشبيه القمر في آخر منازله بـ﴿الْعُرْجُونِ الْقَدِيمِ﴾؟","answer":"دقته وانحناؤه واصفراره تشبه عود العذق اليابس، صورة يراها أهل النخل فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص699–706.","url":""}]},{"id":"s36-30","number":30,"surah":36,"verses":[40],"verseLabel":"يس: 40","question":"ما سرّ التعبير بـ﴿لَا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ﴾؟","answer":"لكل جرم نظام وحد لا يتعداه، وتعاقب الليل والنهار شاهد انتظام لا صراع.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص707–717.","url":""}]},{"id":"s36-31","number":31,"surah":36,"verses":[41],"verseLabel":"يس: 41","question":"ما سرّ التعبير بـ﴿وَحَمَلْنَا ذُرِّيَّتَهُمْ فِي الْفُلْكِ الْمَشْحُونِ﴾؟","answer":"ذكّر بنجاة أصل البشر مع نوح أو بحمل نسلهم في السفن الممتلئة، فالإنقاذ نعمة ممتدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص718–730.","url":""}]},{"id":"s36-32","number":32,"surah":36,"verses":[45],"verseLabel":"يس: 45","question":"ما سرّ حذف جواب الشرط بعد قوله ﴿وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ﴾؟","answer":"حُذف جواب ﴿إذا﴾ لدلالة السياق التالي عليه؛ إذ كلما جاءتهم آية أعرضوا. فالحذف يصور أن عرض التقوى لم يلق جوابًا إلا الإعراض، ويترك تقديره لما يكشفه السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص750–755.","url":""}]},{"id":"s36-33","number":33,"surah":36,"verses":[47],"verseLabel":"يس: 47","question":"ما دلالة احتجاج الكافرين ﴿أَنُطْعِمُ مَنْ لَوْ يَشَاءُ اللَّهُ أَطْعَمَهُ﴾؟","answer":"احتجوا بالمشيئة على ترك واجب الإنفاق، فجعلوا قدر الله ذريعة لإبطال أمره؛ مع أن من سنته أن يجري رزق بعض عباده على أيدي بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص766–777.","url":""}]},{"id":"s36-34","number":34,"surah":36,"verses":[49],"verseLabel":"يس: 49","question":"لماذا لا ينتظرون إلا صيحة واحدة تأخذهم وهم يخصمون؟","answer":"تأتي الساعة وسط انشغالهم بجدال الدنيا، فلا يمنحهم توقعها وقت استعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج47، ص784–791.","url":""}]},{"id":"s36-35","number":35,"surah":36,"verses":[51],"verseLabel":"يس: 51","question":"ما سرّ التعبير بـ﴿فَإِذَا هُمْ مِنَ الْأَجْدَاثِ إِلَى رَبِّهِمْ يَنْسِلُونَ﴾؟","answer":"«ينسلون» يسرعون في الخروج، و«إلى ربهم» تحدد جهة لا يستطيعون تحويلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص10–17.","url":""}]},{"id":"s36-36","number":36,"surah":36,"verses":[52],"verseLabel":"يس: 52","question":"ما سرّ التعبير في قولهم ﴿مَنْ بَعَثَنَا مِنْ مَرْقَدِنَا﴾؟","answer":"سُمّي القبر مرقدًا بالنظر إلى هيئة المكث أو قصره في شعورهم عند البعث، ثم يجيب السياق بأن هذا هو ما وعد الرحمن وصدق المرسلون؛ فلا يدل اللفظ على إنكار بعث سابق بعد ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص18–29.","url":""}]},{"id":"s36-37","number":37,"surah":36,"verses":[55],"verseLabel":"يس: 55","question":"ما سرّ التعبير بـ﴿إِنَّ أَصْحَابَ الْجَنَّةِ الْيَوْمَ فِي شُغُلٍ فَاكِهُونَ﴾؟","answer":"شغلهم نعيم محبب لا تعب فيه، في مقابلة خصومة أهل الدنيا وحسرة المجرمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص44–51.","url":""}]},{"id":"s36-38","number":38,"surah":36,"verses":[58],"verseLabel":"يس: 58","question":"ما سرّ التعبير بـ﴿سَلَامٌ قَوْلًا مِنْ رَبٍّ رَحِيمٍ﴾؟","answer":"ارتفع من نعيم المكان إلى خطاب الرب نفسه، صادرًا من الرحمة ومحققًا للأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص66–70.","url":""}]},{"id":"s36-39","number":39,"surah":36,"verses":[59],"verseLabel":"يس: 59","question":"ما سرّ الأمر للمجرمين بقوله ﴿وَامْتَازُوا الْيَوْمَ﴾؟","answer":"أمرهم أن ينفصلوا عن المؤمنين انفصال مصير بعد أن اختلطوا بهم في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص71–76.","url":""}]},{"id":"s36-40","number":40,"surah":36,"verses":[60],"verseLabel":"يس: 60","question":"ما سرّ تسمية طاعة الشيطان عبادةً في قوله ﴿أَنْ لَا تَعْبُدُوا الشَّيْطَانَ﴾؟","answer":"العبادة هنا تشمل الطاعة والانقياد للشيطان في معصية الله، لا السجود له وحده؛ ولذلك قابلها الأمر بعبادة الله وبيّن أن الشيطان عدو مضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص77–86.","url":""}]},{"id":"s36-41","number":41,"surah":36,"verses":[65],"verseLabel":"يس: 65","question":"لماذا تختم الأفواه وتتكلم الأيدي وتشهد الأرجل؟","answer":"يسقط سلطان اللسان الذي اعتاد الإنكار، وتنطق أدوات العمل بالحقيقة التي باشرتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص109–120.","url":""}]},{"id":"s36-42","number":42,"surah":36,"verses":[66],"verseLabel":"يس: 66","question":"ما سرّ التعبير بـ﴿لَطَمَسْنَا عَلَى أَعْيُنِهِمْ فَاسْتَبَقُوا الصِّرَاطَ فَأَنَّى يُبْصِرُونَ﴾؟","answer":"لو محا أبصارهم لتنافسوا على الطريق بلا إمكان رؤيته؛ قدرة تسلب الوسيلة في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص121–131.","url":""}]},{"id":"s36-43","number":43,"surah":36,"verses":[68],"verseLabel":"يس: 68","question":"ما سرّ التعبير بـ﴿وَمَنْ نُعَمِّرْهُ نُنَكِّسْهُ فِي الْخَلْقِ﴾؟","answer":"منحنى القوة يعود ضعفًا؛ والتنكيس برهان أن العمر لا يمضي صعودًا دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص142–150.","url":""}]},{"id":"s36-44","number":44,"surah":36,"verses":[69],"verseLabel":"يس: 69","question":"ما سرّ نفي الشعر عن النبي ﷺ والتعبير بـ﴿وَمَا يَنْبَغِي لَهُ﴾؟","answer":"طبيعة الوحي وصدق مقاصده لا تلائم تخييل الشعر الذي اتهموه به، وهو ذكر وقرآن مبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص151–161.","url":""}]},{"id":"s36-45","number":45,"surah":36,"verses":[71],"verseLabel":"يس: 71","question":"ما سرّ التعبير بـ﴿مِمَّا عَمِلَتْ أَيْدِينَا أَنْعَامًا﴾؟","answer":"نسب الخلق إلى قدرته مباشرة، ثم أظهر تسخير الحيوان الكبير للإنسان الضعيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص168–177.","url":""}]},{"id":"s36-46","number":46,"surah":36,"verses":[74],"verseLabel":"يس: 74","question":"ما سرّ المقابلة بين رجائهم النصر من الآلهة وقوله ﴿لَا يَسْتَطِيعُونَ نَصْرَهُمْ﴾؟","answer":"واجه غاية العبادة بعكسها: المعبودات لا تنصر بل يحضر عابدوها جندًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص191–197.","url":""}]},{"id":"s36-47","number":47,"surah":36,"verses":[77],"verseLabel":"يس: 77","question":"ما سرّ الاحتجاج على البعث بخلق الإنسان من نطفة ثم صيرورته ﴿خَصِيمٌ مُبِينٌ﴾؟","answer":"من مادة مهينة صار قادرًا على الجدال، ثم استعمل القدرة الموهوبة لإنكار واهبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص213–227.","url":""}]},{"id":"s36-48","number":48,"surah":36,"verses":[78],"verseLabel":"يس: 78","question":"ما سرّ التعبير بـ﴿وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ﴾؟","answer":"استدل بالعظم البالي ونسي المثال الأقرب: خلق نفسه أول مرة من عدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص228–237.","url":""}]},{"id":"s36-49","number":49,"surah":36,"verses":[80],"verseLabel":"يس: 80","question":"ما سرّ الجمع بين الشجر الأخضر وإيقاد النار منه؟","answer":"جمع الماء والنار في محل واحد؛ من أخرج الضد من الضد قادر على إحياء العظام.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص246–253.","url":""}]},{"id":"s36-50","number":50,"surah":36,"verses":[82],"verseLabel":"يس: 82","question":"ما سرّ التعبير بـ﴿إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"قصر شأن قدرته على إرادة نافذة بلا معالجة أو زمن يعجزها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص262–267.","url":""}]},{"id":"s36-51","number":51,"surah":36,"verses":[83],"verseLabel":"يس: 83","question":"ما سرّ ختم السورة بـ﴿فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"نزه مالك باطن السلطان وظاهره عن العجز، ورد كل أدلة السورة إلى الرجوع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص268–274.","url":""}]},{"id":"s37-1","number":1,"surah":37,"verses":[1,2,3],"verseLabel":"الصافات: 1-3","question":"ما سرّ افتتاح السورة بالقسم ﴿وَالصَّافَّاتِ صَفًّا * فَالزَّاجِرَاتِ زَجْرًا * فَالتَّالِيَاتِ ذِكْرًا﴾؟","answer":"أقسم بطوائف تصف وتزجر وتتلو الذكر؛ وأشهر الأقوال حملها على الملائكة في انتظام عبادتهم ووظائفهم، مع ذكر أقوال أخرى في الموصوف. وجاء جواب القسم بتوحيد الإله، فناسبه انتظام المأمورين ووحدة الآمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص283–298.","url":""}]},{"id":"s37-2","number":2,"surah":37,"verses":[4],"verseLabel":"الصافات: 4","question":"ما سرّ مجيء جواب الأقسام بقوله ﴿إِنَّ إِلَهَكُمْ لَوَاحِدٌ﴾؟","answer":"انتظام الجند ووحدة تدبير الكون دليلان على وحدة الآمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص283–298.","url":""}]},{"id":"s37-3","number":3,"surah":37,"verses":[6],"verseLabel":"الصافات: 6","question":"ما أوجه تركيب ﴿بِزِينَةٍ الْكَوَاكِبِ﴾ ودلالته؟","answer":"قُرئت الإضافة في ﴿زينةِ الكواكبِ﴾، وقُرئ تنوين ﴿زينةٍ﴾ مع جر الكواكب على البدل أو البيان؛ وفي الوجوه جعل الكواكب زينة للسماء الدنيا مع ما يلي من معنى الحفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص299–324.","url":""}]},{"id":"s37-4","number":4,"surah":37,"verses":[7,8,9,10],"verseLabel":"الصافات: 7-10","question":"لماذا ربط حفظ السماء بالشهب التي تتبع الشياطين؟","answer":"أبطل زعم تلقي الكهان خبر الغيب؛ من يسترق السمع يطرد ولا يملك الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص299–324.","url":""}]},{"id":"s37-5","number":5,"surah":37,"verses":[11],"verseLabel":"الصافات: 11","question":"ما دلالة الاستفهام في قوله ﴿أَهُمْ أَشَدُّ خَلْقًا أَمْ مَنْ خَلَقْنَا﴾؟","answer":"قارن الإنسان المتكبر بالسماوات والملائكة، ثم ذكّره بأصله من طين لازب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص325–351.","url":""}]},{"id":"s37-6","number":6,"surah":37,"verses":[11],"verseLabel":"الصافات: 11","question":"ما سرّ وصف الطين بأنه ﴿لَازِبٍ﴾؟","answer":"هو لاصق متماسك؛ أصل مادي ضعيف يناقض استبعادهم إعادة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص325–351.","url":""}]},{"id":"s37-7","number":7,"surah":37,"verses":[12],"verseLabel":"الصافات: 12","question":"ما أوجه القراءة والدلالة في قوله ﴿بَلْ عَجِبْتَ وَيَسْخَرُونَ﴾؟","answer":"في قراءة فتح التاء عجب النبي ﷺ من حالهم مع وضوح الحجة وهم يسخرون، وفي قراءة الضم أُسند العجب إلى الله على الوجه اللائق به؛ فلا يصح حصر الآية في توجيه قراءة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص325–351.","url":""}]},{"id":"s37-8","number":8,"surah":37,"verses":[19],"verseLabel":"الصافات: 19","question":"ما سرّ التعبير في قول ﴿فَإِنَّمَا هِيَ زَجْرَةٌ وَاحِدَةٌ فَإِذَا هُمْ يَنْظُرُونَ﴾؟","answer":"البعث الذي عظموه لا يحتاج إلا صيحة، و«إذا» تفاجئ بقيامهم مبصرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص352–374.","url":""}]},{"id":"s37-9","number":9,"surah":37,"verses":[22,23],"verseLabel":"الصافات: 22-23","question":"ما سرّ التعبير في قول ﴿فَاهْدُوهُمْ إِلَى صِرَاطِ الْجَحِيمِ﴾؟","answer":"استعمل فعل الهداية في سوقهم إلى طريق الجحيم على سبيل التهكم والمشاكلة؛ فقد أعرضوا عن طريق الهدى في الدنيا، فدلوا يومئذ على الطريق الموصل إلى جزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص352–374.","url":""}]},{"id":"s37-10","number":10,"surah":37,"verses":[24],"verseLabel":"الصافات: 24","question":"لماذا أوقفوا للسؤال قبل النار؟","answer":"لإظهار العدل والتوبيخ وسقوط الحجة قبل تنفيذ العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص352–374.","url":""}]},{"id":"s37-11","number":11,"surah":37,"verses":[25],"verseLabel":"الصافات: 25","question":"لماذا يسأل بعضهم ﴿مَا لَكُمْ لَا تَنَاصَرُونَ﴾؟","answer":"تهكم بمن طلبوا القوة من الجماعة والآلهة؛ يومئذ استسلمت الروابط كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص375–383.","url":""}]},{"id":"s37-12","number":12,"surah":37,"verses":[27],"verseLabel":"الصافات: 27","question":"لماذا أقبل بعضهم على بعض يتساءلون بعد أن كانوا لا يتناصرون؟","answer":"لا يملكون إنقاذًا، فلم يبق إلا تبادل اللوم بين الأتباع والقادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص384–389.","url":""}]},{"id":"s37-13","number":13,"surah":37,"verses":[28],"verseLabel":"الصافات: 28","question":"ما أوجه دلالة قولهم ﴿إِنَّكُمْ كُنْتُمْ تَأْتُونَنَا عَنِ الْيَمِينِ﴾؟","answer":"ذُكرت لليمين وجوه متقاربة: جهة القوة والغلبة، أو جهة الخير والدين والثقة؛ والمعنى أنهم اتهموا قادتهم بأنهم أتوهم من المدخل الذي يطمئنون إليه، فلا يحصر اللفظ في صورة مكانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص390–414.","url":""}]},{"id":"s37-14","number":14,"surah":37,"verses":[35],"verseLabel":"الصافات: 35","question":"لماذا كانوا إذا قيل لهم ﴿لَا إِلَهَ إِلَّا اللَّهُ يَسْتَكْبِرُونَ﴾؟","answer":"الكلمات قليلة، لكن لازمها إسقاط سلطان الأصنام والكبراء، فرفضوا الانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص424–435.","url":""}]},{"id":"s37-15","number":15,"surah":37,"verses":[37],"verseLabel":"الصافات: 37","question":"ما سرّ التعبير في الرد بقوله ﴿بَلْ جَاءَ بِالْحَقِّ وَصَدَّقَ الْمُرْسَلِينَ﴾؟","answer":"أثبت صدق رسالته واتصالها بجميع الرسل؛ ليس شاعرًا شاذًا بل خاتم طريق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص436–441.","url":""}]},{"id":"s37-16","number":16,"surah":37,"verses":[40,41],"verseLabel":"الصافات: 40-41","question":"لماذا استثنى ﴿عِبَادَ اللَّهِ الْمُخْلَصِينَ﴾ وجعل لهم رزقًا معلومًا؟","answer":"أخلصهم الله فنجوا من الذوق، ورزقهم ثابت معروف لا يخشى انقطاعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص450–479.","url":""}]},{"id":"s37-17","number":17,"surah":37,"verses":[45,46,47],"verseLabel":"الصافات: 45-47","question":"ما سرّ الجمع في خمر الجنة بين ﴿بَيْضَاءَ لَذَّةٍ﴾ ونفي الغول والنزف؟","answer":"أثبت صفاء اللون ولذة الشرب، ثم نفى ما يفسد خمر الدنيا من أذى وذهاب عقل أو نفاد للشراب بحسب توجيه ﴿يُنزَفون﴾؛ فاجتمع كمال اللذة وانتفاء المضرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص450–479.","url":""}]},{"id":"s37-18","number":18,"surah":37,"verses":[48],"verseLabel":"الصافات: 48","question":"ما سرّ وصف الحور بـ﴿قَاصِرَاتُ الطَّرْفِ عِينٌ﴾؟","answer":"جمع اختصاص النظر بأزواجهن وجمال العيون، فالجمال مصون بالوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص450–479.","url":""}]},{"id":"s37-19","number":19,"surah":37,"verses":[49],"verseLabel":"الصافات: 49","question":"ما سرّ تشبيههن بـ﴿بَيْضٌ مَكْنُونٌ﴾؟","answer":"بياض ناعم محفوظ لم تمسه يد ولا غبار؛ جمع اللون والصيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص450–479.","url":""}]},{"id":"s37-20","number":20,"surah":37,"verses":[51],"verseLabel":"الصافات: 51","question":"لماذا تذكر أحد أهل الجنة قرينه المشكك؟","answer":"وسط النعيم يظهر الفرق الذي صنعته الصحبة والموقف من البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص480–487.","url":""}]},{"id":"s37-21","number":21,"surah":37,"verses":[55],"verseLabel":"الصافات: 55","question":"لماذا اطلع فرآه في سواء الجحيم؟","answer":"جعله في وسطها وأشد مواضعها، ليكتمل إدراك نعمة النجاة من تأثيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص501–518.","url":""}]},{"id":"s37-22","number":22,"surah":37,"verses":[62],"verseLabel":"الصافات: 62","question":"ما دلالة الاستفهام في قوله ﴿أَذَلِكَ خَيْرٌ نُزُلًا أَمْ شَجَرَةُ الزَّقُّومِ﴾؟","answer":"قارن ضيافة الجنة بطعام النار تهكمًا بمن اختار سبب الثانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص537–565.","url":""}]},{"id":"s37-23","number":23,"surah":37,"verses":[65],"verseLabel":"الصافات: 65","question":"ما سرّ تشبيه طلع الزقوم برؤوس الشياطين مع أنهم لم يروها؟","answer":"صورة الشيطان مستقرة في الخيال رمزًا لأقصى القبح، فاستدعاها للتهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص537–565.","url":""}]},{"id":"s37-24","number":24,"surah":37,"verses":[69,70],"verseLabel":"الصافات: 69-70","question":"لماذا وجدوا آباءهم ضالين ثم على آثارهم يهرعون؟","answer":"لم يتبعوهم بتؤدة بل أسرعوا، كأن الأثر وحده يغني عن فحص الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص566–573.","url":""}]},{"id":"s37-25","number":25,"surah":37,"verses":[75],"verseLabel":"الصافات: 75","question":"ما سرّ التعبير في قول ﴿وَلَقَدْ نَادَانَا نُوحٌ فَلَنِعْمَ الْمُجِيبُونَ﴾؟","answer":"قابل امتداد كربه بسرعة إجابة الله، وجاء الجمع للتعظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص590–599.","url":""}]},{"id":"s37-26","number":26,"surah":37,"verses":[77],"verseLabel":"الصافات: 77","question":"لماذا جعل ذرية نوح هم الباقين؟","answer":"بعد الطوفان صار امتداد البشر من ذريته، فتحولت نجاته إلى حفظ النوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص600–615.","url":""}]},{"id":"s37-27","number":27,"surah":37,"verses":[79],"verseLabel":"الصافات: 79","question":"ما سرّ التعبير في قول ﴿سَلَامٌ عَلَى نُوحٍ فِي الْعَالَمِينَ﴾؟","answer":"جاء السلام نكرة للتعظيم، وامتد بـ﴿في العالمين﴾ ليخلد الثناء والأمان على نوح في الأمم؛ ثم علل ذلك بجزاء المحسنين وإيمانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص600–615.","url":""}]},{"id":"s37-28","number":28,"surah":37,"verses":[83],"verseLabel":"الصافات: 83","question":"ما سرّ التعبير في قول ﴿وَإِنَّ مِنْ شِيعَتِهِ لَإِبْرَاهِيمَ﴾؟","answer":"جعل إبراهيم من أتباع نوح في أصل التوحيد رغم تباعد الزمن؛ وحدة المنهج تنشئ القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص616–640.","url":""}]},{"id":"s37-29","number":29,"surah":37,"verses":[84],"verseLabel":"الصافات: 84","question":"ما سرّ وصف قلب إبراهيم عليه السلام بأنه ﴿قَلْبٍ سَلِيمٍ﴾؟","answer":"سلامته من الشرك والغل هي الأصل الذي خرجت منه محاجته وتضحيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص616–640.","url":""}]},{"id":"s37-30","number":30,"surah":37,"verses":[88,89],"verseLabel":"الصافات: 88-89","question":"ما أوجه دلالة نظر إبراهيم في النجوم وقوله ﴿إِنِّي سَقِيمٌ﴾؟","answer":"ذُكرت في النظر وقوله ﴿إني سقيم﴾ وجوه، منها التعريض بسقم يعرض للإنسان أو سقم القلب من شركهم، واتخاذ ذلك وسيلة للتخلف عن عيدهم؛ ولا تحمل الآية على تصديق التنجيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص616–640.","url":""}]},{"id":"s37-31","number":31,"surah":37,"verses":[91],"verseLabel":"الصافات: 91","question":"ما سرّ مخاطبة إبراهيم الأصنام بقوله ﴿أَلَا تَأْكُلُونَ * مَا لَكُمْ لَا تَنْطِقُونَ﴾؟","answer":"حول طعام القرابين إلى اختبار ساخر لعجز المعبود عن أبسط فعل وجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص641–663.","url":""}]},{"id":"s37-32","number":32,"surah":37,"verses":[93],"verseLabel":"الصافات: 93","question":"ما أوجه دلالة ﴿بِالْيَمِينِ﴾ في قوله ﴿فَرَاغَ عَلَيْهِمْ ضَرْبًا بِالْيَمِينِ﴾؟","answer":"تحتمل اليمين اليد اليمنى، وتأتي بمعنى القوة، وقيل: باليمين التي حلفها في شأن الأصنام؛ لذلك يثبت تعدد الأوجه ولا يحصر التركيب في واحد منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص641–663.","url":""}]},{"id":"s37-33","number":33,"surah":37,"verses":[99],"verseLabel":"الصافات: 99","question":"ما سرّ التعبير بعد النجاة بقوله ﴿إِنِّي ذَاهِبٌ إِلَى رَبِّي سَيَهْدِينِ﴾؟","answer":"الهجرة إلى مكان يعبد فيه الله صارت ذهابًا إليه، والهداية مفتوحة لما لم يعرفه من الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص664–686.","url":""}]},{"id":"s37-34","number":34,"surah":37,"verses":[100],"verseLabel":"الصافات: 100","question":"ما سرّ دعاء إبراهيم ﴿رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ﴾ دون التصريح بالولد؟","answer":"طلب الصفة قبل الشخص؛ قيمة الذرية في صلاحها لا مجرد وجودها.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص664–686.","url":""}]},{"id":"s37-35","number":35,"surah":37,"verses":[102],"verseLabel":"الصافات: 102","question":"ما سرّ التعبير في قول الابن ﴿يَا أَبَتِ افْعَلْ مَا تُؤْمَرُ﴾؟","answer":"لم يقل «اذبحني»؛ رد الفعل إلى أمر الله الذي يطيعانه معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص664–686.","url":""}]},{"id":"s37-36","number":36,"surah":37,"verses":[102],"verseLabel":"الصافات: 102","question":"ما سرّ التعبير في قول ﴿سَتَجِدُنِي إِنْ شَاءَ اللَّهُ مِنَ الصَّابِرِينَ﴾؟","answer":"وعد بالصبر معلقًا على المشيئة، فلم يغتر بقوته أمام امتحان لم يقع بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص664–686.","url":""}]},{"id":"s37-37","number":37,"surah":37,"verses":[103],"verseLabel":"الصافات: 103","question":"ما سرّ التعبير في قول ﴿فَلَمَّا أَسْلَمَا وَتَلَّهُ لِلْجَبِينِ﴾؟","answer":"جمع انقياد القلبين والفعل الجسدي؛ وصرعه على جبينه ليتم الامتثال بعيدًا عن عاطفة النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص687–703.","url":""}]},{"id":"s37-38","number":38,"surah":37,"verses":[104,105],"verseLabel":"الصافات: 104-105","question":"ما سرّ التعبير بالنداء ﴿قَدْ صَدَّقْتَ الرُّؤْيَا﴾ قبل وقوع الذبح؟","answer":"تحقق مقصود الامتحان ببذل الإرادة وتنفيذ المقدمات، لا بسفك الدم لذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص687–703.","url":""}]},{"id":"s37-39","number":39,"surah":37,"verses":[107],"verseLabel":"الصافات: 107","question":"ما سرّ التعبير في قول ﴿وَفَدَيْنَاهُ بِذِبْحٍ عَظِيمٍ﴾؟","answer":"عظُم بقبوله وفدائه نبيًا وصيرورته شعيرة باقية تذكر بالتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص687–703.","url":""}]},{"id":"s37-40","number":40,"surah":37,"verses":[112],"verseLabel":"الصافات: 112","question":"لماذا بشّر بإسحاق نبيًا من الصالحين بعد قصة الذبح؟","answer":"زاد على هبة الولد هبة النبوة والصلاح، واستأنف فرعًا آخر من بركة إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص704–721.","url":""}]},{"id":"s37-41","number":41,"surah":37,"verses":[125],"verseLabel":"الصافات: 125","question":"ما سرّ استفهام إلياس لقومه بقوله ﴿أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ الْخَالِقِينَ﴾؟","answer":"سمى صنمهم ثم قابله بمن له كمال الخلق والربوبية لهم ولآبائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص744–755.","url":""}]},{"id":"s37-42","number":42,"surah":37,"verses":[139],"verseLabel":"الصافات: 139","question":"ما سرّ إثبات رسالة يونس قبل قوله ﴿إِذْ أَبَقَ إِلَى الْفُلْكِ الْمَشْحُونِ﴾؟","answer":"قُدّم إثبات رسالته صونًا لمقام النبوة قبل حكاية ما وقع منه، ثم عبّر بالإباق لتشبيه خروجه قبل الإذن بخروج العبد من سيده في شدة المفارقة، مع بقاء اصطفائه رسولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص788–807.","url":""}]},{"id":"s37-43","number":43,"surah":37,"verses":[141],"verseLabel":"الصافات: 141","question":"لماذا ساهم يونس فكان من المدحضين؟","answer":"وقعت القرعة عليه مرارًا فغُلبت حجته، ليبدأ تدبير العودة في بطن الحوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص788–807.","url":""}]},{"id":"s37-44","number":44,"surah":37,"verses":[143,144],"verseLabel":"الصافات: 143-144","question":"ما دلالة قوله ﴿فَلَوْلَا أَنَّهُ كَانَ مِنَ الْمُسَبِّحِينَ * لَلَبِثَ فِي بَطْنِهِ إِلَى يَوْمِ يُبْعَثُونَ﴾؟","answer":"عبادته السابقة وتسبيحه في الكرب صارا سبب النجاة؛ الرصيد الصادق يعمل عند الضيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج48، ص788–807.","url":""}]},{"id":"s37-45","number":45,"surah":37,"verses":[145],"verseLabel":"الصافات: 145","question":"لماذا نبذ بالعراء وهو سقيم؟","answer":"أخرجه الحوت إلى أرض مكشوفة بلا ساتر وهو ضعيف، فظهرت حاجته إلى عناية اليقطين.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص10–25.","url":""}]},{"id":"s37-46","number":46,"surah":37,"verses":[147],"verseLabel":"الصافات: 147","question":"ما أوجه دلالة ﴿أَوْ يَزِيدُونَ﴾ في قوله ﴿مِائَةِ أَلْفٍ أَوْ يَزِيدُونَ﴾؟","answer":"ذُكرت وجوه، أشهرها أن ﴿أو﴾ على تقدير الناظر؛ من رآهم قال: مائة ألف أو أكثر، وقيل هي للإضراب بمعنى بل يزيدون. فلا تحمل على الشك في علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص10–25.","url":""}]},{"id":"s37-47","number":47,"surah":37,"verses":[149],"verseLabel":"الصافات: 149","question":"ما سرّ الاستفهام في قوله ﴿أَلِرَبِّكَ الْبَنَاتُ وَلَهُمُ الْبَنُونَ﴾؟","answer":"الاستفهام إنكاري يفضح تناقضهم: جعلوا لله البنات مع كراهتهم لهن، وخصوا أنفسهم بالبنين؛ فبطل أصل النسبة وبان فساد قسمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص26–42.","url":""}]},{"id":"s37-48","number":48,"surah":37,"verses":[164,165,166],"verseLabel":"الصافات: 164-166","question":"ما سرّ التعبير في قول الملائكة ﴿وَمَا مِنَّا إِلَّا لَهُ مَقَامٌ مَعْلُومٌ * وَإِنَّا لَنَحْنُ الصَّافُّونَ﴾؟","answer":"أثبتوا عبوديتهم ونظام وظائفهم، فكيف يجعلهم المشركون بناتًا أو شركاء؟","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص77–87.","url":""}]},{"id":"s37-49","number":49,"surah":37,"verses":[171,172,173],"verseLabel":"الصافات: 171-173","question":"ما سرّ التعبير في قول ﴿إِنَّهُمْ لَهُمُ الْمَنْصُورُونَ * وَإِنَّ جُنْدَنَا لَهُمُ الْغَالِبُونَ﴾ مع وقوع أذى الرسل؟","answer":"النصر للعاقبة والحجة والرسالة، لا لسلامة كل فرد من كل ألم مؤقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص99–110.","url":""}]},{"id":"s37-50","number":50,"surah":37,"verses":[180,181,182],"verseLabel":"الصافات: 180-182","question":"ما سرّ ختم السورة بالتسبيح والسلام والحمد؟","answer":"نزه الله عن وصفهم، وسلم على رسله لإصابة وصفهم، وحمده على ظهور الحق والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص126–136.","url":""}]},{"id":"s38-1","number":1,"surah":38,"verses":[1],"verseLabel":"ص: 1","question":"لماذا افتتحت السورة بحرف ﴿ص﴾؟","answer":"تنبيه إلى إعجاز القرآن المؤلف من جنس هذه الحروف، والحرف يلائم اسم السورة وفاصلتها القوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص145–149.","url":""}]},{"id":"s38-2","number":2,"surah":38,"verses":[1],"verseLabel":"ص: 1","question":"لماذا أقسم بـ﴿الْقُرْآنِ ذِي الذِّكْرِ﴾؟","answer":"وصفه بالشرف والتذكير، فالمقسم به نفسه يرد غفلة المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص145–149.","url":""}]},{"id":"s38-3","number":3,"surah":38,"verses":[2],"verseLabel":"ص: 2","question":"لماذا لم يذكر جواب القسم صراحة وقال ﴿بَلِ الَّذِينَ كَفَرُوا فِي عِزَّةٍ وَشِقَاقٍ﴾؟","answer":"حذف الجواب ليفهم صدق القرآن من السياق، وانتقل إلى العلة النفسية للرفض: الكبر والمخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص150–154.","url":""}]},{"id":"s38-4","number":4,"surah":38,"verses":[3],"verseLabel":"ص: 3","question":"ما سرّ التعبير عن القرون الهالكة بقوله ﴿فَنَادَوْا وَلَاتَ حِينَ مَنَاصٍ﴾؟","answer":"جاء طلب النجاة بعد فوات وقتها؛ «لات» تنفي الزمن المناسب للفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص155–161.","url":""}]},{"id":"s38-5","number":5,"surah":38,"verses":[4],"verseLabel":"ص: 4","question":"لماذا عجبوا أن جاءهم منذر منهم؟","answer":"جعلوا معرفة بشرية الرسول موضع استبعاد، مع أنها أقرب للفهم والاقتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص162–169.","url":""}]},{"id":"s38-6","number":6,"surah":38,"verses":[5],"verseLabel":"ص: 5","question":"ما سرّ تعبيرهم بقولهم ﴿أَجَعَلَ الْآلِهَةَ إِلَهًا وَاحِدًا﴾؟","answer":"صوروا التوحيد تحويلًا غريبًا لأن كثرة المعبودات ألفتهم، لا لأن لها برهانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص170–174.","url":""}]},{"id":"s38-7","number":7,"surah":38,"verses":[6],"verseLabel":"ص: 6","question":"ما سرّ تعبير الملأ بقوله ﴿امْشُوا وَاصْبِرُوا عَلَى آلِهَتِكُمْ﴾؟","answer":"جعلوا الثبات على الباطل صبرًا، وأمروا بالحركة بعيدًا عن مجلس الحجة حتى لا يتأثر الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص175–180.","url":""}]},{"id":"s38-8","number":8,"surah":38,"verses":[7],"verseLabel":"ص: 7","question":"ما سرّ تعبيرهم بقولهم ﴿مَا سَمِعْنَا بِهَذَا فِي الْمِلَّةِ الْآخِرَةِ﴾؟","answer":"جعلوا حد علمهم وعادتهم ميزان الحقيقة، فردوا الجديد لمجرد أنه لا يوافق الموروث.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص181–188.","url":""}]},{"id":"s38-9","number":9,"surah":38,"verses":[8],"verseLabel":"ص: 8","question":"ما سرّ تعبيرهم بقولهم ﴿أَأُنْزِلَ عَلَيْهِ الذِّكْرُ مِنْ بَيْنِنَا﴾؟","answer":"كشف الاستفهام حسد الاختيار لا فحص الرسالة؛ اعترضوا على «من بيننا».","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص189–196.","url":""}]},{"id":"s38-10","number":10,"surah":38,"verses":[8],"verseLabel":"ص: 8","question":"ما سرّ التعبير بقوله ﴿بَلْ لَمَّا يَذُوقُوا عَذَابِ﴾؟","answer":"لم ينفعهم البيان لأن المانع جرأة لم تُكسر بعد؛ وسيحول الذوق الإنكار إلى يقين متأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص189–196.","url":""}]},{"id":"s38-11","number":11,"surah":38,"verses":[9],"verseLabel":"ص: 9","question":"لماذا سأل ﴿أَمْ عِنْدَهُمْ خَزَائِنُ رَحْمَةِ رَبِّكَ الْعَزِيزِ الْوَهَّابِ﴾؟","answer":"من لا يملك خزائن الرحمة لا يقرر موضع النبوة، والعزيز الوهاب يعطي بلا خضوع لمقاييسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص197–205.","url":""}]},{"id":"s38-12","number":12,"surah":38,"verses":[10],"verseLabel":"ص: 10","question":"ما سرّ التعبير بقوله ﴿فَلْيَرْتَقُوا فِي الْأَسْبَابِ﴾؟","answer":"تهكم بمن ينازع اختيار السماء: إن ملكوا السماوات فليصعدوا طرقها ويدبروا الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص197–205.","url":""}]},{"id":"s38-13","number":13,"surah":38,"verses":[11],"verseLabel":"ص: 11","question":"لماذا وصفهم ﴿جُنْدٌ مَا هُنَالِكَ مَهْزُومٌ مِنَ الْأَحْزَابِ﴾؟","answer":"حقّر جمعهم بـ«ما»، وأشار إلى موضع هزيمتهم قبل وقوعها تثبيتًا للرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص206–211.","url":""}]},{"id":"s38-14","number":14,"surah":38,"verses":[12],"verseLabel":"ص: 12","question":"لماذا وصف فرعون في سورة ص بـ﴿ذِي الْأَوْتَادِ﴾؟","answer":"اللفظ يصور رسوخ سلطانه وكثرة جنده وخيامه كالأوتاد، وقيل أوتاد عذابه التي يثبت بها من يعاقبه؛ وفي الوجهين إظهار قوة لم تمنع الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص212–224.","url":""}]},{"id":"s38-15","number":15,"surah":38,"verses":[13],"verseLabel":"ص: 13","question":"لماذا سمي المكذبون السابقون ﴿الْأَحْزَابُ﴾؟","answer":"اختلفت أزمانهم واجتمعوا في حزب مقاومة الرسل، فصار مصيرهم شاهدًا على الحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص212–224.","url":""}]},{"id":"s38-16","number":16,"surah":38,"verses":[15],"verseLabel":"ص: 15","question":"لماذا لا ينتظر هؤلاء إلا ﴿صَيْحَةً وَاحِدَةً مَا لَهَا مِنْ فَوَاقٍ﴾؟","answer":"صيحة لا تحتاج تكرارًا ولا مهلة رجوع؛ «فواق» مقدار قصير بين الحلبتين نُفي أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص225–231.","url":""}]},{"id":"s38-17","number":17,"surah":38,"verses":[16],"verseLabel":"ص: 16","question":"ما سرّ تعبيرهم بقولهم ﴿رَبَّنَا عَجِّلْ لَنَا قِطَّنَا قَبْلَ يَوْمِ الْحِسَابِ﴾؟","answer":"طلبوا نصيبهم من العذاب استهزاء، فسموه «قطًا» كصحيفة أو حصة موزعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص232–236.","url":""}]},{"id":"s38-18","number":18,"surah":38,"verses":[17],"verseLabel":"ص: 17","question":"ما سرّ توجيه الرسول بقوله ﴿اصْبِرْ عَلَى مَا يَقُولُونَ وَاذْكُرْ عَبْدَنَا دَاوُودَ ذَا الْأَيْدِ﴾؟","answer":"قدّم نموذجًا جمع القوة والرجوع إلى الله؛ الصبر ليس ضعفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص237–245.","url":""}]},{"id":"s38-19","number":19,"surah":38,"verses":[18,19],"verseLabel":"ص: 18-19","question":"لماذا سخرت الجبال والطير يسبحن مع داود؟","answer":"استجابت له أجسام عظيمة وأحياء طائرة، في مقابل قلوب بشرية استكبرت عن الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص246–257.","url":""}]},{"id":"s38-20","number":20,"surah":38,"verses":[20],"verseLabel":"ص: 20","question":"لماذا جمع لداود شد الملك والحكمة وفصل الخطاب؟","answer":"قوة السلطان تحتاج علمًا يحكم وبيانًا يفصل الخصومة، وإلا صارت بطشًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص258–263.","url":""}]},{"id":"s38-21","number":21,"surah":38,"verses":[21],"verseLabel":"ص: 21","question":"ما سرّ التعبير بقوله ﴿وَهَلْ أَتَاكَ نَبَأُ الْخَصْمِ إِذْ تَسَوَّرُوا الْمِحْرَابَ﴾؟","answer":"الاستفهام يشوق، و«تسوروا» يفسر فزع داود من دخول غير مألوف إلى موضع عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص264–272.","url":""}]},{"id":"s38-22","number":22,"surah":38,"verses":[22],"verseLabel":"ص: 22","question":"ما سرّ قول الخصمين ﴿لَا تَخَفْ﴾ قبل عرض القضية؟","answer":"أزالا أثر المفاجأة ليتهيأ القاضي لسماع الحجة بعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص273–284.","url":""}]},{"id":"s38-23","number":23,"surah":38,"verses":[23],"verseLabel":"ص: 23","question":"ما سرّ تعبير صاحب النعجة بقوله ﴿وَعَزَّنِي فِي الْخِطَابِ﴾؟","answer":"غلبه بقوة البيان والمكانة، فتكشف أن الظلم قد يقع بالكلمة قبل اليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص285–291.","url":""}]},{"id":"s38-24","number":24,"surah":38,"verses":[24],"verseLabel":"ص: 24","question":"لماذا استغفر داود وخر راكعًا وأناب؟","answer":"فهم أن الخصومة اختبار له في سرعة الحكم أو شأن آخر، فبادر بالرجوع دون مكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص292–307.","url":""}]},{"id":"s38-25","number":25,"surah":38,"verses":[25],"verseLabel":"ص: 25","question":"ما سرّ التعبير بقوله ﴿فَغَفَرْنَا لَهُ ذَلِكَ وَإِنَّ لَهُ عِنْدَنَا لَزُلْفَى وَحُسْنَ مَآبٍ﴾؟","answer":"لم تكتف المغفرة بمحو العثرة؛ أثبتت قربه وحسن مرجعه كيلا تحجب الزلة مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص308–314.","url":""}]},{"id":"s38-26","number":26,"surah":38,"verses":[26],"verseLabel":"ص: 26","question":"ما سرّ التعبير بقوله ﴿يَا دَاوُودُ إِنَّا جَعَلْنَاكَ خَلِيفَةً فِي الْأَرْضِ﴾ بعد الخصومة؟","answer":"حوّل الدرس الفردي إلى قاعدة حكم: العدل وترك الهوى أساس الاستخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص315–329.","url":""}]},{"id":"s38-27","number":27,"surah":38,"verses":[27],"verseLabel":"ص: 27","question":"ما سرّ التعبير بقوله ﴿وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ... بَاطِلًا﴾؟","answer":"انتقل من عدل القاضي إلى عدل الكون؛ الخلق بلا حساب يجعل الوجود عبثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص330–341.","url":""}]},{"id":"s38-28","number":28,"surah":38,"verses":[28],"verseLabel":"ص: 28","question":"لماذا سأل ﴿أَمْ نَجْعَلُ الَّذِينَ آمَنُوا... كَالْمُفْسِدِينَ﴾؟","answer":"استحالة التسوية الأخروية فرع عن حكمة الخلق؛ العدل يميز الطريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص342–352.","url":""}]},{"id":"s38-29","number":29,"surah":38,"verses":[29],"verseLabel":"ص: 29","question":"لماذا وصف القرآن بأنه ﴿كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ﴾؟","answer":"بركته لا تظهر بمجرد التلاوة؛ التدبر يعبر إلى المعنى، والتذكر يحوله عملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص353–364.","url":""}]},{"id":"s38-30","number":30,"surah":38,"verses":[30],"verseLabel":"ص: 30","question":"ما سرّ التعبير عن سليمان بقوله ﴿نِعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ﴾ مع عظم ملكه؟","answer":"أعلى ألقابه العبودية وكثرة الرجوع، لا اتساع السلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص365–372.","url":""}]},{"id":"s38-31","number":31,"surah":38,"verses":[31],"verseLabel":"ص: 31","question":"لماذا عرضت عليه ﴿الصَّافِنَاتُ الْجِيَادُ﴾ بالعشي؟","answer":"خيول قوية جميلة تهيأ للجهاد، واختبار أن لا تشغله الوسيلة عن ذكر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص373–379.","url":""}]},{"id":"s38-32","number":32,"surah":38,"verses":[32],"verseLabel":"ص: 32","question":"ما سرّ التعبير بقوله ﴿إِنِّي أَحْبَبْتُ حُبَّ الْخَيْرِ عَنْ ذِكْرِ رَبِّي﴾؟","answer":"سمى الخيل خيرًا، واعترف بأن محبتها جاوزت به وقت الذكر أو كانت لأجله بحسب التفسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص380–390.","url":""}]},{"id":"s38-33","number":33,"surah":38,"verses":[34],"verseLabel":"ص: 34","question":"لماذا ألقي على كرسي سليمان جسد ثم أناب؟","answer":"ابتلاء كسر تعلقه بالأسباب أو تعلق أمله بولد، فرد الملك إلى واهبه؛ وتفاصيل الروايات غير الثابتة لا يعتمد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص398–404.","url":""}]},{"id":"s38-34","number":34,"surah":38,"verses":[35],"verseLabel":"ص: 35","question":"لماذا طلب سليمان ملكًا لا ينبغي لأحد من بعده؟","answer":"سأل آية خاصة تثبت نبوته وتناسب رسالته، لا مجرد تنافس دنيوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص405–415.","url":""}]},{"id":"s38-35","number":35,"surah":38,"verses":[36],"verseLabel":"ص: 36","question":"لماذا سخرت له الريح ﴿تَجْرِي بِأَمْرِهِ رُخَاءً حَيْثُ أَصَابَ﴾؟","answer":"جمعت طاعتها ولينها ودقة اتجاهها؛ قوة بلا اضطراب تحت أمر مأذون.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص416–429.","url":""}]},{"id":"s38-36","number":36,"surah":38,"verses":[38],"verseLabel":"ص: 38","question":"ما سرّ التعبير عن الشياطين بقوله ﴿وَآخَرِينَ مُقَرَّنِينَ فِي الْأَصْفَادِ﴾؟","answer":"من لم يعمل في البناء والغوص كف شره بالقيد، فتم سلطان الضبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص416–429.","url":""}]},{"id":"s38-37","number":37,"surah":38,"verses":[39],"verseLabel":"ص: 39","question":"ما سرّ التعبير بقوله ﴿هَذَا عَطَاؤُنَا فَامْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ﴾؟","answer":"فوض له التصرف في ذلك العطاء بلا مؤاخذة على البذل والإمساك المشروع، ثقة بحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص430–437.","url":""}]},{"id":"s38-38","number":38,"surah":38,"verses":[41],"verseLabel":"ص: 41","question":"ما سرّ تعبير أيوب بقوله ﴿أَنِّي مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ﴾؟","answer":"أدبًا نسب الوسوسة وما جرته من ألم للشيطان، وعرض البلاء بلا شكوى متسخطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص444–453.","url":""}]},{"id":"s38-39","number":39,"surah":38,"verses":[42],"verseLabel":"ص: 42","question":"ما سرّ الأمر لأيوب بقوله ﴿ارْكُضْ بِرِجْلِكَ هَذَا مُغْتَسَلٌ بَارِدٌ وَشَرَابٌ﴾؟","answer":"أمر بحركة يسيرة فجعل الله منها سبب علاج الظاهر والباطن بالماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص454–459.","url":""}]},{"id":"s38-40","number":40,"surah":38,"verses":[43],"verseLabel":"ص: 43","question":"ما سرّ التعبير في قصة أيوب بـ﴿رَحْمَةً مِنَّا﴾، وفي الأنبياء بـ﴿رَحْمَةً مِنْ عِنْدِنَا﴾؟","answer":"«من عندنا» تناسب إبراز مصدر الكشف والعطاء هناك، و«منا» أوجز مع سياق تعداد المنن هنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص460–480.","url":""}]},{"id":"s38-41","number":41,"surah":38,"verses":[44],"verseLabel":"ص: 44","question":"لماذا أمر أيوب أن يأخذ ضغثًا فيضرب به ولا يحنث؟","answer":"جمع الوفاء باليمين والرفق بمن حلف على ضربها، فخرج من الحرج بلا ظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص460–480.","url":""}]},{"id":"s38-42","number":42,"surah":38,"verses":[45],"verseLabel":"ص: 45","question":"لماذا وصف إبراهيم وإسحاق ويعقوب بأنهم ﴿أُولِي الْأَيْدِي وَالْأَبْصَارِ﴾؟","answer":"الأيدي قوة العمل، والأبصار نفاذ العلم؛ كمال الإنسان في بصيرة منتجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص481–496.","url":""}]},{"id":"s38-43","number":43,"surah":38,"verses":[46],"verseLabel":"ص: 46","question":"لماذا أخلصوا ﴿بِخَالِصَةٍ ذِكْرَى الدَّارِ﴾؟","answer":"صفا مقصدهم بتذكر الآخرة والدعوة إليها، فلم تستغرقهم الدار العاجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص481–496.","url":""}]},{"id":"s38-44","number":44,"surah":38,"verses":[49],"verseLabel":"ص: 49","question":"ما سرّ التعبير بعد قصص الأنبياء بقوله ﴿هَذَا ذِكْرٌ﴾؟","answer":"وقف السرد ليعلن أن المقصود تذكر القدوة، ثم انتقل إلى جزاء المتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص503–524.","url":""}]},{"id":"s38-45","number":45,"surah":38,"verses":[50],"verseLabel":"ص: 50","question":"ما سرّ التعبير عن جنات عدن بقوله ﴿مُفَتَّحَةً لَهُمُ الْأَبْوَابُ﴾؟","answer":"جاءت الأبواب مفتوحة قبل وصولهم إكرامًا وأمنًا من المنع والانقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص503–524.","url":""}]},{"id":"s38-46","number":46,"surah":38,"verses":[55],"verseLabel":"ص: 55","question":"لماذا انتقل فجأة بـ﴿هَذَا وَإِنَّ لِلطَّاغِينَ لَشَرَّ مَآبٍ﴾؟","answer":"قطع مشهد النعيم ليضع المصير المقابل أمام العين ويمنع سماع الوعد منفصلًا عن الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص535–554.","url":""}]},{"id":"s38-47","number":47,"surah":38,"verses":[57],"verseLabel":"ص: 57","question":"ما سرّ التعبير بقوله ﴿هَذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ﴾؟","answer":"اسم الإشارة يقرب العذاب، والأمر بالذوق يسخر من لذات طلبوها؛ الحميم حار والغساق مؤذٍ بارد أو منتن.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص535–554.","url":""}]},{"id":"s38-48","number":48,"surah":38,"verses":[59],"verseLabel":"ص: 59","question":"لماذا يتلاعن أهل النار عند دخول كل فوج؟","answer":"انقلبت روابط القيادة والاتباع عداوة، فلا مرحبًا بالداخل ولا راحة بالسابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص555–577.","url":""}]},{"id":"s38-49","number":49,"surah":38,"verses":[62],"verseLabel":"ص: 62","question":"ما دلالة قولهم ﴿مَا لَنَا لَا نَرَى رِجَالًا كُنَّا نَعُدُّهُمْ مِنَ الْأَشْرَارِ﴾؟","answer":"انقلب الميزان: من احتقروهم غابوا عن النار، فشكوا متأخرين في حكمهم وسخريتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص578–599.","url":""}]},{"id":"s38-50","number":50,"surah":38,"verses":[67],"verseLabel":"ص: 67","question":"ما سرّ التعبير بقوله ﴿قُلْ هُوَ نَبَأٌ عَظِيمٌ * أَنْتُمْ عَنْهُ مُعْرِضُونَ﴾؟","answer":"سمى الوحي والمصير خبرًا عظيمًا، وجعل المشكلة إعراضهم عنه لا خفاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص616–623.","url":""}]},{"id":"s38-51","number":51,"surah":38,"verses":[69],"verseLabel":"ص: 69","question":"ما دلالة قول النبي ﴿مَا كَانَ لِيَ مِنْ عِلْمٍ بِالْمَلَإِ الْأَعْلَى إِذْ يَخْتَصِمُونَ﴾؟","answer":"معرفته بحوار الملائكة وإبليس دليل وحي لا خبرة بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص624–634.","url":""}]},{"id":"s38-52","number":52,"surah":38,"verses":[72],"verseLabel":"ص: 72","question":"ما سرّ التعبير في شأن آدم بقوله ﴿فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِنْ رُوحِي فَقَعُوا لَهُ سَاجِدِينَ﴾؟","answer":"قدم تمام الخلق والتشريف بالنفخ قبل أمر السجود، وإضافة الروح للتكريم لا التجزؤ.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص635–648.","url":""}]},{"id":"s38-53","number":53,"surah":38,"verses":[74],"verseLabel":"ص: 74","question":"ما سرّ التعبير بقوله ﴿إِلَّا إِبْلِيسَ اسْتَكْبَرَ وَكَانَ مِنَ الْكَافِرِينَ﴾؟","answer":"لم يكن مجرد ترك حركة؛ دافعه الكبر وكشف الفعل ما استقر من الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص649–656.","url":""}]},{"id":"s38-54","number":54,"surah":38,"verses":[75],"verseLabel":"ص: 75","question":"ما سرّ التعبير الإلهي بقوله ﴿مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ﴾؟","answer":"تشريف خاص لخلق آدم على الوجه اللائق بالله، وتوبيخ لمن عارض الأمر بقياسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص657–669.","url":""}]},{"id":"s38-55","number":55,"surah":38,"verses":[76],"verseLabel":"ص: 76","question":"لماذا احتج إبليس بأنه من نار وآدم من طين؟","answer":"قاس المادة وأغفل أمر الخالق ووظيفة المخلوق؛ قياس الكبر ينتقي وصفًا ويترك الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص670–678.","url":""}]},{"id":"s38-56","number":56,"surah":38,"verses":[82],"verseLabel":"ص: 82","question":"لماذا أقسم إبليس ﴿فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ﴾؟","answer":"اعترف بعزة الله واستعمل القسم بها في تحدي أمره؛ علم بلا عبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص688–694.","url":""}]},{"id":"s38-57","number":57,"surah":38,"verses":[83],"verseLabel":"ص: 83","question":"لماذا استثنى ﴿عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ﴾؟","answer":"أقر أن الإخلاص الذي يصطفي الله به عباده حصن لا يملكه الإغواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص688–694.","url":""}]},{"id":"s38-58","number":58,"surah":38,"verses":[86],"verseLabel":"ص: 86","question":"ما دلالة قول الرسول ﴿وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ﴾؟","answer":"نَفى طلب أجر وادعاء ما ليس له؛ رسالته وحي على السجية لا صناعة متصنعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص711–734.","url":""}]},{"id":"s38-59","number":59,"surah":38,"verses":[87,88],"verseLabel":"ص: 87-88","question":"لماذا ختمت السورة بـ﴿إِنْ هُوَ إِلَّا ذِكْرٌ لِلْعَالَمِينَ * وَلَتَعْلَمُنَّ نَبَأَهُ بَعْدَ حِينٍ﴾؟","answer":"قصر القرآن على التذكير العام، ووعد أن يتحول خبره إلى يقين واقع ولو بعد مهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص711–734.","url":""}]},{"id":"s39-1","number":1,"surah":39,"verses":[1],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الزمر»، وما صلة الاسم بمشهد سوق الفريقين في خاتمتها؟","answer":"سميت بالزمر لاستحضار سوق الفريقين جماعات إلى مصيرهما؛ فالاسم يلخص حركة السورة من إخلاص الدين والاختيار إلى الجزاء الجامع في خاتمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص737–744؛ ج50، ص794–823؛ ج51، ص1–19.","url":""}]},{"id":"s39-2","number":2,"surah":39,"verses":[1],"verseLabel":"الزمر: 1","question":"ما سر افتتاح السورة بجملة ﴿تَنْزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ﴾؟","answer":"الافتتاح يعلن أن الكتاب منزل من الله وحده، وأن مصدره عزيز لا يغلب وحكيم يضع الوحي موضعه؛ فيقيم أصل التوحيد الذي تبني عليه السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص744–757.","url":""}]},{"id":"s39-3","number":3,"surah":39,"verses":[1],"verseLabel":"الزمر: 1","question":"ما مناسبة تقديم ﴿الْعَزِيزِ﴾ على ﴿الْحَكِيمِ﴾ في مصدر التنزيل؟","answer":"العزة تضمن نفاذ التنزيل وقهر معارضيه، والحكمة تضمن إحكامه ووضعه في مواضعه؛ فقدم ما يناسب مواجهة الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص753–757.","url":""}]},{"id":"s39-4","number":4,"surah":39,"verses":[2],"verseLabel":"الزمر: 2","question":"ما سر اختيار ﴿أَنْزَلْنَا إِلَيْكَ الْكِتَابَ﴾ بعد قوله ﴿تَنْزِيلُ الْكِتَابِ﴾؟","answer":"﴿تَنْزِيلُ﴾ يقرر جنس الوحي ومصدره، ثم ﴿أَنْزَلْنَا إِلَيْكَ﴾ يوجه الخطاب إلى الرسول ويصل الحقيقة العامة بمهمته في البلاغ والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص758–764.","url":""}]},{"id":"s39-5","number":5,"surah":39,"verses":[2,3],"verseLabel":"الزمر: 2–3","question":"ما دلالة الانتقال من أمر الرسول ﷺ بإخلاص الدين لله إلى تقرير ﴿أَلَا لِلَّهِ الدِّينُ الْخَالِصُ﴾؟","answer":"بدأ بتكليف الرسول ليكون القدوة العملية، ثم عمم الحكم بأن الدين الخالص حق لله وحده؛ فانتقل من الامتثال الفردي إلى الأصل الكلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص764–779.","url":""}]},{"id":"s39-6","number":6,"surah":39,"verses":[3],"verseLabel":"الزمر: 3","question":"ما دلالة حكاية قول المشركين ﴿مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى﴾؟","answer":"الحكاية تكشف أنهم لم ينكروا الله، بل جعلوا الوسائط طريقًا مزعومًا إليه؛ ففضحت الآية أن التقرب الذي يبنى على عبادة غيره هو عين الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص777–789.","url":""}]},{"id":"s39-7","number":7,"surah":39,"verses":[3],"verseLabel":"الزمر: 3","question":"ما سر الجمع بين وصفي ﴿كَاذِبٌ كَفَّارٌ﴾ وتقديم الكذب؟","answer":"الكذب وصف دعوى الوساطة والولد، والكفّار يدل على شدة الجحود وتكرره؛ فقدم فساد القول ثم كشف رسوخ صاحبه فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص789–795.","url":""}]},{"id":"s39-8","number":8,"surah":39,"verses":[4],"verseLabel":"الزمر: 4","question":"ما دلالة إقامة الحجة الافتراضية في ﴿لَوْ أَرَادَ اللَّهُ أَنْ يَتَّخِذَ وَلَدًا لَاصْطَفَى﴾؟","answer":"التنزل الجدلي يبطل مقالتهم من أصلها: فلو فرض اتخاذ الولد ـ وهو منزه عنه ـ لكان الاصطفاء لله لا ما عينه المشركون بأهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص797–806.","url":""}]},{"id":"s39-9","number":9,"surah":39,"verses":[4],"verseLabel":"الزمر: 4","question":"ما مناسبة ختم نفي الولد بقوله ﴿هُوَ اللَّهُ الْوَاحِدُ الْقَهَّارُ﴾؟","answer":"الواحد ينفي كل شريك وولد، والقهار يدل على خضوع الخلق له؛ فمن قهر الجميع لا يكون أحد منهم جزءًا منه ولا ندًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج49، ص805–810.","url":""}]},{"id":"s39-10","number":10,"surah":39,"verses":[5],"verseLabel":"الزمر: 5","question":"ما سر اختيار التكوير في تصوير تعاقب الليل والنهار؟","answer":"التكوير لف الشيء على الشيء، فصور دخول الليل على النهار والنهار على الليل في تعاقب متصل محكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص10–22.","url":""}]},{"id":"s39-11","number":11,"surah":39,"verses":[5],"verseLabel":"الزمر: 5","question":"ما دلالة الجمع بين تكوير الليل والنهار وتسخير الشمس والقمر لجريان إلى أجل مسمى؟","answer":"تعاقب الليل والنهار يبين نظام الأرض، وجريان الشمس والقمر يبين نظام الأجرام؛ وجميعها مسخرة إلى أجل ينتهي عنده هذا العالم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص17–32.","url":""}]},{"id":"s39-12","number":12,"surah":39,"verses":[6],"verseLabel":"الزمر: 6","question":"ما سر التعبير بـ﴿وَأَنْزَلَ لَكُمْ مِنَ الْأَنْعَامِ ثَمَانِيَةَ أَزْوَاجٍ﴾ مع أن الأنعام لا تنزل من السماء؟","answer":"يأتي الإنزال بمعنى الإيجاد والتقدير، وقيل لما كانت أسباب حياة الأنعام ورزقها من السماء؛ فلا يلزم منه نزول ذواتها كنزول المطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص35–62.","url":""}]},{"id":"s39-13","number":13,"surah":39,"verses":[6],"verseLabel":"الزمر: 6","question":"ما سر الانتقال من خلق النفس الواحدة وزوجها إلى ذكر الأنعام ثم خلق الإنسان في بطن أمه؟","answer":"جمع أصل الإنسان وتكاثره، وما سخر له من الأنعام، ثم عاد إلى خلقه الخفي؛ فدل على وحدة التدبير في الإنسان ورزقه وتكوينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص35–54.","url":""}]},{"id":"s39-14","number":14,"surah":39,"verses":[6],"verseLabel":"الزمر: 6","question":"ما دلالة تصوير أطوار الجنين بأنها ﴿خَلْقًا مِنْ بَعْدِ خَلْقٍ فِي ظُلُمَاتٍ ثَلَاثٍ﴾؟","answer":"التعبير يرسم تحولًا متتابعًا لا دفعة واحدة، داخل طبقات مستورة؛ فيبرز دقة القدرة حيث لا يرى الخلق ولا يملكون التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص49–57.","url":""}]},{"id":"s39-15","number":15,"surah":39,"verses":[6],"verseLabel":"الزمر: 6","question":"ما مناسبة ختم دلائل الخلق بقوله ﴿ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ﴾؟","answer":"بعد تفصيل الخلق عرّف فاعله: ذلكم هو الله المربي والمالك؛ فصارت النعم المشاهدة دليلًا على انفراده بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص55–63.","url":""}]},{"id":"s39-16","number":16,"surah":39,"verses":[7],"verseLabel":"الزمر: 7","question":"ما دلالة الجمع بين غنى الله عن الناس وعدم رضاه الكفر لعباده؟","answer":"غناه ينفي أن يعود عليه نفع الإيمان أو ضرر الكفر، وعدم رضاه بالكفر يثبت رحمته وحكمته؛ فهو يأمر العباد بما يصلحهم لا لحاجة إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص63–76.","url":""}]},{"id":"s39-17","number":17,"surah":39,"verses":[7],"verseLabel":"الزمر: 7","question":"ما مناسبة تقرير ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾ لسياق الكفر والشكر والرجوع إلى الله؟","answer":"ما دام كل إنسان يحمل اختياره وحده ويرجع إلى الله، فلا ينفع تبرير الكفر باتباع غيره؛ فقررت الآية فردية المسؤولية مع علم الله بالسرائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص76–87.","url":""}]},{"id":"s39-18","number":18,"surah":39,"verses":[8],"verseLabel":"الزمر: 8","question":"ما دلالة تدرج حال الإنسان من مس الضر ودعاء ربه منيبًا إلى نسيان ما دعا إليه واتخاذ الأنداد؟","answer":"بدأ بالإنابة الصادقة عند العجز، ثم كشف النسيان بعد النعمة، وانتهى بصنع الأنداد؛ فتدرج من معرفة الفطرة إلى جحودها وإضلال الغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص87–112.","url":""}]},{"id":"s39-19","number":19,"surah":39,"verses":[8],"verseLabel":"الزمر: 8","question":"ما سر اختيار ﴿خَوَّلَهُ نِعْمَةً﴾ بدل «أعطاه نعمة»؟","answer":"التخويل إعطاء مع تمكين وتوسعة، فيوحي بأن النعمة عهد واختبار تحت تصرف المنعم، لا ملكًا مستقلًا لصاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص97–103.","url":""}]},{"id":"s39-20","number":20,"surah":39,"verses":[9],"verseLabel":"الزمر: 9","question":"ما دلالة تصوير القانت بأنه يقوم آناء الليل ساجدًا وقائمًا يحذر الآخرة ويرجو رحمة ربه؟","answer":"جمع دوام الطاعة في ساعات الليل وهيئتي السجود والقيام، ثم خوف الحساب ورجاء الرحمة؛ فصور عبادة تستغرق الجسد والقلب والزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص113–131.","url":""}]},{"id":"s39-21","number":21,"surah":39,"verses":[9],"verseLabel":"الزمر: 9","question":"ما سر تقديم الحذر من الآخرة على رجاء رحمة الله؟","answer":"قدم الحذر لأن السياق يواجه الغافل المعرض، ثم أتبع بالرجاء حتى يبقى القانت بين خوف يردعه ورحمة تجذبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج50، ص126–130.","url":""}]}]);
